function companyView(){let c=company(companyId);if(!c)return companies();return head(c.name,'Expediente empresarial',B('Editar empresa',`companyDialog(${arg(c.id)})`,'')+B('+ Proyecto',`projectDialog(${arg(c.id)})`)+B('Resumen integral ZIP',`companyExportDialog(${arg(c.id)},'client')`)+B('Proveedor · RFQ',`companyExportDialog(${arg(c.id)},'supplier')`)+B('Respaldo empresarial',`backupCompany(${arg(c.id)})`))+panel('Información de contacto',`<div class="fields">${[['Tipo',c.type],['Comercial',c.commercial],['Representante',c.contact],['Cargo',c.role],['Teléfono',c.phone],['Correo',c.email],['Dirección',c.address],['Identificación fiscal',c.tax]].map(([k,v])=>`<div><small>${k}</small><p>${E(v||'Por registrar')}</p></div>`).join('')}</div>`)+panel('Contactos adicionales',`<div class="scroll"><table><tr><th>Nombre</th><th>Cargo</th><th>Teléfono / correo</th><th></th></tr>${c.contacts.map((r,i)=>`<tr>${['name','role','contact'].map(k=>`<td><input value="${E(r[k])}" oninput="editContact(${i},'${k}',this.value)"></td>`).join('')}<td>${B('Quitar',`removeContact(${i})`,'danger small')}</td></tr>`).join('')}</table></div>${B('+ Contacto','addContact()')}`)+panel('Proyectos asociados',`<div class="grid projectgrid">${pageCards(state.projects.filter(p=>p.companyId===c.id),'companyProjects:'+c.id,projectCard)||empty('Sin proyectos')}</div>`)}
function addContact(){company(companyId).contacts.push({});touch();render()}function editContact(i,k,v){company(companyId).contacts[i][k]=v;touch()}function removeContact(i){company(companyId).contacts.splice(i,1);touch();render()}
function modal(title,body,onSubmit,saveLabel='Guardar'){let d=$('dialog');d.innerHTML=`<div class="row between"><h2>${E(title)}</h2>${B('✕',"$('dialog').close()",'secondary small')}</div><form id="modalForm">${body}<div class="actions" style="justify-content:flex-end">${B('Cancelar',"$('dialog').close()") }<button type="submit">${E(saveLabel)}</button></div></form>`;d.showModal();$('modalForm').onsubmit=e=>{e.preventDefault();let form=e.target,submit=form.querySelector('[type=submit]'),result;try{result=onSubmit(new FormData(form))}catch(err){toast(err.message);return}if(result&&typeof result.then==='function'){if(submit)submit.disabled=true;result.then(v=>{if(v!==false&&d.open&&$('modalForm')===form)d.close()}).catch(err=>toast(err.message)).finally(()=>{if(submit)submit.disabled=false})}else if(result!==false&&d.open&&$('modalForm')===form)d.close()}}
function companyDialog(id,continueProject=false){let c=id?company(id):newCompany();modal(id?'Editar empresa':'Registrar empresa',`<div class="fields">${mfield('Razón social','name',c.name,'text',true)}${mfield('Nombre comercial','commercial',c.commercial)}<label class="field">Tipo<select name="type">${['Empresa estatal','Empresa privada'].map(t=>`<option ${t===c.type?'selected':''}>${t}</option>`).join('')}</select>${help('type')}</label>${[['Categoría empresarial','category'],['Identificación fiscal','tax'],['Provincia','province'],['Municipio','municipality'],['Dirección','address'],['Representante','contact'],['Cargo','role'],['Teléfono / WhatsApp','phone'],['Correo','email']].map(([l,k])=>k==='category'?modalSelect(l,k,c[k],categories):k==='province'||k==='municipality'?territoryField(k,c):mfield(l,k,c[k],k==='email'?'email':'text')).join('')}</div><label class="field">Observaciones internas<textarea name="notes" placeholder="Ej. Coordinar la visita con mantenimiento">${E(c.notes)}</textarea><small class="field-help">Anotaciones internas para coordinar el trabajo con el cliente.</small></label>`,f=>{let o=Object.fromEntries(f);if(!o.name.trim())return false;Object.assign(c,o);if(!id)state.companies.push(c);touch();if(!project())showCompany(c.id);else render();if(continueProject)setTimeout(()=>projectDialog(c.id),0)})}
