function editProject(id){let p=state.projects.find(x=>x.id===id);modal('Editar identidad del proyecto',`<div class="fields">${mfield('Nombre','name',p.name,'text',true)}${typeSelect(p.type)}<label class="field">Estado<select name="status">${statuses.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select>${help('status')}</label><label class="field">Viabilidad técnica<select name="viabilityStatus">${viabilityStates.map(v=>`<option ${v===projectViabilityStatus(p)?'selected':''}>${E(v)}</option>`).join('')}</select></label></div><label class="field">Motivo de viabilidad<textarea name="viabilityRationale">${E(p.viability?.rationale||'')}</textarea></label><label class="field">Condiciones pendientes<textarea name="viabilityConditions">${E(p.viability?.conditions||'')}</textarea></label><label class="field">Objetivo<textarea name="objective">${E(p.objective)}</textarea><small class="field-help">Necesidad que debe resolver la solución energética.</small></label>`,f=>{let data=Object.fromEntries(f),vstatus=data.viabilityStatus||'Sin evaluar',reason=data.viabilityRationale||'',conditions=data.viabilityConditions||'';delete data.viabilityStatus;delete data.viabilityRationale;delete data.viabilityConditions;let changed=JSON.stringify([projectViabilityStatus(p),p.viability?.rationale||'',p.viability?.conditions||''])!==JSON.stringify([vstatus,reason,conditions]);let stamp=now();Object.assign(p,data,{updated:stamp});p.viability={status:vstatus,rationale:reason,conditions,assessedBy:changed?(me?.username||'Usuario local'):(p.viability?.assessedBy||''),assessedAt:changed&&vstatus!=='Sin evaluar'?stamp:(p.viability?.assessedAt||''),reviewedUpdated:changed&&vstatus!=='Sin evaluar'?stamp:(p.viability?.reviewedUpdated||'')};touch();render()})}
function resetCommercialCopy(q){q.revisions=[];q.reportHistory=[];q.preferred=false;for(let s of q.sites||[]){s.commercialOffers=[];s.supplierQuotes=[];s.quoteCostHistory=[];delete s.oemReviews;delete s.oemReviewHistory;if(s.privateFinance)s.privateFinance.confirmed=false;for(let c of Object.values(s.materialCosts||{})){if(c.quoteId){delete c.quoteId;delete c.quoteSignature;c.cost='';}}}return q;}
function duplicate(id,alternative){let p=state.projects.find(p=>p.id===id);modal(alternative?'Crear alternativa de diseño':'Duplicar proyecto',`<p>${alternative?'Crea otro diseño relacionado con esta empresa. No cambia el original. Las ofertas emitidas y solicitudes de fábrica permanecen en el original; reconfirma los costos en la copia.':'Crea una copia independiente del expediente actual sin transferir ofertas emitidas ni solicitudes de fábrica. Reconfirma los costos.'}</p>`+mfield('Nombre de la copia','name',p.name+(alternative?' · alternativa':' · copia'),'text',true)+mfield('Etiqueta de versión','version',alternative?'Alternativa optimizada':'Revisión 1','text',true),f=>{let q=resetCommercialCopy(copy(p));Object.assign(q,Object.fromEntries(f),{id:uid(),parentId:alternative?p.id:'',status:'Borrador',created:now(),updated:now(),revisions:[],reportHistory:[]});state.projects.push(q);touch();openProject(q.id)})}
function archiveProject(id){let p=state.projects.find(p=>p.id===id);p.status=p.status==='Archivado'?'Borrador':'Archivado';touch();render()}
