function overview(){let p=project(),s=site();return `<div class="hero"><div><div class="eyebrow">${E(cname(p))} / ${E(s.name)}</div><h1>${E(p.name)}</h1><p>${E(p.objective||'Define el objetivo del proyecto.')}</p><small>${E(p.status)} · ${E(p.version)} · ${E(p.type)}</small></div><div class="actions">${B('Editar identidad',`editProject(${arg(p.id)})`)}${B('Vista cliente',"sub('export')")}</div></div><div id="keyMetrics" class="grid">${keyMetrics(s)}</div>${panel('Alcance e instalaciones',`<div class="row between"><div><small>Instalación activa</small><h3>${E(s.name)}</h3></div>${B('+ Sucursal','siteDialog()')}</div><div class="fields" style="margin-top:10px">${field('Nombre de instalación','name',s.name)}${select('Estado del proyecto','status',p.status,statuses,'setProject')}</div><div class="fields" style="margin-top:15px">${MOD.map(([m,d])=>`<label class="check"><input type="checkbox" ${s.modules.includes(m)?'checked':''} onchange="toggleModule(${arg(m)},this.checked)"><span><b>${E(m)}</b><br><small>${E(moduleDetails[m]||d)}</small></span></label>`).join('')}</div>`)}${p.sites.length>1?panel('Consolidado de instalaciones',siteComparison(p.sites)):''}<h2>Expediente técnico de esta instalación</h2><div class="grid">${SUB.slice(1).map(([k,g,t,d])=>`<article class="tile"><span class="glyph">${g}</span><h3>${E(t)}</h3><p>${E(d)}</p>${B('Abrir sección',`sub('${k}')`,'open')}</article>`).join('')}</div>`}
function siteDialog(){modal('Agregar instalación',mfield('Nombre de sede o sucursal','name','','text',true),f=>{let s=emptySite(f.get('name').trim());s.modules=[...site().modules];project().sites.push(s);sid=s.id;touch();render()})}
function surveyBase(){let s=site();return head('Levantamiento técnico','Mediciones y condiciones reales. Los datos iniciales son supuestos editables.')+panel('Datos eléctricos',`<div class="fields">${select('Estado de los datos','surveyStatus',s.surveyStatus||'Pendiente de verificar',['Pendiente de verificar','Estimado','Medido'])}${field('Dirección de la instalación','location',s.location)}${field('Tensión nominal (V)','voltage',s.voltage,'setSite','number')}${select('Número de fases','phases',String(s.phases),['1','2','3'],'setSite')}${field('Frecuencia (Hz)','frequency',s.frequency,'setSite','number')}${field('Potencia máxima disponible de la red (kW)','gridLimit',s.gridLimit,'setSite','number')}</div>${textField('Mediciones de red, protecciones existentes y conexión','gridNotes',s.gridNotes)}`)+panel('Condiciones de campo',textField('Cubierta, dimensiones, estructura, sombras y accesos','roof',s.roof)+textField('Riesgos, combustibles, incendios y condiciones ambientales','risks',s.risks)+textField('Observaciones y tareas de verificación','notes',s.notes))}
function rowTable(k,cols,items=site()[k]){let key='rows:'+site()?.id+':'+k,list=items.map((r,i)=>({r,i})),paged=['loads','materials','tasks','budget'].includes(k);let shown=paged?pageSlice(list,key,15):list;return `<div class="scroll"><table><thead><tr>${cols.map(c=>`<th>${E(c[1])}</th>`).join('')}<th></th></tr></thead><tbody>${shown.map(({r,i})=>`<tr>${cols.map(([f,l,t])=>f==='priority'?`<td><select aria-label="Prioridad" onchange="editRow('${k}',${i},'priority',this.value,false)">${[...new Set([r[f],...priorities])].filter(Boolean).map(v=>`<option ${v===r[f]?'selected':''}>${E(v)}</option>`).join('')}</select></td>`:`<td><input type="${t||'text'}" ${t==='number'?'min="0" step="any"':''} value="${E(r[f])}" aria-label="${E(l)}" oninput="editRow('${k}',${i},'${f}',this.value,${t==='number'})"></td>`).join('')}<td>${k==='materials'?B('Ficha',`materialSpecDialog(null,${i})`,'small'):k==='loads'?B('Ficha',`loadSourceDialog(${i})`,'small'):''}${B('×',`removeRow('${k}',${i})`,'danger small')}</td></tr>`).join('')}</tbody></table></div>${paged?pageControls(list,key,15):''}${k==='loads'?'':B(k==='outages'?'+ Agregar otro apagón':'+ Agregar fila',`addRow('${k}')`)}`}
function editRow(k,i,f,v,n){let z=n?Math.max(0,Number(v)||0):v;if(n&&['loads','outages'].includes(k)){if(f==='start')z=Math.min(23,z);if(f==='hours')z=Math.min(24,z);if(f==='sim')z=Math.min(100,z)}site()[k][i][f]=z;touch()}
function removeRow(k,i){site()[k].splice(i,1);touch();render()}
function addRow(k){let defs={loads:{name:'',kw:0,qty:1,sim:100,start:8,hours:8,priority:'P2 — Esencial'},outages:{start:12,hours:1},materials:{id:uid(),family:'',name:'',unit:'ud',qty:1,note:''},tasks:{id:uid(),name:'',start:'',end:'',owner:'',status:'Pendiente',progress:0},budget:{name:'',qty:1,cost:0,currency:'USD'}};site()[k].push(defs[k]||{});if(['loads','materials','tasks','budget'].includes(k))listPages['rows:'+site().id+':'+k]=Math.floor((site()[k].length-1)/15);touch();render()}
function loads(){let s=site();return head('Estudio de cargas','Define las cargas de la empresa y activa el perfil de equipos para simular su demanda.')+panel('Perfil de consumo',`<label class="check"><input type="checkbox" ${s.useLoads?'checked':''} onchange="setSite('useLoads',this.checked);render()"> Usar inventario detallado de equipos (desmarcado = estimación rápida por horarios)</label><label class="check"><input type="checkbox" ${s.loadCalendarMode?'checked':''} onchange="setSite('loadCalendarMode',this.checked);render()"> Activar días de funcionamiento por equipo, incluidos días de descanso</label><div id="energySummary" class="grid">${energyMetrics(s)}</div>`)+panel('Equipos y prioridades',`<p class="notice">P1 crítica: no debería interrumpirse; P2 esencial: sostiene la actividad; P3 secundaria: puede limitarse; P4 aplazable: puede reprogramarse. Simultaneidad: porcentaje de potencia utilizada a la vez. Inicio y duración se expresan en horas del día. Por defecto el inventario se aplica en días laborables. Si activas el calendario por equipo, configura los días en su ficha. En descanso, la potencia permanente configurada actúa como mínimo sin duplicar los equipos.</p>`+B('Agregar equipo','addEquipmentDialog()','')+rowTable('loads',[['name','Equipo'],['kw','kW / unidad','number'],['qty','Cantidad','number'],['sim','Simultaneidad %','number'],['start','Hora inicio','number'],['hours','Duración h','number'],['priority','Prioridad']]))+panel('Datos de diseño y arranque',`<div id="loadDesignAudit">${loadDesignAudit(s)}</div>`)+`<p class="warn">El modelo usa promedios de una hora durante el período seleccionado. No calcula los picos instantáneos al arrancar motores ni la potencia reactiva; estos afectan el dimensionamiento de inversores y conductores. Las prioridades documentan qué cargas proteger; no se simula su desconexión automáticamente.</p>`}
const pvDefaults={"pvImp": 0, "pvVmp": 0, "pvVoc": 0, "pvIsc": 0, "pvSeries": 0, "pvParallel": 0, "pvMppt": 0, "pvMpptA": 0, "pvMpptIsc": 0, "pvMpptMin": 0, "pvMpptMax": 0, "pvMaxVoc": 0, "pvDcMax": 0, "pvShape": 3, "pvDawn": 6, "pvDusk": 18, "pvGmax": 1100, "pvAmbient": 30, "pvNoct": 45, "pvCold": 5, "pvGamma": -0.35, "pvVmpCoeff": -0.3, "pvVocCoeff": -0.28, "pvLoss": 5, "pvConversion": 96};
const configs={...{"pvImp": ["Corriente Imp por panel (A)", 0, 50, 0.01], "pvVmp": ["Tensión Vmp por panel (V)", 0, 150, 0.01], "pvVoc": ["Tensión Voc por panel (V)", 0, 200, 0.01], "pvIsc": ["Corriente Isc por panel (A)", 0, 60, 0.01], "pvSeries": ["Paneles por string", 0, 100, 1], "pvParallel": ["Strings totales", 0, 3000, 1], "pvMppt": ["MPPT totales", 0, 3000, 1], "pvMpptA": ["Corriente operativa máxima por MPPT (A)", 0, 500, 0.1], "pvMpptIsc": ["Isc máxima por MPPT (A)", 0, 500, 0.1], "pvMpptMin": ["Tensión mínima MPPT (V)", 0, 2000, 1], "pvMpptMax": ["Tensión máxima MPPT (V)", 0, 2000, 1], "pvMaxVoc": ["Tensión DC absoluta máxima (V)", 0, 2000, 1], "pvDcMax": ["Potencia FV DC admisible total (kW)", 0, 5000, 0.01], "pvShape": ["Concentración del perfil solar", 0.25, 12, 0.25], "pvDawn": ["Inicio de ventana solar (h)", 0, 23, 0.5], "pvDusk": ["Fin de ventana solar (h)", 1, 24, 0.5], "pvGmax": ["Irradiancia máxima sintética (W/m²)", 100, 1400, 10], "pvAmbient": ["Temperatura ambiente de referencia (°C)", -30, 70, 1], "pvNoct": ["NOCT del módulo (°C)", 20, 80, 1], "pvCold": ["Temperatura mínima de célula de diseño (°C)", -40, 50, 1], "pvGamma": ["Coeficiente térmico Pmax (%/°C)", -2, 0, 0.01], "pvVmpCoeff": ["Coeficiente térmico Vmp (%/°C)", -2, 0, 0.01], "pvVocCoeff": ["Coeficiente térmico Voc (%/°C)", -2, 0, 0.01], "pvLoss": ["Pérdidas adicionales DC (%)", 0, 100, 0.1], "pvConversion": ["Eficiencia de conversión de referencia (%)", 0, 100, 0.1]},hours:['Jornada laboral (h)',0,24,1],start:['Hora de inicio laboral',0,23,1],work:['Carga laboral (kW)',0,1000,.1],rest:['Carga fuera de jornada laboral (kW)',0,1000,.1],restDay:['Consumo permanente en días de descanso (kW)',0,1000,1],panels:['Paneles (ud)',0,3000,1],watts:['Potencia por panel (W)',100,1000,5],sun:['Horas solares pico',0,10,.1],pr:['Rendimiento total FV (%)',0,100,1],inverter:['Potencia inversores (kW)',0,1500,1],battery:['Baterías nominales (kWh)',0,5000,1],bcharge:['Potencia máxima de carga (kW)',0,1500,1],bdischarge:['Potencia máxima de descarga (kW)',0,1500,1],dod:['Profundidad de descarga (%)',0,100,1],eff:['Eficiencia de descarga (%)',1,100,1],chargeEff:['Eficiencia de carga (%)',1,100,1],soc:['SOC inicial (%)',0,100,1],gridLimit:['Potencia máxima de red (kW)',0,2000,1],gridCharge:['Recarga desde red (kW)',0,1500,1],outStart:['Inicio del apagón',0,23,1],outHours:['Duración del apagón (h)',0,24,1],generator:['Generador (kW)',0,1500,1],ev:['Carga EV simultánea (kW)',0,1000,1],evStart:['Inicio de carga EV',0,23,1],evHours:['Duración EV (h)',0,24,1]};
function demandField(s,k){let [label,min,max,step]=configs[k];if(s.useLoads&&['work','rest'].includes(k)){let d=inventoryDemand(s);min=k==='work'?d.workPeak:d.restPeak;max=Math.max(max,min,k==='work'?d.workTarget:d.restTarget);step='any';return {label,min,max,step,value:k==='work'?d.workTarget:d.restTarget}}let value=simValue(s,k);if(Number.isFinite(Number(value)))max=Math.max(max,Number(value));if(k==='panels'||k==='pvParallel'||k==='pvMppt')max=Math.max(max,12000);return {label,min,max,step,value}}
function updateDemandValue(s,k,v,min,max){if(s.useLoads&&['work','rest'].includes(k)){let d=inventoryDemand(s),floor=k==='work'?d.workPeak:d.restPeak,field=k==='work'?'inventoryWork':'inventoryRest';let n=Math.max(floor,Math.min(Math.max(max,floor),Number(v)||0));s[field]=n>floor?n:null;return n}return s[k]=Math.max(min,Math.min(max,Number(v)||0))}
function inventoryModeFields(s,fn){return `<p class="notice"><label class="check"><input type="checkbox" aria-label="Usar inventario detallado en simulación" ${s.useLoads?'checked':''} onchange="${fn}('mode',this.checked)"> Usar inventario detallado en simulación</label>${s.useLoads?'Los campos muestran los picos simultáneos inventariados más las ampliaciones. Los equipos conservan sus horarios. El selector inferior decide si la ampliación fuera de jornada también se suma durante el trabajo.':'Modo manual: puedes introducir cualquier valor, incluso cero. El estudio de equipos se conserva sin cambios.'} ${s.useLoads?`<button type="button" class="secondary" onclick="${fn}('reset',true)">Restablecer a los valores del estudio</button>`:''}</p>`}
function setInventoryMode(k,v){let calc=page==='tools',s=calc?calcSite:site();if(k==='mode')s.useLoads=Boolean(v);else if(k==='reset'){s.inventoryWork=null;s.inventoryRest=null}if(!calc)touch();render()}
function syncDemandControls(s){for(let k of ['work','rest']){let f=demandField(s,k);for(let prefix of ['r_','n_']){let el=$(prefix+k);if(!el)continue;el.min=f.min;el.max=f.max;el.step=f.step;if(document.activeElement!==el)el.value=f.value}}}
function control(s,k,calc=false){let {label:l,min,max,step,value}=demandField(s,k),a=calc?'setCalc':'setSim';return `<label class="field">${E(l)}<div class="units"><input aria-label="${E(l)}" id="r_${k}" type="range" min="${min}" max="${max}" step="${step}" value="${E(value)}" oninput="${a}('${k}',this.value)"><input aria-label="Valor ${E(l)}" id="n_${k}" type="number" min="${min}" max="${max}" step="${step}" value="${E(value)}" oninput="${a}('${k}',this.value,true)" onchange="this.value=demandField(${calc?'calcSite':'site()'},'${k}').value" onblur="this.value=demandField(${calc?'calcSite':'site()'},'${k}').value"></div>${s.useLoads&&['work','rest'].includes(k)?`<small class="field-help">${k==='work'?'Pico inventariado más ampliación laboral, antes de sumar la base adicional. Consulta el pico resultante abajo.':'Pico inventariado fuera de jornada más ampliación. El selector decide si la ampliación también se aplica al trabajo.'}</small>`:help(k)}</label>`}
function setSim(k,v,fromNumber=false){let s=site(),f=demandField(s,k),x=updateDemandValue(s,k,v,f.min,f.max);if(k==='pvParallel')s.strings=x;if(k==='pvMppt'){s.mppt=x;if(s.inverterCount&&s.mpptPerInverter*s.inverterCount!==x)s.mpptPerInverter=null;}if(k==='inverter'&&s.inverterCount>0&&s.unitInverter>0){s.inverterCount=null}if(k==='rest'&&s.restDay==null&&$('weeklyFields'))$('weeklyFields').innerHTML=calendarFields(s,'setCalendar');$('r_'+k).value=x;if(!fromNumber)$('n_'+k).value=x;touch()}
function setCalc(k,v,fromNumber=false){let s=calcSite,f=demandField(s,k),x=updateDemandValue(s,k,v,f.min,f.max);if(k==='pvParallel')s.strings=x;if(k==='pvMppt'){s.mppt=x;if(s.inverterCount&&s.mpptPerInverter*s.inverterCount!==x)s.mpptPerInverter=null;}if(k==='inverter'&&s.inverterCount>0&&s.unitInverter>0){s.inverterCount=null}if(k==='rest'&&s.restDay==null&&$('weeklyFields'))$('weeklyFields').innerHTML=calendarFields(s,'setCalendar');$('r_'+k).value=x;if(!fromNumber)$('n_'+k).value=x;refreshDerived()}
const weekNames=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
function calendarDefaults(){return {startWeekday:0,workDays:[0,1,2,3,4,5,6],restDay:null,evOnRest:false}}
function workSchedule(s){return Array.isArray(s.workDays)?[...new Set(s.workDays.map(Number).filter(i=>Number.isInteger(i)&&i>=0&&i<=6))].sort((a,b)=>a-b):[0,1,2,3,4,5,6]}
function calendarFields(s,fn){let w=workSchedule(s),d=Number(s.startWeekday??0),base=s.restDay??s.rest??0;return `<div class="weekly-layout"><label class="field">Día de inicio de la simulación<select aria-label="Día de inicio de la simulación" onchange="${fn}('startWeekday',this.value)">${weekNames.map((n,i)=>`<option value="${i}" ${d===i?'selected':''}>${n}</option>`).join('')}</select><small class="field-help">El SOC inicial se aplica el día elegido a la hora de inicio del estudio.</small></label><div class="field"><span>Consumo permanente en días de descanso (kW)</span><input type="number" aria-label="Consumo permanente en días de descanso (kW)" min="0" max="1000" step="0.1" value="${Number(base)||0}" onchange="${fn}('restDay',this.value)"><small class="field-help">Carga viva de 24 h: vigilancia, frigoríficos, servidores u otros equipos que no se apagan.</small></div></div><div class="weekly-actions"><button type="button" class="secondary" onclick="${fn}('preset','week')">Lunes a viernes</button><button type="button" class="secondary" onclick="${fn}('preset','six')">Lunes a sábado</button><button type="button" class="secondary" onclick="${fn}('preset','all')">Todos los días</button><button type="button" class="secondary" onclick="${fn}('preset','none')">Todos descanso</button></div><div class="weekly-days">${weekNames.map((n,i)=>`<button type="button" class="week-day ${w.includes(i)?'work-day':'rest-day'}" aria-label="${n}" aria-pressed="${w.includes(i)}" onclick="${fn}('toggle',${i})"><strong>${n}</strong><span>${w.includes(i)?'Laborable':'Descanso'}</span></button>`).join('')}</div><p class="notice">${w.length} días laborables · ${7-w.length} días de descanso. El perfil laboral (o inventario de equipos) se aplica solo en días laborables. En descanso se usa la carga permanente todo el día; FV, baterías, red, apagones y generador conservan sus reglas. Los días se cambian a medianoche.</p>${s.modules.includes('Carga EV')?`<label class="check"><input type="checkbox" ${s.evOnRest?'checked':''} onchange="${fn}('evOnRest',this.checked)"> Permitir carga de vehículos también en días de descanso (se suma a la carga viva)</label>`:''}`}
function updateCalendar(s,k,v){if(k==='preset')s.workDays=({week:[0,1,2,3,4],six:[0,1,2,3,4,5],all:[0,1,2,3,4,5,6],none:[]})[v]??workSchedule(s);else if(k==='toggle'){let w=workSchedule(s),i=Number(v);if(i>=0&&i<=6)s.workDays=w.includes(i)?w.filter(a=>a!==i):[...w,i].sort((a,b)=>a-b)}else if(k==='startWeekday')s.startWeekday=Math.max(0,Math.min(6,Math.trunc(Number(v)||0)));else if(k==='restDay')s.restDay=Math.max(0,Math.min(1000,Number(v)||0));else if(k==='evOnRest')s.evOnRest=Boolean(v)}
function setCalendar(k,v){let calc=page==='tools',s=calc?calcSite:site();updateCalendar(s,k,v);$('weeklyFields').innerHTML=calendarFields(s,'setCalendar');if(calc)refreshDerived();else touch()}
function calendarSummary(s){return 'Laborables: '+(workSchedule(s).map(i=>weekNames[i]).filter(Boolean).join(', ')||'ninguno')+'; descanso: '+(weekNames.filter((_,i)=>!workSchedule(s).includes(i)).join(', ')||'ninguno')+'; carga viva: '+(s.restDay??s.rest??0)+' kW; inicio: '+weekNames[s.startWeekday??0]+'.'}
function civilRows(r){let groups=[];for(let a of r.rows){let g=groups.at(-1);if(!g||g.day!==a.day){g={day:a.day,weekday:a.weekday,workday:a.workday,rows:[]};groups.push(g)}g.rows.push(a)}return groups.map(g=>{let z=g.rows,sum=k=>z.reduce((n,a)=>n+(a[k]||0),0);return {day:g.day,weekday:g.weekday,workday:g.workday,from:z[0].i,to:z.at(-1).i+1,hours:z.length,start:z[0].socStart,end:z.at(-1).soc,load:sum('load'),pv:sum('pv'),grid:sum('grid'),gen:sum('gen'),ch:sum('ch'),dis:sum('dis'),need:sum('need')}})}
function weekDayLabel(a){return weekNames[a.weekday]+' · '+(a.workday?'Laborable':'Descanso')}
function civilTable(r){return `<div class="scroll"><table id="weeklyBalance"><tr>${['Día / actividad','Período','Demanda kWh','FV kWh','Red kWh','Gen. kWh','Recarga kWh','Descarga kWh','Déficit kWh','SOC inicial','SOC final'].map(t=>'<th>'+t+'</th>').join('')}</tr>${civilRows(r).map(a=>`<tr class="${a.workday?'':'rest-row'}"><td>${weekDayLabel(a)}</td><td>${timeAt(r,a.from)} → ${timeAt(r,a.to)} (${a.hours} h)</td>${['load','pv','grid','gen','ch','dis','need'].map(k=>'<td>'+fmt(a[k])+'</td>').join('')}<td>${socText(a.start,r.bat)}</td><td>${socText(a.end,r.bat)}</td></tr>`).join('')}</table></div>`}

const clockHour=h=>String((h+24)%24).padStart(2,'0')+':00';
const timeAt=(r,i)=>clockHour(r.startHour+i)+(Math.floor((r.startHour+i)/24)?' +'+Math.floor((r.startHour+i)/24)+'d':'');
const durationHours=s=>Math.max(1,Math.min(168,Math.trunc(Number(s.simHours)||24)));
function durationPicker(s,calc=false){let n=durationHours(s);return `<div class="field"><span>Duración de la simulación</span><div class="duration-buttons">${[24,48,72,168].map(h=>`<button type="button" data-duration="${h}" aria-pressed="${n===h}" class="${n===h?'':'secondary'}" onclick="setDuration(${h},${calc})">${h===168?'7 días · 168 h':h+' h'}</button>`).join('')}</div><div class="units"><input id="simHoursRange" aria-label="Horas simuladas" type="range" min="1" max="168" step="1" value="${n}" oninput="setDuration(this.value,${calc})"><input id="simHoursNumber" aria-label="Duración personalizada en horas" type="number" min="1" max="168" step="1" value="${n}" onchange="setDuration(this.value,${calc})"></div><small class="field-help">1–168 horas. El SOC inicial se aplica una sola vez; el consumo cambia según el calendario; el sol y los apagones se repiten cada día.</small></div>`}
function setDuration(v,calc=false){let s=calc?calcSite:site();s.simHours=durationHours({simHours:v});for(let id of ['simHoursRange','simHoursNumber'])if($(id))$(id).value=s.simHours;document.querySelectorAll('[data-duration]').forEach(b=>{let on=+b.dataset.duration===s.simHours;b.classList.toggle('secondary',!on);b.setAttribute('aria-pressed',String(on))});if(calc)refreshDerived();else touch()}
function cycleRows(r){let blocks=[];for(let i=0;i<r.rows.length;i+=24){let a=r.rows.slice(i,i+24),sum=k=>a.reduce((n,z)=>n+(z[k]||0),0);blocks.push({n:blocks.length+1,from:timeAt(r,i),to:timeAt(r,i+a.length),hours:a.length,load:sum('load'),pv:sum('pv'),grid:sum('grid'),gen:sum('gen'),genRecharge:sum('genRecharge'),genHours:a.filter(z=>z.genRunning).length,dis:sum('dis'),ch:sum('ch'),need:sum('need'),start:a[0].socStart,end:a.at(-1).soc})}return blocks}
function cycleTable(r){return `<div class="scroll"><table><tr>${['Ciclo','Período','Demanda kWh','FV kWh','Red kWh','Generador kWh','Gen. a recarga kWh','Horas generador','Descarga kWh','Recarga kWh','Déficit kWh','SOC inicial','SOC final'].map(x=>'<th>'+x+'</th>').join('')}</tr>${cycleRows(r).map(a=>`<tr><td>${a.n} · ${a.hours} h</td><td>${a.from} → ${a.to}</td>${['load','pv','grid','gen','genRecharge','genHours','dis','ch','need'].map(k=>'<td>'+fmt(a[k])+'</td>').join('')}<td>${socText(a.start,r.bat)}</td><td>${socText(a.end,r.bat)}</td></tr>`).join('')}</table></div>`}
function tickIndices(last){let step=Math.max(1,Math.ceil(last/6));return [...new Set([0,...Array.from({length:Math.floor(last/step)},(_,i)=>(i+1)*step),last])]}
const socText=(v,cap)=>cap>0?fmt(v/cap*100)+' % · '+fmt(v)+' kWh':'—';
function simStartPicker(s,calc=false){return `<label class="field"><span>Inicio de la simulación y SOC inicial</span><select id="simStartMode" onchange="setSimulationStart(this.value,${calc})"><option value="linked" ${s.simStart==null?'selected':''}>Igual al inicio laboral (automático)</option>${Array.from({length:24},(_,h)=>`<option value="${h}" ${s.simStart===h?'selected':''}>${clockHour(h)} · independiente</option>`).join('')}</select><small class="field-help">El SOC inicial se aplica en esta hora exacta. El cálculo continúa durante el período elegido, sin reiniciar la batería.</small></label>`}
function setSimulationStart(v,calc=false){let s=calc?calcSite:site();s.simStart=v==='linked'?null:Math.max(0,Math.min(23,Math.trunc(Number(v)||0)));if(calc)refreshDerived();else touch()}
function simPeriod(r){return `${timeAt(r,0)} → ${timeAt(r,r.rows.length)} · ${r.rows.length} h`;}
function energyMetrics(s){let m=energy(s);return (m.groupStatus==='invalid'?'<p class="warn">Comprobación por grupos inválida: cifras únicamente agregadas.</p>':'')+metric(fmt(m.loadTotal)+' kWh','Demanda · '+m.rows.length+' h')+metric(fmt(m.pvTotal)+' kWh','FV disponible · '+m.rows.length+' h')+metric(fmt(m.unmet)+' kWh','Energía no atendida')+metric(fmt(m.gridTotal)+' kWh','Energía de red')+metric(fmt(m.genTotal)+' kWh','Generador total')+ (s.modules.includes('Generador')?metric(fmt(m.rows.reduce((n,a)=>n+a.genRecharge,0))+' kWh','Generador a recarga')+metric(m.rows.filter(a=>a.genRunning).length+' h','Horas con aporte del generador'):'')+metric(m.bat?fmt(m.end/m.bat*100)+' %':'—','SOC al final')}
function chart(r,keys=[['load','#18323a'],['pv','#d5a134'],['grid','#5784b5'],['gen','#7758a0'],['dis','#087e67'],['need','#c84444']]){let max=Math.max(1,...r.flatMap(x=>keys.map(([k])=>x[k])));return `<svg class="chart" viewBox="0 0 780 245" role="img" aria-label="Balance energético horario">${[0,1,2,3,4].map(i=>`<line x1="50" y1="${20+i*46}" x2="750" y2="${20+i*46}" stroke="#dce7e4"/><text x="3" y="${24+i*46}" font-size="11" fill="#62767b">${fmt(max*(1-i/4),0)}</text>`).join('')}${keys.map(([k,c])=>`<polyline fill="none" stroke="${c}" stroke-width="2.8" points="${r.map((a,i)=>`${50+i*700/Math.max(1,r.length-1)},${204-a[k]/max*184}`).join(' ')}"/>`).join('')}${tickIndices(r.length-1).map(i=>`<text x="${50+i*700/Math.max(1,r.length-1)}" y="228" font-size="12" fill="#62767b">${clockHour(r[i].h)}${r[i].day?' +'+r[i].day+'d':''}</text>`).join('')}</svg>`}
function result(s){let m=energy(s);return `${balanceNotice(m)}<div class="notice"><b>Período: ${simPeriod(m)}</b><br>${weekNames[m.startWeekday]} · ${calendarSummary(s)}<br>SOC inicial a las ${timeAt(m,0)}: ${socText(m.rows[0].socStart,m.bat)}. SOC final: ${socText(m.end,m.bat)}.</div><div class="notice">${m.unmet>0?'La solución deja '+fmt(m.unmet)+' kWh sin atender en '+m.rows.filter(r=>r.need>1e-8).length+' intervalos horarios. Revisa capacidad, potencia y disponibilidad de fuentes.':'La demanda simulada queda atendida bajo estos supuestos.'} Excedente solar: ${fmt(m.spill)} kWh.</div><div class="grid">${energyMetrics(s)}</div><div class="panel"><h2>Comparación por ciclos de 24 horas</h2><p class="muted">Cada ciclo comienza a la hora de inicio elegida. El último puede ser parcial. El SOC final pasa al ciclo siguiente.</p>${cycleTable(m)}</div><div class="panel"><h2>Balance por día de la semana</h2><p class="muted">Días civiles de medianoche a medianoche. Primero y último pueden ser parciales; la batería conserva su SOC. Los días de descanso pueden recuperar energía si sobra generación.</p>${civilTable(m)}</div><div class="panel"><h2>Potencia media por hora (kW)</h2>${chart(m.rows)}<div class="row"><small>● Demanda</small><small style="color:#a77712">● Solar</small><small style="color:#5784b5">● Red</small><small style="color:#7758a0">● Generador</small><small style="color:#087e67">● Batería</small><small style="color:#c84444">● Déficit</small></div><h2 style="margin-top:20px">Evolución del almacenamiento (kWh)</h2>${chart([{h:m.startHour,day:0,soc:m.rows[0].socStart},...m.rows.map(a=>({h:(a.h+1)%24,day:Math.floor((m.startHour+a.i+1)/24),soc:a.soc}))],[['soc','#087e67']])}<p class="muted">Excedente FV: ${fmt(m.spill)} kWh · Energía útil nominal AC: ${fmt(m.usable)} kWh · Jornada restante: ${24-s.hours} h</p></div><div class="scroll"><table id="hourlyBalance"><tr>${['Hora de inicio','Carga (kW)','FV','Red','Generador','Gen. a recarga','Descarga','Recarga','SOC inicial','SOC final','Déficit'].map(t=>`<th>${t}</th>`).join('')}</tr>${m.rows.map(a=>`<tr><td>${timeAt(m,a.i)} <small>${weekDayLabel(a)}</small></td>${['load','pv','grid','gen','genRecharge','dis','ch'].map(k=>`<td>${fmt(a[k],3)}</td>`).join('')}<td>${socText(a.socStart,m.bat)}</td><td>${socText(a.soc,m.bat)}</td><td>${fmt(a.need)}</td></tr>`).join('')}</table></div>`}
function generatorDefaults(){return {genMode:'deficit',genTarget:'loads',genIntervals:[],genMaxHours:24,genSocStart:50,genSocStop:90,genChargeLimit:1500,genOnlyOutage:false}}
function generatorFields(s,handler){
  let mode=s.genMode||'deficit',target=s.genTarget||'loads',socMode=mode==='soc'||mode==='combined',schedule=mode==='schedule'||mode==='combined';
  const options=(key,label,values,help)=>`<label class="field"><span>${label}</span><select aria-label="${label}" onchange="${handler}('${key}',this.value)">${values.map(([v,t])=>`<option value="${v}" ${(s[key]|| (key==='genMode'?'deficit':'loads'))===v?'selected':''}>${t}</option>`).join('')}</select><small class="field-help">${help}</small></label>`;
  const n=(key,label,min,max,value,help)=>`<label class="field"><span>${label}</span><input aria-label="${label}" type="number" min="${min}" max="${max}" step="1" value="${Number(value)}" onchange="${handler}('${key}',this.value)"><small class="field-help">${help}</small></label>`;
  return `<label class="check"><input type="checkbox" ${s.genEnabled?'checked':''} onchange="${handler}('genEnabled',this.checked)"> Habilitar generador</label><div class="fields">${options('genMode','Modo de arranque',[['deficit','Automático por déficit (modo anterior)'],['schedule','Por horarios programados'],['soc','Por porcentaje de batería (SOC)'],['combined','Por SOC dentro de horarios']],'Define cuándo el generador puede suministrar energía.')}<div class="field" style="grid-column:1/-1"><span>Destino de la energía del generador</span><div role="group" aria-label="Destino de la energía" style="display:flex;gap:8px;flex-wrap:wrap">${[['loads','Solo alimentar la instalación'],['charge','Solo cargar la batería'],['both','Alimentar y cargar batería']].map(([v,label])=>`<button type="button" aria-pressed="${target===v}" class="${target===v?'':'secondary'}" style="flex:1;min-width:145px;padding:10px;border-radius:8px;${target===v?'background:#087e67;color:white;border:1px solid #087e67':'background:#f0f5f4;color:#163d39;border:1px solid #c5d5d2'}" onclick="${handler}('genTarget','${v}')">${label}</button>`).join('')}</div><small class="field-help">${target==='loads'?'Alimenta únicamente las cargas que no cubren las fuentes prioritarias.':target==='charge'?'Dedica el generador a la recarga; las cargas siguen dependiendo de las otras fuentes y del inversor.':'Abastece primero las cargas pendientes y emplea la potencia restante para recargar.'} La red es la instalación interna; no se simula inyección a la red pública.</small></div>${n('genMaxHours','Máximo de horas por día',0,24,s.genMaxHours??24,'Horas civiles con producción efectiva; 0 deshabilita el aporte.')}${target!=='loads'?n('genChargeLimit','Límite de recarga desde generador (kW)',0,1500,s.genChargeLimit??1500,'Además se respetan el límite de carga de batería y el modelo de inversor.'):''}${socMode?n('genSocStart','Arrancar al SOC (%)',0,99,s.genSocStart??50,'Arranca al inicio de una hora si llega o baja de este porcentaje.')+n('genSocStop','Detener al SOC (%)',1,100,s.genSocStop??90,'Debe superar el umbral de arranque; evita ciclos de arranque frecuentes.'):''}</div><label class="check"><input type="checkbox" ${s.genOnlyOutage?'checked':''} onchange="${handler}('genOnlyOutage',this.checked)"> Permitir funcionamiento únicamente durante apagones</label>${schedule?`<h3>Intervalos diarios de funcionamiento</h3><p class="muted">Añade varios horarios. Pueden cruzar medianoche; se repiten cada día y no se suman si coinciden. Sin intervalos, el generador no aportará energía.</p>${(s.genIntervals||[]).map((o,i)=>`<div class="fields"><label class="field">Inicio (0–23)<input aria-label="Inicio intervalo ${i+1}" type="number" min="0" max="23" step="1" value="${Number(o.start)}" onchange="${handler}('intervalStart',this.value,${i})"></label><label class="field">Duración (h)<input aria-label="Duración intervalo ${i+1}" type="number" min="0" max="24" step="1" value="${Number(o.hours)}" onchange="${handler}('intervalHours',this.value,${i})"></label><button class="secondary" onclick="${handler}('removeInterval',0,${i})">Eliminar intervalo ${i+1}</button></div>`).join('')}<button class="secondary" onclick="${handler}('addInterval')">+ Agregar intervalo</button>`:''}${socMode&&(!s.modules.includes('Baterías')||!s.battery)?'<p class="warn">El arranque por SOC requiere una batería configurada.</p>':socMode&&(s.genSocStart??50)<100-s.dod?'<p class="warn">El SOC de arranque está por debajo de la reserva de descarga: normalmente no se alcanzará. Revisa el umbral.</p>':''}${target==='charge'?'<p class="notice">Solo recarga: supone un cargador compatible independiente hacia el bus DC. El inversor puede abastecer las cargas mientras el generador aporta energía al bus; el SOC refleja el flujo neto y las pérdidas. Validar topología y límites con fabricante.</p>':''}<p class="muted">Modelo por horas completas, red prioritaria. No calcula consumo de combustible ni arranques físicos.</p>`;
}
function updateGenerator(s,k,v,i){
  let limits={genMaxHours:[0,24],genSocStart:[0,99],genSocStop:[1,100],genChargeLimit:[0,1500]};
  if(k==='addInterval'){(s.genIntervals??=[]).push({start:18,hours:4});return}
  if(k==='removeInterval'){s.genIntervals.splice(i,1);return}
  if(k==='intervalStart'||k==='intervalHours'){let key=k==='intervalStart'?'start':'hours';s.genIntervals[i][key]=Math.max(0,Math.min(key==='start'?23:24,Math.trunc(Number(v)||0)));return}
  if(k in limits){s[k]=Math.max(limits[k][0],Math.min(limits[k][1],Math.trunc(Number(v)||0)));if(k==='genSocStart'&&(s.genSocStop??90)<=s[k])s.genSocStop=s[k]+1;if(k==='genSocStop'&&(s.genSocStart??50)>=s[k])s.genSocStart=s[k]-1;return}
  if(['genMode','genTarget','genEnabled','genOnlyOutage'].includes(k))s[k]=v;
}
function setGenerator(k,v,i){let calc=page==='tools',s=calc?calcSite:site();updateGenerator(s,k,v,i);if(calc)refreshDerived();else touch();$('generatorFields').innerHTML=generatorFields(s,'setGenerator')}
function loadModeSummary(s){if(s.useLoads){let d=inventoryDemand(s),f=v=>Number(v.toFixed(3)).toLocaleString('es');return 'Inventario detallado activo. Pico laboral estudiado: '+f(d.workPeak)+' kW; pico fuera de jornada: '+f(d.restPeak)+' kW. Ampliación laboral: '+f(d.workExtra)+' kW; ampliación fuera de jornada: '+f(d.restExtra)+' kW. Tratamiento: '+(s.restMode==='additional'?'Adicional':'Incluida')+'. Ampliación fuera de jornada aplicada también durante el trabajo: '+f(d.restExtraAtWork)+' kW. Pico laboral resultante: '+f(d.workResult)+' kW; fuera de jornada: '+f(d.restTarget)+' kW. Energía del perfil diario: '+f(d.adjusted.reduce((a,b)=>a+b,0))+' kWh (sin EV, día laborable). El descanso mantiene su consumo independiente.';}let w=Math.max(0,Number(s.work)||0),r=Math.max(0,Number(s.rest)||0),h=Math.max(0,Math.min(24,Number(s.hours)||0)),extra=s.restMode==='additional',total=w+(extra?r:0),f=v=>Number(v.toFixed(3)).toLocaleString('es');return (extra?'Carga base adicional durante el trabajo.':'Carga fuera de jornada ya incluida en la carga laboral.')+' Jornada: '+f(total)+' kW × '+f(h)+' h; fuera de jornada: '+f(r)+' kW × '+f(24-h)+' h. Total día laborable: '+f(total*h+r*(24-h))+' kWh (sin carga EV).'+(!extra&&w<r&&h>0?' Verifica las potencias: la carga laboral declarada es inferior a la carga fuera de jornada.':'')}
function loadModeFields(s,fn){let extra=s.restMode==='additional';return `<div class="field"><span>Tratamiento de la carga fuera de jornada</span><select aria-label="Tratamiento de la carga fuera de jornada" onchange="${fn}(this.value)"><option value="included" ${!extra?'selected':''}>Incluida en la carga laboral (no sumar)</option><option value="additional" ${extra?'selected':''}>Adicional a la carga laboral (sumar)</option></select><small class="field-help">${s.useLoads?'Con inventario: incluida = la ampliación fuera de jornada solo se aplica fuera del trabajo; adicional = esa ampliación también se suma durante el trabajo. Los equipos estudiados no se duplican.':'Incluida: 66 kW ya contiene los 20 kW de base. Adicional: 66 + 20 = 86 kW durante el trabajo. Fuera de jornada se mantienen los 20 kW.'}</small></div><p class="notice" id="loadModeSummary">${loadModeSummary(s)}</p>`}
function setLoadMode(v){let calc=page==='tools',s=calc?calcSite:site();s.restMode=v==='additional'?'additional':'included';if(calc)refreshDerived();else touch()}
function pvModeFields(s,handler){
 let esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 return `<div class="fields"><label class="field">Método de producción FV<select aria-label="Método de producción FV" onchange="${handler}('pvMode',this.value)">${[['legacy','Histórico · HSP / PR'],['advanced','Avanzado · irradiancia sintética y temperatura'],['hourly','Avanzado · irradiancia horaria introducida']].map(([v,t])=>`<option value="${v}" ${(s.pvMode||'legacy')===v?'selected':''}>${t}</option>`).join('')}</select><small>Histórico conserva estudios previos; avanzado no usa PR para evitar duplicar pérdidas.</small></label><label class="field">Arquitectura energética<select aria-label="Arquitectura fotovoltaica" onchange="${handler}('pvCoupled',this.value)"><option value="0" ${!Number(s.pvCoupled)?'selected':''}>Límite AC común (conservador)</option><option value="1" ${Number(s.pvCoupled)?'selected':''}>Acoplamiento DC compatible (FV puede recargar por encima del límite AC)</option></select><small>Solo tiene efecto en modo avanzado. Verificar límites reales de conversión y fabricante.</small></label></div>${s.pvMode==='hourly'?`<div class="fields"><label class="field">Irradiancia media POA (W/m²) · 24 valores desde 00:00<textarea rows="3" aria-label="Irradiancia horaria" onchange="${handler}('pvHourly',this.value)">${esc((s.pvHourly||[]).join(' '))}</textarea><small>Separar por espacios, usar punto decimal. 0–1600; faltantes usan perfil sintético provisional.</small></label><label class="field">Temperatura de célula (°C) · 24 valores opcionales<textarea rows="3" aria-label="Temperatura horaria" onchange="${handler}('pvHourlyTemp',this.value)">${esc((s.pvHourlyTemp||[]).join(' '))}</textarea><small>Si está vacío, estima con ambiente y NOCT.</small></label></div>`:''}`;
}
function pvUpdate(s,k,v){if(k==='pvMode')s[k]=['legacy','advanced','hourly'].includes(v)?v:'legacy';else if(k==='pvCoupled')s[k]=Number(v)===1?1:0;else if(['pvHourly','pvHourlyTemp'].includes(k)){let a=String(v).trim();s[k]=a?a.split(/\s+/).map(t=>Number.isFinite(Number(t))?Number(t):null):[]}}
function pvSummaryHTML(s){if(!s.modules.includes('Fotovoltaica'))return '';let m=pvModel(s),f=(v,d=2)=>v==null?'—':Number(v).toFixed(d),esc=v=>String(v).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));return `<p><b>${f(m.kwp)} kWp</b> · Imp: ${m.imp?f(m.imp)+' A':'Pendiente'} · Vmp: ${m.vmp?f(m.vmp)+' V':'Pendiente'} ${!Number(s.pvVmp)&&m.vmp?'(inferido de Wp/Imp)':''} · Voc frío string: ${m.coldVoc?f(m.coldVoc)+' V':'Pendiente'}</p><p>HSP efectivos: ${f(m.hsp)} h · Potencia FV máxima media: ${f(m.peak,3)} kW · Energía potencial: ${f(m.potential)} kWh · Disponible tras límites: ${f(m.usable)} kWh por perfil de 24 h. ${m.coupled?'FV expresada en equivalente de bus; no es salida AC exclusivamente.':''}</p>${m.warnings.map(w=>`<p class="warn">${esc(w)}</p>`).join('')}<details><summary>Auditoría del perfil solar · datos hora por hora</summary><div class="scroll"><table><tr><th>Hora</th><th>POA W/m²</th><th>Célula °C</th><th>DC kW tras límites</th><th>MPPT A estimados antes de límite</th><th>String V estimados</th><th>FV disponible kW</th><th>Recorte kW equivalente</th></tr>${m.rows.map((a,h)=>`<tr><td>${String(h).padStart(2,'0')}:00</td><td>${f(a.g,0)}</td><td>${f(a.tc,1)}</td><td>${f(a.dc,3)}</td><td>${f(a.amps)}</td><td>${f(a.vString)}</td><td>${f(a.usable,3)}</td><td>${f(a.clip,3)}</td></tr>`).join('')}</table></div></details>`}
function setPv(k,v){let s=site()||calcSite;pvUpdate(s,k,v);if(site())touch();else refreshDerived();render()}
function pvPanel(s,calc){return panel('Generación fotovoltaica',`<div class="fields">${['panels','watts','sun','pr','pvImp','pvVmp','pvVoc','pvIsc'].map(k=>control(s,k,calc)).join('')}</div><div id="pvModeFields">${pvModeFields(s,'setPv')}</div><p class="muted">HSP controla el perfil sintético; el perfil horario introducido determina sus propios HSP. PR solo se aplica al método histórico; el avanzado usa temperatura, pérdidas DC y eficiencia de conversión.</p><details ${s.pvMode&&s.pvMode!=='legacy'?'open':''}><summary>Parámetros avanzados · strings, MPPT y condiciones ambientales</summary><p class="notice">0 en datos nominales o límites = desconocido, no validado. El perfil avanzado usa irradiancia en el plano del panel; las pérdidas no deben repetirse en PR.</p><div class="fields">${Object.keys(pvDefaults).filter(k=>!['pvImp','pvVmp','pvVoc','pvIsc'].includes(k)).map(k=>control(s,k,calc)).join('')}</div></details><div id="pvSummary">${pvSummaryHTML(s)}</div>`)}

function simControls(s,calc=false){let group=(t,keys)=>panel(t,`<div class="fields">${keys.map(k=>control(s,k,calc)).join('')}</div>`);return panel('Consumo y horarios',`<div class="fields">${['hours','start','work','rest'].map(k=>control(s,k,calc)).join('')}</div>${inventoryModeFields(s,'setInventoryMode')}${loadModeFields(s,'setLoadMode')}`)+panel('Calendario semanal y consumo de descanso',`<div id="weeklyFields">${calendarFields(s,'setCalendar')}</div>`)+panel('Período de cálculo',`<div class="fields">${simStartPicker(s,calc)}${durationPicker(s,calc)}</div>`)+`<p id="restHours" class="notice">Jornada restante: ${24-s.hours} horas · Total: 24 horas${s.useLoads?' · Perfil de equipos activo: picos inventariados y ampliaciones opcionales.':''}</p>`+(s.modules.includes('Fotovoltaica')?pvPanel(s,calc):'')+group('Conversión y red',['inverter','gridLimit','gridCharge','outStart','outHours'])+panel('Configuración de inversores',designSharedFields(s,calc)+pvAssignmentFields(s,calc))+(s.modules.includes('Baterías')?group('Almacenamiento',['battery','bcharge','bdischarge','dod','eff','chargeEff','soc'])+panel('Estado y límites del almacenamiento',storageFields(s,calc)):'')+(s.modules.includes('Generador')?group('Generador',['generator'])+panel('Control inteligente del generador',`<div id="generatorFields">${generatorFields(s,'setGenerator')}</div>${fuelFields(s,calc)}`):'')+(s.modules.includes('Carga EV')?group('Carga de vehículos',['ev','evStart','evHours']):'')+panel('Apagones adicionales por día',outageFields(s,calc))}
function simulation(){let s=site();return head('Simulación energética','Modelo continuo de 1 a 168 horas, en pasos de una hora. Cambios inmediatos y guardado automático.',B('Guardar escenario','saveScenario()'))+`<div class="warn">${s.acGroups?.length?'Los indicadores principales muestran el balance agregado; revisa también la comprobación por grupos. Un balance agregado sin déficit no garantiza cobertura en todos los tableros.<br>':''}Modelo preliminar: solar sintética o perfil horario introducido, sin transitorios, sin topología AC/DC detallada. La red se prioriza cuando está disponible; no modela estrategia de autoconsumo con descarga salvo déficit. Verifica valores y datos de fabricante.</div>${simControls(s)}${s.acGroups?.length?groupDispatchPanel(s):''}<section class="panel"><h2>Resultados en tiempo real</h2><div id="liveBars">${liveBars(s)}</div><div id="simResult">${result(s)}</div></section>${panel('Escenarios guardados',s.scenarios.map((x,i)=>`<div class="row between"><p>${E(x.name)} · ${E(x.date.slice(0,10))}</p>${B('Cargar parámetros',`loadScenario(${i})`)}${B('Eliminar',`removeRow('scenarios',${i})`,'danger small')}</div>`).join('')||empty('Sin escenarios independientes.'))}`}
function saveScenario(){modal('Guardar escenario',mfield('Nombre','name','Escenario '+(site().scenarios.length+1),'text',true),f=>{let s=site();s.scenarios.push({name:f.get('name'),date:now(),data:Object.fromEntries([...Object.keys(configs),'pvMode','pvCoupled','pvHourly','pvHourlyTemp','simStart','simHours','startWeekday','workDays','evOnRest','restMode','inventoryWork','inventoryRest','outages','loads','useLoads','modules','genEnabled','genMode','genTarget','genIntervals','genMaxHours','genSocStart','genSocStop','genChargeLimit','genOnlyOutage','designMargin','autonomy','unitInverter','unitBattery',...V35_ENERGY_KEYS,'acGroups','acGroupDispatch','acDemandMode'].map(k=>[k,copy(k==='restDay'?s.restDay??null:k==='acGroups'?s.acGroups||[]:k==='acGroupDispatch'?s.acGroupDispatch===true:simValue(s,k)??null)]))});touch();render()})}
function loadScenario(i){if(confirm('¿Aplicar estos parámetros a la instalación activa?'+(installationGroup(project()).ids.includes(site().id)?' Los parámetros vinculados se actualizarán también en las demás instalaciones seleccionadas.':''))){let d=copy(site().scenarios[i].data);if(d.bcharge==null&&d.bpower!=null)d.bcharge=d.bpower;if(d.bdischarge==null&&d.bpower!=null)d.bdischarge=d.bpower;Object.assign(site(),{pvMode:'legacy',pvCoupled:0,pvHourly:[],pvHourlyTemp:[],...pvDefaults,simStart:null,simHours:24,restMode:'included',inventoryWork:null,inventoryRest:null,...calendarDefaults(),...generatorDefaults(),...Object.fromEntries(V35_ENERGY_KEYS.filter(k=>k!=='unitInverter').map(k=>[k,null])),acGroupDispatch:false,acDemandMode:'Porcentaje'},d);touch();render()}}
function tools(){return head('Calculadora independiente','Prueba parámetros sin modificar ningún expediente.')+panel('Configuración inicial',templatePicker('calcTemplate','','loadCalcTemplate(this.value)')+B('Aplicar valores generales','resetCalcDefaults()')+`<p class="muted">La plantilla reemplaza solo el cálculo independiente, previa confirmación. No modifica expedientes.</p>`)+catalogDesignPanel(calcSite,true)+panel('Tecnologías del cálculo',`<div class="fields">${MOD.map(([m,d])=>`<label class="check"><input type="checkbox" ${calcSite.modules.includes(m)?'checked':''} onchange="setCalcModule(${arg(m)},this.checked)"><span>${E(m)}<br><small>${E(moduleDetails[m]||d)}</small></span></label>`).join('')}</div>`)+simControls(calcSite,true)+panel('Ingeniería preliminar de la calculadora',`<div class="fields">${field('Autonomía objetivo (h)','autonomy',calcSite.autonomy,'setCalcCriterion','number')}${field('Módulo de batería (kWh)','unitBattery',calcSite.unitBattery,'setCalcCriterion','number')}${field('Margen de potencia (%)','designMargin',designMargin(calcSite),'setCalcCriterion','number','min=0 max=100 step=0.1')}</div><div id="sizing">${sizing(calcSite)}</div>`)+panel('Resultados en tiempo real',`<div id="liveBars">${liveBars(calcSite)}</div><div id="simResult">${result(calcSite)}</div>${B('Guardar cálculo en un proyecto','assignCalc()','')}`)}
function engineering(){let s=site();return head('Ingeniería y dimensionamiento','Parámetros de diseño y verificaciones de compatibilidad.')+panel('Criterios de selección',`<div class="fields">${select('Cargas que deseas respaldar','designLoad',s.designLoad||'Toda la demanda',['Toda la demanda','Solo P1 críticas','P1 y P2 esenciales','Potencia personalizada'])}${field('Potencia personalizada (kW)','customLoad',s.customLoad||0,'setSite','number')}${field('Autonomía objetivo (h)','autonomy',s.autonomy,'setSite','number')}${field('Margen de potencia (%)','designMargin',designMargin(s),'setSite','number','min=0 max=100 step=0.1')}${field('Capacidad por módulo BESS (kWh)','unitBattery',s.unitBattery,'setSite','number')}${field('Reserva accesorios (%)','reserve',s.reserve,'setSite','number')}${designSharedFields(s)}</div><label class="check"><input type="checkbox" ${s.optimize?'checked':''} onchange="setDesignField('optimizerMode',this.checked?'Todos DC':'Sin optimizadores',false);render()"> Incluir optimizadores de potencia (compatibilidad de MPPT pendiente)</label>${textField('Marcas, fichas y compatibilidad de optimizadores, MPPT, BMS, tensión y corriente','compatibility',s.compatibility)}`)+catalogDesignPanel(s,false)+panel('Origen de datos',B('Revisar fuentes y estado','dataSourcesDialog(false)')+`<p class="muted">Marca mediciones, fichas o supuestos sin cambiar automáticamente el dato de otra instalación.</p>`)+panel('Comprobaciones eléctricas y OEM',pvAssignmentFields(s,false)+engineeringFields(s)+`<div id="engineeringAudit">${engineeringAudit(s)}</div>`)+panel('Confirmaciones externas por configuración',oemPanel(s))+acArchitecturePanel(s)+circuitsPanel(s)+auxiliaryPanel(s)+groundingPanel(s)+mountingPanel(s)+panel('Integridad por bloques',`<div id="integrityHTML">${integrityHTML(s)}</div>`)+panel('Recomendación preliminar',`<div id="sizing">${sizing(s)}</div>${B('Aplicar potencia y batería objetivo','applySizing()','')}`)+`<div class="warn">No dimensiona breakers, cables, fijaciones ni estructuras definitivas. Requiere medición, cálculo normativo, cortocircuito, selectividad, puesta a tierra, vientos y fichas técnicas.</div>`}
function sizing(s){let a=recommendations(s);return `<div class="grid">${metric(fmt(a.inv)+' kW','Potencia sugerida · '+fmt(designMargin(s),1)+'% margen')}${metric(fmt(a.bat)+' kWh','BESS sugerido sin aporte FV')}${metric(fmt(a.target)+' kW','Carga objetivo de respaldo')}${metric(fmt(a.m.peak?a.m.usable/a.m.peak:0,2)+' h','Autonomía a pico · energía')}</div><p class="muted">Criterio: pico del calendario semanal (independiente de la duración de la simulación), carga objetivo × (1 + margen / 100); carga objetivo × autonomía / (DoD × eficiencia). Redondeo a unidades seleccionadas. Autonomía real limitada también por potencia del inversor y BESS.</p>`}
function legacySuggestions(s){let a=capacity(s),out=[],add=(key,family,name,unit,qty,note,res=false)=>out.push({key,family,name,unit,qty:qty===null?'':res?Math.ceil(qty*(1+Math.max(0,s.reserve)/100)):qty,note:note+(res?' · incluye reserva configurada':'')});let has=m=>s.modules.includes(m);if(has('Fotovoltaica')){add('pv','Generación',`Módulo FV ${s.watts} W`,'ud',s.panels,'Cantidad de diseño');if(s.optimize)add('opt','Generación','Optimizador de potencia','ud',s.panels,'Uno por módulo solo si ficha lo admite; MPPT pendiente',true);add('string','Protecciones DC','Seccionamiento y protección por string','juego',s.pvParallel||s.strings||null,'Topología y corriente por verificar');add('spdDc','Protecciones DC','SPD DC','juego',null,'Validar tensión y topología');add('cablesPv','Conductores','Cable solar DC y conectores','m',null,'Medir recorridos y caída de tensión');for(let [k,n,u,note] of [['rails','Rieles y perfiles','m','Longitud según plano y viento'],['midClamp','Grapas intermedias','ud','Según filas, módulos y sistema de montaje'],['endClamp','Grapas finales','ud','Según extremos de cada fila'],['splice','Empalmes de riel','ud','Según despiece estructural'],['pvConnectors','Conectores DC compatibles','par','Verificar tipo y fabricante; no mezclar conectores'],['dcConduit','Canalización DC resistente a UV','m','Medición de recorridos'],['pvBond','Accesorios equipotenciales FV','ud','Según estructura y sistema aprobado']])add(k,k==='pvConnectors'||k==='dcConduit'?'Conductores':'Estructura',n,u,null,note);add('labels','Consumibles','Etiquetas de módulo y señalización','ud',s.panels,'Criterio preliminar de identificación',true)}if(a.inv>0)add('inv','Conversión',`Inversor ${s.unitInverter} kW o equivalente`,'ud',Math.ceil(a.inv/Math.max(1,s.unitInverter)),'Confirmar paralelo, fases y tensión');if(has('Baterías')){add('bess','Almacenamiento',`Módulo BESS ${s.unitBattery} kWh`,'ud',Math.ceil(a.bat/Math.max(1,s.unitBattery)),'Confirmar integración, potencia y BMS');add('bms','Almacenamiento','BMS / comunicación / rack','sistema',null,'Según arquitectura fabricante');add('batProtection','Protecciones DC','Protección y seccionamiento BESS','juego',null,'Corriente, tensión y cortocircuito pendientes');add('batCom','Almacenamiento','Cable de comunicaciones BMS','m',null,'Protocolo y distancia según fabricante');add('batCable','Conductores','Conductores y terminales de batería','juego',null,'Según arquitectura, corriente, temperatura y fabricante')}if(has('ATS y respaldo')){add('ats','Transferencia','ATS y bypass','sistema',1,'Capacidad, polos y enclavamientos por ingeniería');add('panelAC','Distribución','Tablero AC y barras','sistema',null,'Según unifilar')}if(has('Generador'))add('gen','Respaldo',`Generador ${s.generator} kW`,'ud',s.generator?1:null,'Validar potencia y combustible');if(has('Carga EV'))add('ev','Movilidad','Cargadores EV / cuadro dedicado','sistema',null,'Número de puntos y simultaneidad por verificar');if(has('Obra civil')){for(let [k,n] of [['anchors','Anclajes estructurales'],['bolts','Tornillos y pernos'],['nuts','Tuercas'],['washers','Arandelas'],['seal','Sellado e impermeabilización']])add(k,'Obra civil',n,k==='seal'?'lote':'ud',null,'Cantidad según plano, unión y cálculo estructural');add('concrete','Obra civil','Hormigón, cabillas y encofrado','lote',null,'Volumen por levantamiento')}if(has('Monitorización')){add('ems','Monitorización','EMS / gateway','sistema',1,'Validar protocolos');add('meter','Monitorización','Medidor y transformadores de corriente','juego',null,'Relación y fases por verificar')}if(has('Climatización'))add('hvac','Climatización','Ventilación y acondicionamiento','sistema',null,'Carga térmica por fabricante');if(s.modules.length){for(let [k,f,n,note] of [['breaker','Protecciones AC','Interruptores y SPD AC','Cortocircuito, coordinación y tensión'],['acCable','Conductores','Cables AC, tierra, terminales y bandejas','Longitudes y ampacidad por estudio'],['earth','Seguridad','Puesta a tierra y equipotencialidad','Medición y norma aplicable'],['fire','Seguridad','Señalización, detección y protección contra incendios','Evaluación de riesgos'],['supplies','Consumibles','Bridas, etiquetas, cintas, terminales y repuestos','Desglose por montaje']])add(k,f,n,'lote',null,note)}if(has('Modernización eléctrica'))add('dist','Distribución','Tablero, barras y canalizaciones de modernización','sistema',null,'Según unifilar aprobado');return out.map(m=>({...m,...(s.overrides[m.key]||{})})).filter(m=>!m.excluded)}
function inventory(s){return [...(s.autoMaterials?suggestions(s):[]),...s.materials]}
function suggestionTable(s){let key='suggestions:'+s.id,items=suggestions(s).filter(m=>(invFamily==='Todas'||m.family===invFamily)&&(m.name+' '+m.family).toLowerCase().includes(invQuery.toLowerCase()));return `<div class="scroll"><table><tr><th>Familia / partida</th><th>Unidad</th><th>Cantidad</th><th>Criterio</th><th></th></tr>${pageSlice(items,key,15).map(m=>`<tr><td><small>${E(m.family)}</small><br><b>${E(m.name)}</b></td><td>${E(m.unit)}</td><td><input aria-label="Cantidad ${E(m.name)}" value="${E(m.qty)}" placeholder="Pendiente" onchange="override(${arg(m.key)},this.value)"></td><td>${E(m.note)}${m.installed!=null?`<small class="field-help">Instalación: ${E(m.installed)} · reserva: ${E(m.spare??0)}</small>`:''}</td><td>${B('Ficha',`materialSpecDialog(${arg(m.key)})`,'small')}${B('Excluir',`exclude(${arg(m.key)})`,'danger small')}</td></tr>`).join('')}</table></div>${pageControls(items,key,15)}`}
function override(k,v){let s=site();s.overrides[k]={...(s.overrides[k]||{}),qty:v===''?'':Math.max(0,Number(v)||0)};touch()}function exclude(k){site().overrides[k]={...(site().overrides[k]||{}),excluded:true};touch();render()}
function materials(){let s=site();return head('Inventario de materiales','Sugerencias en vivo + partidas manuales. Las cantidades desconocidas permanecen pendientes.','')+materialLinkNotice()+panel('Control de inventario',`<label class="check"><input type="checkbox" ${s.detailedBOM?'checked':''} onchange="setSite('detailedBOM',this.checked);render()"> Activar desglose individual (revisar las partidas agrupadas antes de cotizar)</label><div id="inventoryAudit">${inventoryAudit(s)}</div>`)+panel('Embalaje y logística',`<div id="logisticsSummary">${logisticsSummary(s)}</div>`)+panel('Motor de sugerencias',`<div class="row between"><label class="check"><input type="checkbox" ${s.autoMaterials?'checked':''} onchange="setSite('autoMaterials',this.checked);render()"> Incluir sugerencias automáticas en inventario y exportación</label>${B('Restablecer sugerencias',"site().overrides={};touch();render()")}</div><div id="sizing">${sizing(s)}</div><div class="fields"><label class="field">Buscar sugerencias<input placeholder="Material o familia" value="${E(invQuery)}" oninput="invQuery=this.value;resetListPage('suggestions:'+site().id);$('suggestionRows').innerHTML=suggestionTable(site())"></label><label class="field">Familia<select onchange="invFamily=this.value;resetListPage('suggestions:'+site().id);$('suggestionRows').innerHTML=suggestionTable(site())">${['Todas',...new Set(suggestions(s).map(m=>m.family))].map(v=>`<option ${v===invFamily?'selected':''}>${E(v)}</option>`).join('')}</select></label></div><div id="suggestionRows">${suggestionTable(s)}</div>`)+panel('Partidas manuales e importadas',B('Traer del catálogo','catalogDialog()','')+rowTable('materials',[['family','Familia'],['name','Material'],['unit','Unidad'],['qty','Cantidad'],['note','Criterio / ficha']]))+`<p class="notice">Las cantidades automáticas se recalculan cuando cambia el diseño. Una cantidad editada manualmente queda fijada hasta restablecer sugerencias.</p>`}
function catalogDialog(){if(!state.library.length)return toast('Catálogo vacío. Añade referencias desde Biblioteca técnica.');modal('Añadir del catálogo',`${comboField({id:'catalog',name:'id',label:'Artículo',display:'Seleccionar artículo…',placeholder:'Buscar por nombre, familia, marca o modelo…',helpText:'Abre el selector y escribe para filtrar todo el catálogo.'})}<label class="field">Cantidad<input name="qty" type="number" value="1" min="0.000001" step="any" required><small class="field-help">Cantidad en la unidad del artículo seleccionado.</small></label>`,f=>{let entry=state.library.find(x=>x.id===f.get('id')&&x.kind!=='consumer');if(!entry){toast('Selecciona un artículo del catálogo.');$('combo_catalog').open=true;$('catalogSearch').focus();return false}let m=copy(entry);m.qty=f.get('qty');m.catalogId=m.id;m.id=uid();site().materials.push(m);touch();render()},'Añadir artículo');catalogResults();$('catalogSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('catalogResults').querySelector('button')?.focus()}if(e.key==='ArrowDown'){e.preventDefault();$('catalogResults').querySelector('button')?.focus()}})}
function catalogResults(q=''){let el=$('catalogResults');if(!el)return;let tokens=normSearch(q).split(/\s+/).filter(Boolean);let matches=state.library.filter(m=>{if(m.kind==='consumer')return false;let text=normSearch([m.name,m.family,m.brand,m.model,m.power,m.voltage,m.note,m.unit,m.id].join(' '));return tokens.every(t=>text.includes(t))}).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es'));let selected=$('value_catalog')?.value;el.innerHTML=`<div class="catalog-count" role="status">${matches.length} de ${state.library.length} artículos</div>`+(matches.map(m=>`<button type="button" class="secondary picker-item catalog-option ${m.id===selected?'catalog-selected':''}" aria-pressed="${m.id===selected}" onclick="chooseCatalog(${arg(m.id)})">${E(m.name)}<small>${E([m.family,m.brand,m.model,m.power,m.voltage,m.unit].filter(Boolean).join(' · '))}</small></button>`).join('')||'<div class="combo-empty">Sin coincidencias. Prueba otra palabra.</div>')}
function chooseCatalog(id){let m=state.library.find(x=>x.id===id);if(!m)return;$('value_catalog').value=id;$('display_catalog').textContent=[m.name,m.family,m.brand,m.model].filter(Boolean).join(' · ');$('combo_catalog').open=false;$('catalogSearch').value='';catalogResults();$('modalForm').elements.qty.focus()}

function materialLibrary(){let items=state.library.filter(m=>m.kind!=='consumer'&&(libFamily==='Todas'||m.family===libFamily)&&(libVerified==='Todas'||(libVerified==='Verificadas')===!!m.verified)&&(m.name+' '+m.family+' '+(m.brand||'')+' '+(m.model||'')).toLowerCase().includes(libQuery.toLowerCase()));libPage=Math.min(libPage,Math.max(0,Math.ceil(items.length/18)-1));return head('Biblioteca técnica','Catálogo editable, compartido en el modo servidor. Las referencias iniciales del V8 requieren validación.',B('+ Referencia','libDialog()','')+B('Respaldo JSON',"downloadJSON('biblioteca',{kind:'library',library:state.library})"))+`<input style="max-width:450px" placeholder="Buscar material, marca o familia" value="${E(libQuery)}" onchange="libQuery=this.value;libPage=0;render()"><div class="fields"><label class="field">Familia<select onchange="libFamily=this.value;libPage=0;render()">${['Todas',...new Set(state.library.map(m=>m.family))].map(v=>`<option ${v===libFamily?'selected':''}>${E(v)}</option>`).join('')}</select></label><label class="field">Validación<select onchange="libVerified=this.value;libPage=0;render()">${['Todas','Verificadas','Por validar'].map(v=>`<option ${v===libVerified?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="muted" style="margin:12px 0">${items.length} referencias · Página ${libPage+1} de ${Math.max(1,Math.ceil(items.length/18))}</p><div class="grid projectgrid">${items.slice(libPage*18,libPage*18+18).map(m=>`<article class="tile"><span class="glyph">▥</span>${menu([['Editar ficha',`libDialog(${arg(m.id)})`],['Eliminar',`deleteLib(${arg(m.id)})`,'danger']])}<small>${E(m.family)}</small><h3 style="padding-right:20px">${E(m.name)}</h3><p>${E(m.brand||'Marca por confirmar')} · ${E(m.model||'Modelo por confirmar')}</p><p>${E(m.note)}</p><span class="chip">${m.verified?'Verificada':'Por validar'}</span>${B('Editar ficha',`libDialog(${arg(m.id)})`,'open')}</article>`).join('')||empty('Sin coincidencias.')}</div><div class="actions" style="margin-top:20px">${B('Anterior','libPage=Math.max(0,libPage-1);render()')}${Array.from({length:Math.max(1,Math.ceil(items.length/18))},(_,i)=>B(String(i+1),`libPage=${i};render()`,i===libPage?'':'secondary')).join('')}${B('Siguiente',`libPage=Math.min(${Math.max(0,Math.ceil(items.length/18)-1)},libPage+1);render()`)}</div>`}
function libDialog(id){let m=state.library.find(x=>x.id===id)||{id:uid()};modal('Ficha de material',`<div class="fields">${[['Familia','family'],['Nombre','name'],['Unidad','unit'],['Marca','brand'],['Modelo','model'],['Potencia','power'],['Tensión','voltage'],['Volumen CBM','cbm'],['Proveedor (privado)','supplier'],['Costo EXW (privado)','cost'],['Ficha técnica / enlace','datasheet']].map(([l,k])=>k==='family'?modalSelect(l,k,m[k]||'', [...new Set(state.library.map(x=>x.family)), 'Otros']):k==='unit'?modalSelect(l,k,m[k]||'ud',['ud','m','m²','m³','kg','juego','kit','rollo','caja','lote','sistema','litro']):mfield(l,k,m[k]||'','text',k==='name')).join('')}</div><h3>Características específicas</h3>${equipmentFields(m)}<label class="check"><input name="habitual" type="checkbox" ${m.habitual?'checked':''}> Material habitual de instalación</label><label class="field">Criterios y compatibilidad<textarea name="note">${E(m.note||'')}</textarea></label><label class="check"><input name="verified" type="checkbox" ${m.verified?'checked':''}> Referencia validada por especialista</label>`,f=>{Object.assign(m,Object.fromEntries(f),{verified:f.has('verified'),habitual:f.has('habitual')});if(!id)state.library.push(m);touch();render()})}
function deleteLib(id){if(confirm('¿Eliminar referencia del catálogo? No afecta las copias ya incorporadas a proyectos.')){state.library=state.library.filter(x=>x.id!==id);touch();render()}}
function gallery(proposal){let s=site(),types=proposal?['Propuesta','Plano','Evidencia']:['Original','Inspección'];let key='gallery:'+s.id+':'+proposal,a=s.images.map((m,i)=>({...m,i})).filter(m=>types.includes(m.type));return head(proposal?'Propuesta visual':'Galería original',proposal?'Diseños, planos y comparación de la solución propuesta.':'Fotografías de la empresa y del levantamiento técnico.',B('+ Añadir imágenes',`imageDialog(${proposal})`,''))+`<div class="grid projectgrid">${pageSlice(a,key,9).map(m=>`<article class="tile"><img class="asset" data-ev-gallery-image="${m.i}" loading="lazy" decoding="async" alt="${E(m.name)}"><h3>${E(m.name)}</h3>${proposal?(m.designSnapshot===visualSignature(s)?'<p class="notice">Coincide con la configuración registrada.</p>':'<p class="warn">Propuesta sin revisar para el diseño actual.</p>')+B('Confirmar revisión del diseño',`reviewVisual(${m.i})`):`<label class="field">Observaciones técnicas / medición<textarea oninput="visualInput('images',${m.i},'technicalObservation',this.value)" onblur="commitVisualInput()">${E(m.technicalObservation||'')}</textarea></label>`}<label class="field">Zona<input value="${E(m.zone)}" oninput="visualInput('images',${m.i},'zone',this.value)" onblur="commitVisualInput()"></label><label class="field">Descripción<textarea oninput="visualInput('images',${m.i},'caption',this.value)" onblur="commitVisualInput()">${E(m.caption)}</textarea></label><label class="field">Trabajo previsto<textarea oninput="visualInput('images',${m.i},'work',this.value)" onblur="commitVisualInput()">${E(m.work||'')}</textarea></label>${proposal?`<label class="field">Vincular original<select onchange="editAsset('images',${m.i},'originalId',this.value);render()"><option value="">Comparar por zona</option>${s.images.filter(o=>['Original','Inspección'].includes(o.type)).map(o=>`<option value="${E(o.assetId||'')}" ${m.originalId&&m.originalId===o.assetId?'selected':''}>${E(o.zone+' · '+o.name)}</option>`).join('')}</select></label>`:''}<label class="field">Categoría<select onchange="editAsset('images',${m.i},'type',this.value);render()">${['Original','Inspección','Propuesta','Plano','Evidencia'].map(t=>`<option ${t===m.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="check"><input type="checkbox" ${m.publish?'checked':''} onchange="editAsset('images',${m.i},'publish',this.checked)"> Autorizar para cliente</label>${B('Eliminar',`removeRow('images',${m.i})`,'danger small')}</article>`).join('')||empty('Añade imágenes propias de esta instalación.')}</div>${pageControls(a,key,9)}`+(proposal?panel('Comparación por zona',compareGallery(s)+B('Copiar instrucciones para generar propuesta','copyPrompt()')):'')}
function safeImage(d){return /^data:image\/(png|jpeg|gif|webp|avif);base64,[A-Za-z0-9+/=]+$/.test(d||'')?d:''}
function compareGallery(s){let originals=s.images.map((m,i)=>({...m,i})).filter(m=>['Original','Inspección'].includes(m.type)),proposals=s.images.map((m,i)=>({...m,i})).filter(m=>m.type==='Propuesta');return proposals.map(p=>{let o=originals.find(o=>p.originalId&&o.assetId===p.originalId)||originals.find(o=>o.zone===p.zone);return o?`<div class="grid two" style="margin-bottom:10px"><div><small>Antes · ${E(o.zone)}</small><img class="asset" data-ev-gallery-image="${o.i}" loading="lazy" decoding="async"></div><div><small>Propuesta · ${E(p.zone)}</small><img class="asset" data-ev-gallery-image="${p.i}" loading="lazy" decoding="async"></div></div>`:''}).join('')||empty('Asigna la misma zona a una foto original y una propuesta.')}
async function copyPrompt(){let s=site(),p=project(),m=capacity(s),t=`Diseñar una propuesta visual realista de la instalación ${s.name} para ${cname(p)}. Objetivo: ${p.objective}. Preservar geometría y fotos originales; no inventar dimensiones. Equipos: ${s.panels} paneles, ${m.pv} kWp, ${m.inv} kW inversores, ${m.bat} kWh baterías. Zonas: ${[...new Set(s.images.map(a=>a.zone))].join(', ')}. Consideraciones: ${s.roof}.`;try{await navigator.clipboard.writeText(t);toast('Instrucciones copiadas')}catch{modal('Instrucciones',`<textarea readonly>${E(t)}</textarea>`,()=>{})}}
function editAsset(k,i,f,v){site()[k][i][f]=v;touch()}
async function upload(files,k,type){let s=site();for(let f of files){if(f.size>15*1024*1024){toast('Máximo 15 MB por archivo: '+f.name);continue}if(k==='images'&&!/^image\/(png|jpeg|gif|webp|avif)$/.test(f.type)){toast('Formato de imagen no admitido');continue}let data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});s[k].push({name:f.name,data,zone:'General',type,caption:'',publish:false})}touch();render()}
function generatedBase(s,p,t){let m=energy(s),common=`${cname(p)} · ${p.name}\nInstalación: ${s.name}\nObjetivo: ${p.objective||'Por definir'}\n`;let values=`Generación: ${fmt(m.pv)} kWp (${s.modules.includes('Fotovoltaica')?s.panels:0} módulos).\nInversores: ${fmt(m.inv)} kW.\nAlmacenamiento: ${fmt(m.nominalBattery)} kWh nominales; ${fmt(m.bat)} kWh efectivos.\nDemanda del período (${m.rows.length} h): ${fmt(m.loadTotal)} kWh; pico ${fmt(m.peak)} kW.\nCalendario semanal: ${calendarSummary(s)}\nPerfil de demanda: ${loadModeSummary(s)}\nPeríodo simulado: ${simPeriod(m)}; SOC inicial ${socText(m.rows[0].socStart,m.bat)}.\nBalance simulado: ${fmt(m.pvTotal)} kWh FV y ${fmt(m.unmet)} kWh no atendidos.${s.modules.includes('Generador')&&s.genEnabled?`\nGenerador: ${fmt(s.generator)} kW; ${m.rows.filter(a=>a.genRunning).length} h de aporte; ${fmt(m.genTotal)} kWh totales, ${fmt(m.rows.reduce((n,a)=>n+a.genRecharge,0))} kWh a recarga. Validar conexión, potencia y control con fabricante.`:''}`;let specific={ 'Levantamiento técnico':`Red: ${s.voltage} V, ${s.phases} fases, ${s.frequency} Hz (por confirmar).\nCubierta: ${s.roof||'Pendiente de inspección'}.\n${s.gridNotes}\n${s.notes}`, 'Memoria descriptiva':`1. Necesidad y objetivo: ${p.objective||'Pendiente de definición con el cliente'}.\n2. Alcance: ${s.modules.join(', ')||'Por definir'}.\n3. Configuración preliminar:\n${values}\n4. Implantación: ${s.location||'Ubicación por confirmar'}.\n5. Validación: completar levantamiento, fichas, planos y medidas antes de aprobar suministros.`,'Ingeniería y protecciones':`${values}\nStrings: ${s.strings||'Por calcular'}; MPPT: ${s.mppt||'Por confirmar'}; optimizadores: ${s.optimize?'previstos':'no previstos'}.\n${s.compatibility}\nValidar protecciones, secciones, selectividad y compatibilidad.`, 'Cargas prioritarias':calendarSummary(s)+'\n'+loadModeSummary(s)+'\n'+(s.loads.map(r=>`${r.name}: ${r.kw} kW × ${r.qty}; ${r.priority}`).join('\n')||'Clasificación de cargas pendiente.'), 'Plan de ejecución':'1. Levantamiento y revisión de condiciones existentes.\n2. Ingeniería aprobada, coordinación de accesos y seguridad.\n3. Recepción e inspección de suministros y fichas.\n4. Adecuaciones civiles y estructuras según planos aprobados.\n5. Montaje eléctrico, señalización, verificación y puesta en servicio por personal competente.\n6. Pruebas, capacitación, documentación final y entrega. Ajustar al cronograma.', 'Seguridad industrial':`Riesgos registrados: ${s.risks||'Pendientes de evaluación'}.\n1. Evaluar riesgos y permisos de trabajo antes de iniciar.\n2. Bloqueo y etiquetado (LOTO), verificación de ausencia de tensión y personal competente.\n3. Plan de acceso, izaje y protección frente a caídas; validar cubierta y estructura.\n4. Evaluar riesgo de incendio, ventilación y baterías con fabricante y responsables del local.\n5. Señalización, rutas de evacuación, emergencia y registro de incidencias.\nNo sustituye la evaluación de riesgos específica del sitio.`, 'Monitorización':s.modules.includes('Monitorización')?'Prever medición de red, producción, SOC, alarmas y comunicaciones según compatibilidad.':'Módulo no seleccionado; revisar alcance.', 'Garantías y mantenimiento':'1. Garantía: confirmar plazo, cobertura, exclusiones y condiciones de aceptación por fabricante y contrato.\n2. Mantenimiento preventivo: inspección visual, limpieza según suciedad, revisión de alarmas, ventilación y registros.\n3. Mantenimiento eléctrico: especialista autorizado, con aislamiento seguro; revisar conexiones, protecciones y puesta a tierra conforme fabricante.\n4. Registro de incidencias, intervenciones y repuestos. Frecuencias definitivas según manual y entorno.', 'Pruebas y entrega':'1. Recepción: contrastar referencias, cantidades y estado físico con fichas.\n2. Verificación previa: continuidad, polaridad, puesta a tierra y protecciones conforme protocolo aprobado.\n3. Pruebas funcionales: transferencia, alarmas, comunicaciones, cargas y respuesta de respaldo.\n4. Registrar resultados, desviaciones y acciones correctivas; no aceptar si quedan defectos de seguridad.\n5. Entregar documentación final, manuales y formación. Los criterios cuantitativos se acuerdan en ingeniería.', 'Ampliaciones y límites':`${values}\nAmpliaciones condicionadas por capacidad de red, cubierta, protecciones, BMS y estudio de ingeniería. Verificar reserva física, potencia de conexión, espacio y ventilación antes de ampliar.`, 'Memoria de cálculo':`${values}\nPotencia FV = módulos × vatios / 1000. Energía útil AC = batería nominal × DoD × eficiencia de descarga. Perfil horario: ${m.rows.length} intervalos consecutivos de una hora. Rendimiento FV ${s.pr}%, HSP ${s.sun}, DoD ${s.dod}%, eficiencia ${s.eff}%. No incluye transitorios ni cálculo normativo.`};return common+(specific[t]||values)+'\n\nAnteproyecto: confirmar datos y cálculos antes de ejecutar.'}
function docs(){let s=site();return head('Documentación','Memorias técnicas con contenido automático vinculado y texto editable separado.')+`<div class="tabs">${DOC.map(t=>B(t,`docTab=${arg(t)};render()`,docTab===t?'active':'')).join('')}</div>`+panel(docTab,`<div class="notice">El bloque automático cambia con el proyecto. Tu redacción se conserva en un bloque independiente.</div><div class="paper" id="docLive">${E(generated(s,project(),docTab))}</div><label class="field">Redacción y observaciones propias<textarea style="min-height:160px" oninput="site().docs[docTab]=this.value;touch()">${E(s.docs[docTab]||'')}</textarea></label><div class="actions">${B('Imprimir documento','printDocument()')}${B('Descargar texto','downloadTextDoc()')}</div>`)+(s.legacyPrivate?panel('Notas recuperadas de V1 · privadas',`<p class="warn">Copia de notas originales de la versión antigua. No se exporta automáticamente.</p><pre class="paper">${E(JSON.stringify(s.legacyPrivate,null,2))}</pre>`):'')+panel('Documentos complementarios',`<p class="notice">Archivos externos: planos, fichas del fabricante, informes del cliente, autorizaciones y estudios. Autoriza solo documentos revisados y sin información privada.</p><input type="file" multiple onchange="upload(this.files,'files','Documento')">${s.files.map((a,i)=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><span>${E(a.name)}</span><label class="check"><input type="checkbox" ${a.publish?'checked':''} onchange="editAsset('files',${i},'publish',this.checked)"> Autorizar para cliente</label>${B('Descargar',`downloadAsset('files',${i})`)}${B('Eliminar',`removeRow('files',${i})`,'danger small')}</div>`).join('')}`)}
function downloadTextDoc(){download(docTab+'.txt',generated(site(),project(),docTab)+'\n\n'+(site().docs[docTab]||''),'text/plain;charset=utf-8')}
function printDocument(){let h=clientPage(docTab,`<section><pre>${E(generated(site(),project(),docTab)+'\n\n'+(site().docs[docTab]||''))}</pre></section>`,false);openPrintable(h)}
function schedule(){let s=site();return head('Cronograma','Fechas, responsables y estado de actividades de esta instalación.',B('Cargar fases habituales','defaultTasks()')+B('Fases de fabricación y transporte','addLogisticsTasks()'))+panel('Actividades',rowTable('tasks',[['name','Actividad'],['start','Inicio','date'],['end','Fin','date'],['owner','Responsable'],['status','Estado'],['progress','Avance %','number'],['weight','Peso relativo','number'],['dependsOn','Depende de (nombre exacto)']]))+panel('Avance global',`<div id="taskProgress">${taskProgress(s)}</div>`)+panel('Calendario y alertas',`<div id="timelineCalendar">${timelineCalendar(s)}</div>`)}
function taskProgress(s){let w=t=>t.weight==null||t.weight===''?1:Math.max(0,+t.weight||0),total=s.tasks.reduce((a,t)=>a+w(t),0),n=total?Math.round(s.tasks.reduce((a,t)=>a+w(t)*Math.min(100,Math.max(0,+t.progress||0)),0)/total):0;return `<strong>${n}%</strong><div class="progress"><i style="width:${n}%"></i></div>`}
function defaultTasks(){if(site().tasks.length&&!confirm('¿Agregar fases habituales sin borrar las existentes?'))return;for(let name of ['Levantamiento','Ingeniería','Suministros','Obra civil','Instalación','Pruebas','Entrega'])if(!site().tasks.some(t=>String(t.name).trim().toLowerCase()===name.toLowerCase()))site().tasks.push({id:uid(),name,start:'',end:'',owner:'',status:'Pendiente',progress:0,weight:1});touch();render()}
function costKey(m,i){return m.key?'auto:'+m.key+(m.designCatalogId?':ref:'+m.designCatalogId:''):'manual:'+(m.id||i)}
function linkedCosts(s){return inventory(s).map((m,i)=>{let k=costKey(m,i),c=s.materialCosts?.[k]||{},stale=c.quoteSignature&&c.quoteSignature!==quoteSignature(m);return {key:k,name:m.name,qty:m.qty,cost:stale?'':c.cost??'',currency:c.currency||'USD',staleQuote:Boolean(stale)}})}
function editLinked(k,f,v){let s=site();s.materialCosts[k]={...(s.materialCosts[k]||{}),[f]:v};if(f==='cost'||f==='currency'){delete s.materialCosts[k].quoteSignature;delete s.materialCosts[k].quoteId;if(s.privateFinance)s.privateFinance.confirmed=false}touch()}
function linkedTable(s){return `<div class="scroll"><table><tr><th>Material del inventario</th><th>Cantidad vinculada</th><th>Costo unitario</th><th>Moneda</th><th>Subtotal</th></tr>${linkedCosts(s).map(m=>`<tr><td>${E(m.name)}</td><td>${E(m.qty===''?'Pendiente':m.qty)}</td><td><input type="number" min="0" step="any" value="${E(m.cost)}" placeholder="Sin costo" oninput="editLinked(${arg(m.key)},'cost',this.value)"></td><td><input value="${E(m.currency)}" oninput="editLinked(${arg(m.key)},'currency',this.value)"></td><td id="cost_${E(m.key)}">${m.qty===''||m.cost===''?'Pendiente':fmt((+m.qty||0)*(+m.cost||0),2)}</td></tr>`).join('')}</table></div>`}
function budgetTotals(s){let totals={};for(let r of [...s.budget,...linkedCosts(s).filter(m=>m.qty!==''&&m.cost!=='')]){let c=r.currency||'USD';totals[c]=(totals[c]||0)+(+r.qty||0)*Math.max(0,+r.cost||0)}return Object.entries(totals).map(([k,v])=>metric(fmt(v,2)+' '+k,'Costo directo')).join('')||metric('0','Sin partidas')}
function budget(){if(!canSeeFinance())return head('Acceso restringido','Solo el administrador puede acceder a los presupuestos privados.');return head('Presupuesto privado','Solo para uso interno. Nunca se incorpora como módulo al expediente técnico del cliente.')+panel('Materiales vinculados al inventario',`<p class="notice">Las cantidades se actualizan al cambiar el diseño. Introduce precios unitarios una vez; las partidas sin cantidad o costo permanecen pendientes.</p>${linkedTable(site())}`)+panel('Partidas económicas adicionales',rowTable('budget',[['name','Concepto'],['qty','Cantidad','number'],['cost','Costo unitario','number'],['currency','Moneda']]))+panel('Totales por moneda',`<div class="grid" id="budgetTotals">${budgetTotals(site())}</div><p class="muted">No se suman monedas distintas ni se aplican tasas implícitas. Los materiales sin costo o cantidad no se incluyen en el total.</p>`)+quotePanel(site())+financePanel(site())+commercialPanel(site())}
function versions(){let p=project(),rel=state.projects.filter(x=>x.parentId===p.id||p.parentId===x.id||(p.parentId&&p.parentId===x.parentId&&x.id!==p.id));return head('Alternativas y revisiones','Una alternativa es otro diseño; una revisión es una copia histórica del mismo expediente.',B('Nueva alternativa',`duplicate(${arg(p.id)},true)`,'')+(canSeeFinance()?B('Guardar revisión','saveRevision()'):'')+(shared&&me?.role==='admin'?B('Permisos de acceso','projectAccessDialog()'):''))+panel('Cómo utilizar esta sección','<p>Una alternativa es otro diseño para la misma empresa, sin modificar el original. Una revisión conserva una copia histórica antes de cambiar parámetros. Restaurarla como copia mantiene intacto el expediente actual.</p>')+panel('Alternativas relacionadas',`<div class="grid projectgrid">${rel.map(projectCard).join('')||empty('Sin alternativas.')}</div>`)+(rel.length?panel('Comparar alternativas',alternativeComparison([p,...rel]))+comparisonPanel([p,...rel])+panel('Comparación para cliente',B('Ver informe comparativo', 'clientAlternativeReport([project(),...state.projects.filter(x=>x.parentId===project().id||project().parentId===x.id||(project().parentId&&project().parentId===x.parentId&&x.id!==project().id))])')):'')+(shared&&me?.role!=='admin'?panel('Historial de revisiones','<p>Las revisiones privadas están reservadas al administrador.</p>'):panel('Historial de revisiones',p.revisions.map((v,i)=>`<div class="row between"><span>${E(v.label)} · ${E(v.date)}</span>${B('Restaurar como copia',`restoreRevision(${i})`)}</div>`).join('')||empty('Sin revisiones.')))}
function saveRevision(){let p=project();modal('Guardar revisión',`<p>Conserva el estado actual antes de modificar el diseño. Puedes recuperar esta revisión como una copia sin perder el expediente activo.</p>`+mfield('Etiqueta','label','Revisión '+(p.revisions.length+1),'text',true),f=>{let snapshot=copy(p);snapshot.revisions=[];p.revisions.push({label:f.get('label'),date:now(),data:snapshot});p.version=f.get('label');touch();render()})}
function restoreRevision(i){let p=project(),r=p.revisions[i],q=resetCommercialCopy(copy(r.data));q.id=uid();q.name+=' · '+r.label;q.parentId=p.id;q.status='Borrador';q.created=q.updated=now();state.projects.push(q);touch();openProject(q.id)}
function templates(){return head('Plantillas','Reutiliza módulos y criterios, sin copiar datos privados ni fotografías de clientes.',B('Guardar desde proyecto','templateDialog()',''))+`<div class="grid projectgrid">${allTemplates().map(t=>`<article class="tile"><small>${t.builtin?'Incluida · editable al crear':'Personalizada'}</small><h3>${E(t.name)}</h3><p>${E(t.modules.join(', '))}</p>${B('Crear proyecto con plantilla',`applyTemplate(${arg(t.id)})`,'open')}${t.builtin?'':B('Eliminar',`deleteTemplate(${arg(t.id)})`,'danger small')}</article>`).join('')||empty('No hay plantillas.')}</div>`}
function templateDialog(){if(!state.projects.length)return toast('Crea primero un proyecto.');modal('Crear plantilla',mfield('Nombre','name','','text',true)+`<label class="field">Proyecto<select name="pid">${state.projects.map(p=>`<option value="${E(p.id)}">${E(p.name)}</option>`).join('')}</select></label>`,f=>{let p=state.projects.find(p=>p.id===f.get('pid')),s=p.sites[0];state.templates.push({id:uid(),name:f.get('name'),type:p.type,modules:copy(s.modules),criteria:Object.fromEntries([...templateKeys].filter(k=>s[k]!==undefined).map(k=>[k,copy(s[k])]))});touch();render()})}
function applyTemplate(id){let t=allTemplates().find(t=>t.id===id),cs=state.companies.filter(c=>!c.archived);if(!cs.length)return companyDialog();modal('Proyecto desde plantilla',mfield('Nombre','name','','text',true)+`<label class="field">Empresa<select name="cid">${cs.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('')}</select></label>`,f=>{let p=newProject(f.get('cid'),f.get('name'),'',t.type,t.modules,['Sede principal']);applyTemplateCriteria(applyDefaultCriteria(p.sites[0]),t);state.projects.push(p);touch();openProject(p.id)})}
