function refreshDerived(){if(offlineReady&&page==='tools')saveOfflineCalculator();let s=page==='tools'?calcSite:site()||calcSite;if($('logisticsSummary'))$('logisticsSummary').innerHTML=logisticsSummary(s);if($('loadDesignAudit'))$('loadDesignAudit').innerHTML=loadDesignAudit(s);for(let c of s.designCircuits||[])if($('circuit-'+c.id))$('circuit-'+c.id).innerHTML=circuitResult(c);if($('mountingResult'))$('mountingResult').innerHTML=mountingResult(s);if($('liveBars'))$('liveBars').innerHTML=liveBars(s);if($('acArchitectureResult'))$('acArchitectureResult').innerHTML=acArchitectureResult(s);if($('groupDispatchResult'))$('groupDispatchResult').innerHTML=groupDispatchHTML(s);if($('engineeringAudit'))$('engineeringAudit').innerHTML=engineeringAudit(s);if($('oemReviewResult'))$('oemReviewResult').innerHTML=oemReviewHTML(s);if($('designLinkSummary'))$('designLinkSummary').textContent=designLinkSummary(s);if($('fuelResult'))$('fuelResult').innerHTML=fuelSummary(s);if($('timelineCalendar'))$('timelineCalendar').innerHTML=timelineCalendar(s);if($('financeSummary'))$('financeSummary').innerHTML=financeSummary(s);if($('integrityHTML'))$('integrityHTML').innerHTML=integrityHTML(s);syncDemandControls(s);if($('inventoryAudit'))$('inventoryAudit').innerHTML=inventoryAudit(s);if($('pvSummary'))$('pvSummary').innerHTML=pvSummaryHTML(s);if($('loadModeSummary'))$('loadModeSummary').textContent=loadModeSummary(s);if($('keyMetrics'))$('keyMetrics').innerHTML=keyMetrics(s);if($('simResult'))$('simResult').innerHTML=result(s);if($('restHours'))$('restHours').textContent=`Jornada restante: ${24-s.hours} horas · Total: 24 horas${s.useLoads?' · Perfil de equipos activo':''}`;if($('energySummary'))$('energySummary').innerHTML=energyMetrics(s);if($('sizing'))$('sizing').innerHTML=sizing(s);if($('suggestionRows')&&!document.activeElement?.closest('#suggestionRows'))$('suggestionRows').innerHTML=suggestionTable(s);if($('docLive'))$('docLive').textContent=generated(s,project(),docTab);if($('taskProgress'))$('taskProgress').innerHTML=taskProgress(s);if($('budgetTotals')){$('budgetTotals').innerHTML=budgetTotals(s);for(let m of linkedCosts(s)){let el=$('cost_'+m.key);if(el)el.textContent=m.qty===''||m.cost===''?'Pendiente':fmt((+m.qty||0)*Math.max(0,+m.cost||0),2)}}}
function download(name,data,type='application/octet-stream'){let b=data instanceof Blob?data:new Blob([data],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
const recommendedBackupBytes=40*1024*1024;
function backupSizeText(bytes){return (bytes/1024/1024).toFixed(1)+' MiB'}
function confirmLargeBackup(bytes,action){
 if(bytes<=recommendedBackupBytes)return true;
 return confirm('Respaldo de gran tamaño\n\nTamaño: '+backupSizeText(bytes)+' · Recomendado: 40 MiB.\n'+(action==='importar'?'La recuperación puede consumir más memoria y tiempo. Los registros se añaden como copias; revisa posibles duplicados.':'La descarga puede requerir más memoria, tiempo y espacio en disco. Un archivo grande puede superar la capacidad de recuperación o sincronización.')+'\n\nNo se eliminarán adjuntos automáticamente. ¿Deseas '+action+' de todas formas?');
}
function approveImportedWorkspace(next){
 const bytes=new TextEncoder().encode(JSON.stringify(next)).length;
 if(globalThis.EVEngineeringStore&&bytes>200*1024*1024)throw Error('La base resultante supera el límite técnico de 200 MiB. Conserva el original y recupera por proyectos; no se modificaron los datos.');
 return confirmLargeBackup(bytes,'importar');
}
function downloadJSON(name,obj){const json=JSON.stringify({schema:3,release:'3.5-desarrollo',exported:now(),...obj});if(['workspace','project','company','library','workspace-sync'].includes(obj.kind)&&!confirmLargeBackup(new TextEncoder().encode(json).length,'descargar el respaldo'))return false;download(name+'.json',json,'application/json');return true}
