function backupCompany(id){downloadJSON('EV_empresa_'+slug(company(id).name)+'_privado',{kind:'company',companies:[company(id)],projects:state.projects.filter(p=>p.companyId===id),library:[],templates:[]})}
function backupAll(){downloadJSON('EV_Studio_respaldo_general_privado',{kind:'workspace',...state})}
function backups(){return head('Respaldos generales','Copia privada de todo el espacio empresarial. Los archivos están incluidos en JSON como datos codificados.')+panel('Exportar espacio de trabajo',`<p class="warn">Incluye información comercial, documentos e imágenes originales. No entregar al cliente.</p>${B('Descargar respaldo cifrado','backupPasswordDialog()','')}${B('Descargar respaldo general JSON sin cifrar','backupAll()')}`)+mergePanel()+panel('Importar V1 / V2 / V3 o respaldo cifrado',`<p class="muted">La importación añade registros como copias y no reemplaza los existentes. Se conservan los datos locales actuales.</p><input type="file" accept=".json,.evbackup,application/json" onchange="restoreFile(this.files[0])">`)+panel('Ejemplo técnico',`<p>Crear un anteproyecto demostrativo con los parámetros de referencia. No representa una medición aprobada.</p>${B('Cargar ejemplo','demo()')}`)}
