async function restoreFile(f){if(!f)return;try{if(f.size>280*1024*1024)throw Error('Respaldo superior a 280 MiB. Conserva el original.');let raw=JSON.parse(await f.text());if(raw?.format==='EVStudioEncryptedBackup'){modal('Abrir respaldo cifrado',`<p>Introduce la contraseña del respaldo. Se añadirá como copia; no reemplaza tus datos actuales.</p><label class="field">Contraseña<input name="password" type="password" required autocomplete="off"></label>`,async form=>{try{let decoded=await decryptBackup(raw,form.get('password'));return importWorkspace(decoded)!==false}catch(e){toast('No se pudo abrir el respaldo: '+e.message);return false}},'Descifrar e importar');return}importWorkspace(raw)}catch(e){toast('No se pudo importar: '+e.message)}}
function validImportedValue(v,depth=0){if(depth>40)return false;if(v===null||typeof v==='string'||typeof v==='boolean')return true;if(typeof v==='number')return Number.isFinite(v);if(Array.isArray(v))return v.length<=50000&&v.every(x=>validImportedValue(x,depth+1));if(!v||typeof v!=='object')return false;let ks=Object.keys(v);return ks.length<=20000&&ks.every(k=>k.length<=512&&!['__proto__','constructor','prototype'].includes(k)&&validImportedValue(v[k],depth+1))}
function importWorkspace(raw){if(!validImportedValue(raw))throw Error('Datos inválidos o claves no admitidas');let next=copy(state);if(raw.kind==='library'){if(!Array.isArray(raw.library)||!raw.library.every(m=>m&&typeof m==='object'&&!Array.isArray(m)&&typeof m.name==='string'))throw Error('Biblioteca inválida');for(let m of raw.library)next.library.push({...m,id:uid()});if(!approveImportedWorkspace(next))return false;state=next;touch();nav('library');return true}let r=normalize(raw),mapping=new Map(),ids=new Map();for(let c of r.companies){if(!c||typeof c.id!=='string'||mapping.has(c.id))throw Error('Identificadores de empresa duplicados o inválidos');let c2=copy(c);c2.id=uid();mapping.set(c.id,c2.id);next.companies.push(c2)}for(let q of r.projects){if(!q||typeof q.id!=='string'||ids.has(q.id)||!Array.isArray(q.sites)||!q.sites.length)throw Error('Expediente duplicado o sin instalaciones');ids.set(q.id,uid());let siteIds=new Set();for(let a of q.sites){if(!a||typeof a.id!=='string'||siteIds.has(a.id)||!Array.isArray(a.modules)||!Array.isArray(a.loads)||!Array.isArray(a.materials))throw Error('Instalación inválida o duplicada');siteIds.add(a.id);for(let k of ['files','images','tasks','budget','scenarios','outages'])if(!Array.isArray(a[k])||a[k].some(v=>!v||typeof v!=='object'||Array.isArray(v)))throw Error('Lista técnica inválida: '+k);}}for(let q of r.projects){q.id=ids.get(q.id);q.companyId=mapping.get(q.companyId)||q.companyId;if(!next.companies.some(c=>c.id===q.companyId)){let c={...newCompany(),name:'Empresa recuperada'};next.companies.push(c);q.companyId=c.id}q.parentId=ids.get(q.parentId)||'';q.revisions=q.revisions||[];for(let rev of q.revisions){if(rev.data){rev.data.companyId=q.companyId;rev.data.parentId=''}}next.projects.push(q)}for(let m of r.library)if(!next.library.some(x=>x.id===m.id||x.name===m.name&&x.family===m.family))next.library.push({...m,id:uid()});for(let t of r.templates)next.templates.push({...t,id:uid()});if(!approveImportedWorkspace(next))return false;state=next;touch();nav('projects');toast('Importación completada como copia');return true}
function demo(){let c={...newCompany(),name:'Empresa demostrativa · Ficticia',type:'Empresa estatal'},p=newProject(c.id,'Continuidad energética','Anteproyecto de respaldo y generación solar','Solar híbrido',['Fotovoltaica','Baterías','ATS y respaldo','Obra civil','Monitorización'],['Sede principal']);Object.assign(p.sites[0],{work:66,rest:20,panels:120,watts:600,inverter:70,battery:200,bpower:70,gridLimit:100,gridCharge:40,outStart:8,outHours:4,optimize:true,strings:8,mppt:8});state.companies.push(c);state.projects.push(p);touch();openProject(p.id)}
function settings(){if(globalThis.EVEngineeringStore)return head('Configuración','Espacio privado de Bonaire.')+panel('Modo de trabajo',globalThis.EVEngineeringStore.scope==='online'?'<p>Ingeniería online · guardado por revisión en el servidor. No se usa la base SQLite local.</p><p>Las actualizaciones se publican desde Bonaire.</p>':'<p>Ingeniería Windows · guardado cifrado local. Sincroniza con Bonaire cuando estés conectado.</p><p>La actualización se realiza con el instalador oficial de Windows.</p>')+securityPanel()+identityPanel()+settingsDefaultsPanel()+panel('Información del espacio',`<p>${state.companies.length} empresas · ${state.projects.length} expedientes · ${state.library.length} referencias.</p><p>Versión ${E(globalThis.EVPRO_CURRENT_RELEASE)} · Estado: ${E(lastSave)}</p>`);return head('Configuración','Estado del almacenamiento y colaboración empresarial.')+updatePanelV36()+panel('Modo de trabajo',`<p>${shared?'Servidor SQLite compartido · usuario '+E(me?.username):'Modo local: almacenamiento IndexedDB de este navegador.'}</p><div class="notice">${shared?'Consulta del servidor cada cinco segundos; el guardado de cambios depende de la casilla Autoguardado. Los cambios de diferentes expedientes pueden guardarse simultáneamente. Si dos usuarios modifican el mismo registro, se detiene la sincronización para evitar sobrescritura.':'Puedes trabajar sin servidor. SQLite y el almacenamiento del navegador son independientes; transfiere expedientes mediante un respaldo privado. Para trabajo multiusuario, utiliza el modo empresarial opcional con autenticación.'}</div>${collision?`<p class="warn">Conflicto detectado. Descarga el respaldo local antes de recuperar la última versión del servidor.</p>${B('Guardar copia privada','backupAll()','')}${B('Descartar cambios locales y cargar servidor','discardConflict()','danger')}`:''}`)+securityPanel()+identityPanel()+settingsDefaultsPanel()+databaseBackupPanel()+panel('Información del espacio',`<p>Versión ${E(globalThis.EVPRO_CURRENT_RELEASE||'3.7.0-prueba')} · ${state.companies.length} empresas · ${state.projects.length} expedientes · ${state.library.length} referencias.</p><p>Estado: ${E(lastSave)}. Usa respaldos periódicos; el almacenamiento local depende del navegador.</p>`)+panel('Protección y continuidad','<p>La base local es por navegador. La base compartida requiere un equipo servidor encendido. En red no confiable, utiliza HTTPS o VPN; no expongas directamente el servidor a internet.</p>')+(typeof EVProUpdater==='object'?EVProUpdater.panel(): '')}
