function updatePanelV36(){return panel('Versión y actualizaciones · '+E(globalThis.EVPRO_CURRENT_RELEASE||'3.7.0-prueba'),
 '<p><b>Versión instalada:</b> '+E(globalThis.EVPRO_CURRENT_RELEASE||'3.7.0-prueba')+' · Corrección de cortes, resumen integral de empresa y solicitud de proveedor.</p>'+
 '<p class="notice">Para actualizar, primero exporta un respaldo privado. Luego utiliza «Actualización del programa» al final de esta pantalla, selecciona el ZIP oficial y confirma. En modo autónomo, Chrome/Edge puede solicitar permiso de escritura sobre la carpeta de EV Pro. La actualización del código web no modifica los expedientes ni la base SQLite. Para componentes de servidor (PDF y Excel), sigue las instrucciones del instalador Windows correspondiente.</p>'+
 B('Verificar escenarios de red en cero','verifyCutReportsV36()','secondary')+
 '<p class="muted">La comprobación es de solo lectura sobre los expedientes accesibles en este espacio. El motor de cálculo no se modifica.</p>');}
function verifyCutReportsV36(){
 const pairs=state.projects.flatMap(p=>(p.sites||[]).map(s=>({p,s})));
 if(!pairs.length){toast('No hay instalaciones guardadas para comprobar.');return;}
 let checked=0,issues=[];
 for(const {p,s} of pairs){const c={...reportConfig(p),cutSource:'manual',outStart:0,outHours:24};
  for(const id of ['sunOff','cloudOff','darkOff']){
   const r=reportScenario(s,c,id).r;checked++;
   if(r.gridTotal>1e-8||r.rows.some(a=>a.available||a.grid>1e-8||a.gridRecharge>1e-8))issues.push(p.name+' / '+s.name+' / '+id);
  }
 }
 let result=issues.length?'ERROR: '+issues.length+' escenarios permiten energía de red.':'CORRECTO: red 0 kWh en los '+checked+' escenarios de corte de 24 horas.';
 modal('Diagnóstico de corte completo',`<p class="${issues.length?'warn':'notice'}">${E(result)}</p><p>Instalaciones verificadas: ${pairs.length}. Esta comprobación NO altera proyectos, red, baterías ni archivos.</p>${issues.length?'<p>'+E(issues.join(' · '))+'</p>':''}`,()=>true,'Cerrar');
}
let logoutBusy=false;
async function logout(){
 if(!shared||!me||logoutBusy)return;
 logoutBusy=true;const surfaces=['nav','top','main','dialog'].map($).filter(Boolean);for(const e of surfaces)e.inert=true;
 try{
  // Let an existing write complete before starting the final save. Never discard an unsaved draft.
  let deadline=Date.now()+12000;while(syncing&&me&&Date.now()<deadline)await new Promise(r=>setTimeout(r,80));
  if(!me)return;if(syncing)throw Error('Hay una sincronización en curso. Intenta cerrar sesión cuando finalice.');
  if(!autoSaveEnabled&&dirty)throw Error('Hay cambios pendientes. Pulsa Guardar ahora antes de cerrar sesión.');
  await persist();if(!me)return;
  if(dirty||collision)throw Error('Hay cambios pendientes o un conflicto. Guarda o resuelve los cambios antes de cerrar sesión.');
  await api('/api/logout',{method:'POST',body:'{}'});
  if(db&&me)await writeDraft(null).catch(()=>{});
  await lockExpired();if($('loginError'))$('loginError').textContent='Sesión cerrada correctamente.';
 }catch(e){if(e.code===401){await lockExpired();}else toast(e.message||'No se pudo cerrar sesión. Comprueba la conexión.');}
 finally{logoutBusy=false;for(const e of surfaces)e.inert=false;const b=$('topLogout');if(b)b.disabled=false;}
}
async function discardConflict(){if(confirm('¿Descartar TODOS los cambios no sincronizados? Descarga antes un respaldo.')){let r=await api('/api/state');receiveIdentity(r.identity);base=Object.fromEntries(r.records.map(x=>[x.kind+':'+x.id,x]));state=serverState(r.records);collision=false;dirty=false;if(db)await putStore('v35draft:'+me.username,null);status('Sincronizado');nav('home')}}
const slug=t=>String(t||'proyecto').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,90)||'proyecto';
function assetBytes(data){if(typeof data!=='string'||!/^data:[^,]*;base64,/.test(data))throw Error('Archivo inválido');let a=atob(data.split(',')[1]);return Uint8Array.from(a,c=>c.charCodeAt(0))}
function downloadAsset(k,i){let a=site()[k][i];download(a.name,assetBytes(a.data))}
