const help=k=>aids[k]?`<small class="field-help">${E(aids[k])}</small>`:'';
function mfield(label,k,v='',type='text',req=false){return `<label class="field">${E(label)}<input name="${k}" type="${type}" ${type==='number'?'step="any"':''} value="${E(v)}" ${req?'required':''} placeholder="${E(k==='name'&&label!=='Razón social'?'':examples[k]||'')}">${label==='Razón social'?'<small class="field-help">Nombre oficial con el que está registrada legalmente la empresa.</small>':help(k)}</label>`}
function field(label,k,v,on='setSite',type='text',extra=''){return `<label class="field">${E(label)}<input type="${type}" value="${E(v)}" ${extra} oninput="${on}('${k}',this.value${type==='number'?',true':''})">${help(k)}</label>`}
function textField(label,k,v,on='setSite'){return `<label class="field">${E(label)}<textarea oninput="${on}('${k}',this.value)">${E(v)}</textarea>${help(k)}</label>`}
function select(label,k,v,opts,on='setSite'){return `<label class="field">${E(label)}<select onchange="${on}('${k}',this.value)">${[...new Set([v,...opts])].filter(x=>x!==undefined&&x!==null).map(a=>`<option ${a===v?'selected':''}>${E(a)}</option>`).join('')}</select>${help(k)}</label>`}
function modalSelect(label,k,v,opts){return `<label class="field">${E(label)}<select name="${k}">${[...new Set([v,...opts])].filter(x=>x!==undefined&&x!==null).map(a=>`<option ${a===v?'selected':''}>${E(a)}</option>`).join('')}</select>${help(k)}</label>`}
function typeSelect(v='Solar híbrido'){return `<label class="field">Tipo de proyecto<select name="type" onchange="$('typeHelp').textContent=types[this.value]||'Solución personalizada.'">${[...new Set([v,...Object.keys(types)])].map(t=>`<option ${t===v?'selected':''}>${E(t)}</option>`).join('')}</select><small id="typeHelp" class="field-help">${E(types[v]||'Solución personalizada.')}</small></label>`}
