function comboField({id,name,label,value='',display='',placeholder,items='',helpText=''}){return `<div class="field combo-field"><span>${E(label)}</span><details class="combo" id="combo_${id}"><summary><span id="display_${id}">${E(display||value||'Seleccionar…')}</span><span class="combo-arrow" aria-hidden="true">⌄</span></summary><div class="combo-panel"><input type="search" id="${id}Search" placeholder="${E(placeholder)}" aria-label="${E(placeholder)}" autocomplete="off" oninput="${id==='company'?'pickerResults(this.value)':id==='catalog'?'catalogResults(this.value)':'territoryResults(\''+id+'\',this.value)'}"><div class="picker-results" id="${id==='company'?'pickerResults':id+'Results'}">${items}</div></div></details><input type="hidden" id="${id==='company'?'pickCompany':'value_'+id}" name="${name}" value="${E(value)}"><small class="field-help">${E(helpText)}</small></div>`}
function companyPicker(co=''){return comboField({id:'company',name:'companyId',label:'Empresa',value:co,display:company(co)?.name||'Seleccionar empresa',placeholder:'Buscar por nombre, NIT o ubicación',helpText:'Abre el selector para ver las empresas registradas o escribe para buscar.'}).replace('id="display_company"','id="pickedCompany"')}
function pickerResults(q=''){let el=$('pickerResults');if(!el)return;let matches=state.companies.filter(c=>!c.archived&&normSearch([c.name,c.commercial,c.tax,c.province,c.municipality].join(' ')).includes(normSearch(q))).sort((a,b)=>a.name.localeCompare(b.name,'es'));el.innerHTML=matches.map(c=>`<button type="button" class="secondary picker-item" onclick="chooseCompany(${arg(c.id)})">${E(c.name)} <small>${E([c.municipality,c.province].filter(Boolean).join(' · '))}</small></button>`).join('')||empty('Sin coincidencias')}
function chooseCompany(id){$('pickCompany').value=id;$('pickedCompany').textContent=company(id).name;$('combo_company').open=false;$('companySearch').value='';pickerResults();if($('calcProject'))updateCalcProjects()}
function territoryField(id,c){let val=c[id]||'';return comboField({id,name:id,label:id==='province'?'Provincia / municipio especial':'Municipio',value:val,display:val||(id==='province'?'Seleccionar provincia':'Seleccionar municipio'),placeholder:id==='province'?'Buscar provincia…':'Buscar municipio…',helpText:aids[id],items:territoryItems(id,c.province,val,'')})}
function territoryItems(id,province,current,q){let items=id==='province'?Object.keys(CUBA_TERRITORIES):(CUBA_TERRITORIES[province]||[]);if(current&&!items.includes(current))items=[current,...items];return items.filter(v=>normSearch(v).includes(normSearch(q))).sort((a,b)=>a.localeCompare(b,'es')).map(v=>`<button type="button" class="secondary picker-item" onclick="chooseTerritory('${id}',${arg(v)})">${E(v)}${v==='Isla de la Juventud'&&id==='province'?' <small>Municipio especial</small>':''}</button>`).join('')||`<div class="combo-empty">${id==='municipality'&&!province?'Selecciona primero la provincia.':'Sin coincidencias'}</div>`}
function territoryResults(id,q=''){let el=$(id+'Results');if(el)el.innerHTML=territoryItems(id,$('value_province')?.value||'',$('value_'+id)?.value||'',q)}
function chooseTerritory(id,v){let old=$('value_'+id).value;$('value_'+id).value=v;$('display_'+id).textContent=v;$('combo_'+id).open=false;$(id+'Search').value='';if(id==='province'&&old!==v){let auto=v==='Isla de la Juventud'?v:'';$('value_municipality').value=auto;$('display_municipality').textContent=auto||'Seleccionar municipio';$('municipalitySearch').value='';territoryResults('municipality')}territoryResults(id)}
document.addEventListener('toggle',e=>{if(e.target.matches?.('details.combo')&&e.target.open){let id=e.target.id.slice(6);document.querySelectorAll('details.combo[open]').forEach(x=>{if(x!==e.target)x.open=false});if(id==='company')pickerResults($('companySearch').value);else if(id==='catalog')catalogResults($('catalogSearch').value);else territoryResults(id,$(id+'Search').value);e.target.querySelector('input[type=search]')?.focus()}},true);
function addBranch(){let el=document.createElement('div');el.className='row branch';el.innerHTML='<input name="branch" placeholder="Nombre de otra instalación"><button type="button" class="danger small" onclick="this.parentNode.remove()">Quitar</button>';$('branches').append(el)}
function projectDialog(co){let cs=state.companies.filter(c=>!c.archived);if(!cs.length){toast('Para crear un proyecto primero registra su empresa.');companyDialog(undefined,true);return}modal('Nuevo proyecto empresarial',`<p class="notice">Selecciona la empresa y define la solución. El título se genera automáticamente; podrás personalizarlo más adelante.</p>${companyPicker(co||'')}${templatePicker('projectTemplate',prefs().template,'selectProjectTemplate(this.value)')}<div class="fields">${typeSelect()}${mfield('Instalación principal','site','Instalación principal','text',true)}</div><label class="field">Objetivo<textarea name="objective" placeholder="Ej. Mantener la producción durante apagones"></textarea><small class="field-help">Necesidad que debe resolver la solución.</small></label><h3>Instalaciones adicionales</h3><p class="muted">Agrega una instalación adicional solo si hay otro local, edificio o sucursal que necesita su propia solución energética. Cada lugar tendrá su simulación, fotografías e inventario independientes.</p><div id="branches"></div>${B('+ Agregar instalación','addBranch()')}<h3>Soluciones que incluirá el proyecto</h3><p class="muted">Selecciona los trabajos y tecnologías previstos. Podrás cambiar el alcance después.</p>${MOD.map(([m,d],i)=>`<label class="check"><input type="checkbox" name="module" value="${E(m)}" ${i<3?'checked':''}><span><b>${E(m)}</b><br><small>${E(moduleDetails[m]||d)}</small></span></label>`).join('')}`,f=>{let o=Object.fromEntries(f);if(!company(o.companyId)||!o.site.trim()){toast('Selecciona una empresa y una instalación.');return false}let p=newProject(o.companyId,company(o.companyId).name+' — '+o.type,o.objective,o.type,f.getAll('module'),[o.site.trim(),...f.getAll('branch').map(a=>a.trim()).filter(Boolean)]);let t=allTemplates().find(t=>t.id===f.get('projectTemplate'));for(let a of p.sites){applyDefaultCriteria(a);if(t)applyTemplateCriteria(a,t,false)}state.projects.push(p);touch();openProject(p.id)});if(!co)pickerResults();if(prefs().template)selectProjectTemplate(prefs().template)}
const moduleDetails={'Fotovoltaica':'Paneles solares que producen electricidad. Incluye cadenas y control de generación.','Baterías':'Almacena energía para usarla cuando sea necesaria.','ATS y respaldo':'Transferencia automática y segura entre fuentes de suministro.','Generador':'Grupo electrógeno como fuente alternativa.','Carga EV':'Cargadores y protecciones para vehículos eléctricos.','Obra civil':'Bases, estructuras, soportes y adecuaciones constructivas.','Monitorización':'Medición y supervisión de consumos, producción y alarmas.','Climatización':'Control térmico y ventilación de equipos.','Modernización eléctrica':'Tableros, conductores, distribución y protecciones.'};
function simValue(s,k){if(k in pvDefaults)return s[k]??pvDefaults[k];if(k==='pvMode')return s.pvMode||'legacy';if(k==='pvCoupled')return s.pvCoupled??0;if(['pvHourly','pvHourlyTemp'].includes(k))return s[k]||[];if(k==='restDay')return s.restDay??s.rest??0;if(k==='simHours')return durationHours(s);return ['bcharge','bdischarge'].includes(k)?s[k]??s.bpower??0:s[k]}
function recommendations(s){let m=energy({...s,simHours:168}),target=m.peak;if(s.designLoad==='Potencia personalizada')target=+s.customLoad||0;else if(['Solo P1 críticas','P1 y P2 esenciales'].includes(s.designLoad)){let allowed=s.designLoad==='Solo P1 críticas'?['P1']:['P1','P2'];target=Math.max(0,...Array.from({length:24},(_,h)=>(s.loads||[]).filter(r=>allowed.includes(String(r.priority).slice(0,2))&&active(h,+r.start||0,+r.hours||0)).reduce((a,r)=>a+(+r.kw||0)*(+r.qty||0)*(+r.sim||0)/100,0)))}let u=Math.max(1,s.unitInverter),b=Math.max(1,s.unitBattery),den=s.dod/100*s.eff/100*((s.batterySOH??100)/100);return {inv:Math.ceil(target*(1+designMargin(s)/100)/u)*u,bat:den>0?Math.ceil(target*s.autonomy/den/b)*b:0,m,target,valid:den>0&&target>0}}
function applySizing(){let s=site(),a=recommendations(s);if(!a.valid)return toast('Define una carga objetivo positiva y profundidad de descarga válida.');modal('Aplicar recomendaciones de ingeniería',`<p>Actualiza la simulación, las sugerencias, el resumen y la documentación vinculada. Las cantidades fijadas manualmente se conservan.</p><table><tr><th>Equipo</th><th>Actual</th><th>Propuesto</th></tr><tr><td>Inversores</td><td>${fmt(s.inverter)} kW</td><td>${fmt(a.inv)} kW</td></tr><tr><td>Baterías</td><td>${fmt(s.battery)} kWh</td><td>${s.modules.includes('Baterías')?fmt(a.bat)+' kWh':'No incluido'}</td></tr></table><p class="warn">Verifica potencia de descarga, compatibilidad y fichas técnicas. Es un cálculo preliminar.</p>`,()=>{s.inverter=a.inv;s.inverterCount=s.unitInverter>0?Math.ceil(a.inv/s.unitInverter):null;if(s.modules.includes('Baterías'))s.battery=a.bat;touch();render()},'Aplicar cambios')}
function toggleModule(m,v){let s=site();if(!v){modal('Retirar módulo del alcance',`<p>${E(m)} dejará de incluirse en los cálculos y sugerencias que dependen de ese módulo. Los datos introducidos se conservan para una futura reactivación.</p>`,()=>{s.modules=s.modules.filter(x=>x!==m);touch();render()});render();return}s.modules=[...new Set([...s.modules,m])];touch();render()}
function keyMetrics(s){let m=energy(s);return metric(s.modules.includes('Fotovoltaica')?s.panels:0,'Paneles solares','☀')+metric(fmt(m.pv)+' kWp','Potencia fotovoltaica','ϟ')+metric(fmt(m.inv)+' kW','Inversores','◇')+metric(fmt(m.nominalBattery)+' kWh','Baterías nominales','▰')+metric(fmt(m.peak)+' kW','Demanda máxima del período','≋')+metric(fmt(m.loadTotal)+' kWh','Demanda · '+m.rows.length+' h','∑')+metric(fmt(m.pvTotal)+' kWh','FV disponible · '+m.rows.length+' h','☀')+metric(fmt(m.usable)+' kWh','Energía útil teórica de batería','▰')}
function assignCalc(){if(!state.projects.length)return toast('Primero crea una empresa y un proyecto.');modal('Guardar cálculo en un expediente',`${companyPicker()}<label class="field">Proyecto<select id="calcProject" name="project" onchange="updateCalcSites()"></select></label><label class="field">Instalación<select id="calcInstall" name="install"></select></label>${mfield('Nombre del cálculo','label','Cálculo independiente','text',true)}<p class="notice">El proyecto ya tiene parámetros de simulación. Puedes guardar el nuevo cálculo como escenario o aplicarlo y conservar el anterior como copia.</p><label class="check"><input type="radio" name="mode" value="keep" checked> Mantener ambos cálculos (no modifica el activo)</label><label class="check"><input type="radio" name="mode" value="replace"> Sustituir el activo y respaldar el anterior (si está vinculado, también actualizará los parámetros compartidos)</label>`,f=>{let p=state.projects.find(x=>x.id===f.get('project')&&x.companyId===f.get('companyId')),s=p?.sites.find(x=>x.id===f.get('install'));if(!s){toast('Selecciona empresa, proyecto e instalación.');return false}let snap=x=>Object.fromEntries([...Object.keys(configs),'pvMode','pvCoupled','pvHourly','pvHourlyTemp','simStart','simHours','startWeekday','workDays','evOnRest','restMode','inventoryWork','inventoryRest','outages','loads','useLoads','modules','genEnabled','genMode','genTarget','genIntervals','genMaxHours','genSocStart','genSocStop','genChargeLimit','genOnlyOutage','designMargin','autonomy','unitInverter','unitBattery',...V35_ENERGY_KEYS].map(k=>[k,copy(k==='restDay'?x.restDay??null:simValue(x,k)??null)]));s.scenarios=s.scenarios||[];let data=snap(calcSite);if(f.get('mode')==='replace'){let before=installationSnapshot(p,s);s.scenarios.push({name:'Respaldo anterior a '+f.get('label'),date:now(),data:snap(s)});Object.assign(s,data);propagateInstallationChanges(p,s,before)}else s.scenarios.push({name:f.get('label'),date:now(),data});p.updated=now();touch();toast('Cálculo guardado en el expediente');openProject(p.id,'simulation');sid=s.id;render()});pickerResults()}
function updateCalcProjects(){let ps=state.projects.filter(p=>p.companyId===$('pickCompany').value);$('calcProject').innerHTML=ps.map(p=>`<option value="${E(p.id)}">${E(p.name)}</option>`).join('');updateCalcSites()}
function updateCalcSites(){let p=state.projects.find(p=>p.id===$('calcProject').value);$('calcInstall').innerHTML=(p?.sites||[]).map(s=>`<option value="${E(s.id)}">${E(s.name)}</option>`).join('')}
let pendingImages=[];
function imageDialog(proposal){pendingImages=[];modal('Añadir imágenes',`<p class="muted">Selecciona una o varias fotografías. Añade una descripción y zona a cada una antes de guardar.</p><input id="imageFiles" type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,image/avif" onchange="stageImages(this.files)"><div id="imageStage"></div>`,()=>{if(!pendingImages.length||pendingImages.some(a=>!a.data)){toast('Selecciona imágenes y espera a que aparezcan las vistas previas.');return false}let s=site();s.images.push(...pendingImages.map(a=>({...a,type:proposal?'Propuesta':'Original',publish:false,designSnapshot:proposal?visualSignature(s):null})));pendingImages=[];touch();render()});$('dialog').dataset.proposal=String(proposal)}
async function stageImages(files){let target=$('imageStage');for(let f of files){if(f.size>15*1024*1024||!/^image\/(png|jpeg|webp|gif|avif)$/.test(f.type)){toast('Imagen no admitida o mayor de 15 MB');continue}let a={assetId:uid(),name:f.name,data:null,zone:'General',caption:'',work:'',originalId:''};pendingImages.push(a);try{a.data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}catch{pendingImages=pendingImages.filter(x=>x!==a);toast('No se pudo leer '+f.name)}}if(!$('dialog').open||!target.isConnected)return;let proposal=$('dialog').dataset.proposal==='true';let originals=site().images.filter(a=>['Original','Inspección'].includes(a.type));originals.forEach(a=>{if(!a.assetId)a.assetId=uid()});target.innerHTML=pendingImages.map((a,i)=>`<div class="stage-card"><img class="asset" data-ev-stage-image="${i}" decoding="async"><b>${E(a.name)}</b><label class="field">Zona<input value="${E(a.zone)}" oninput="pendingImages[${i}].zone=this.value"></label><label class="field">Descripción<textarea oninput="pendingImages[${i}].caption=this.value">${E(a.caption)}</textarea></label><label class="field">Trabajo previsto<textarea oninput="pendingImages[${i}].work=this.value">${E(a.work)}</textarea></label>${proposal?`<label class="field">Fotografía original<select onchange="pendingImages[${i}].originalId=this.value"><option value="">Comparar por zona</option>${originals.map(o=>`<option value="${E(o.assetId)}" ${o.assetId===a.originalId?'selected':''}>${E(o.zone+' · '+o.name)}</option>`).join('')}</select></label>`:''}</div>`).join('');for(const img of target.querySelectorAll('img[data-ev-stage-image]')){const i=Number(img.dataset.evStageImage);if(Number.isSafeInteger(i)&&pendingImages[i]?.data)img.src=safeImage(pendingImages[i].data)}}

function siteComparison(sites){return `<div class="scroll"><table><tr><th>Instalación</th><th>FV kWp</th><th>Inversor kW</th><th>Baterías kWh</th><th>Período h</th><th>Consumo kWh</th><th>Déficit kWh</th></tr>${sites.map(s=>{let m=energy(s);return `<tr><td>${E(s.name)}</td>${[m.pv,m.inv,m.bat,m.rows.length,m.loadTotal,m.unmet].map(n=>`<td>${fmt(n)}</td>`).join('')}</tr>`}).join('')}<tr><th>Capacidades totales</th>${['pv','inv','bat'].map(k=>`<th>${fmt(sites.reduce((a,s)=>a+energy(s)[k],0))}</th>`).join('')}<td colspan="3">Energías por instalación</td></tr></table></div><small>Las instalaciones son independientes. Compara energías únicamente entre períodos iguales; no se deduce un pico simultáneo total.</small>`}
function alternativeComparison(ps){return `<div class="scroll"><table><tr><th>Proyecto / alternativa</th><th>FV kWp</th><th>Inversores kW</th><th>BESS kWh</th><th>Períodos h</th><th>Déficit kWh</th><th>Paneles</th><th>Cobertura %</th><th>Red kWh</th><th>SOC final kWh</th></tr>${ps.map(p=>{let rr=p.sites.map(energy);return `<tr><td>${E(p.name)} · ${E(p.version)}</td>${['pv','inv','bat'].map(k=>`<td>${fmt(rr.reduce((n,r)=>n+r[k],0))}</td>`).join('')}<td>${rr.map(r=>r.rows.length).join(' / ')}</td><td>${rr.map(r=>fmt(r.unmet)).join(' / ')}</td><td>${p.sites.reduce((n,s)=>n+(s.modules.includes('Fotovoltaica')?Number(s.panels)||0:0),0)}</td><td>${rr.map(r=>r.loadTotal?fmt(100*(1-r.unmet/r.loadTotal),1):'—').join(' / ')}</td><td>${rr.map(r=>fmt(r.gridTotal)).join(' / ')}</td><td>${rr.map(r=>fmt(r.rows.at(-1)?.soc||0)).join(' / ')}</td></tr>`}).join('')}</table></div><p class="muted">Déficits por instalación. Comparar alternativas con períodos, perfiles de consumo, condiciones solares y cortes equivalentes.</p>`}
function setCalcModule(m,v){calcSite.modules=v?[...new Set([...calcSite.modules,m])]:calcSite.modules.filter(x=>x!==m);render()}
function equipmentFields(m){return `${modalSelect('Tipo de especificación','equipmentType',m.equipmentType||'General',['General','Protección eléctrica','Módulo fotovoltaico','Inversor / PCS','Batería / BESS','Conductor / accesorio'])}<div id="equipFields" class="fields">${equipDetails(m.equipmentType||'General',m)}</div><small class="field-help">Selecciona el tipo; registra características solo cuando estén disponibles en la ficha técnica.</small>`}
const equipmentSpecs={'Protección eléctrica':[['Corriente nominal (A)','amps'],['Número de polos','poles',['Por confirmar','1','2','3','4']],['Tipo de corriente','currentType',['Por confirmar','AC','DC','AC/DC']],['Poder de corte (kA)','breaking'],['Tensión asignada V (aplicable a la configuración de polos)','ratedVoltageV'],['Corriente convencional I2 (A)','i2A']], 'Módulo fotovoltaico':[['Potencia (W)','moduleWatts'],['Voc (V)','voc'],['Isc (A)','isc'],['Vmp (V)','vmp'],['Imp (A)','imp'],['Coeficiente Voc %/°C','vocCoeff'],['Coeficiente Vmp %/°C','vmpCoeff'],['Coeficiente potencia %/°C','powerCoeff'],['NOCT °C','noct'],['Longitud (m)','lengthM'],['Anchura (m)','widthM']], 'Inversor / PCS':[['Potencia AC nominal kW','ratedACkw'],['MPPT independientes','mpptCount'],['Máxima tensión DC (V)','maxDc'],['Entrada FV máxima kW/unidad','maxInputDCkw'],['MPPT tensión mínima V','mpptMinV'],['MPPT tensión máxima V','mpptMaxV'],['MPPT corriente de trabajo A','mpptOperatingA'],['MPPT Isc máxima A','mpptShortCircuitA'],['Fases','acPhases',['Por confirmar','1','2','3']],['Compatibilidad BMS/optimizador','protocol']], 'Batería / BESS':[['Capacidad nominal (kWh)','ratedKwh'],['Carga máxima (kW)','maxCharge'],['Descarga máxima (kW)','maxDischarge'],['Tensión mínima de módulo/banco V','minBatteryV'],['Tensión máxima de módulo/banco V','maxBatteryV'],['Comunicación BMS','protocol']], 'Conductor / accesorio':[['Sección (mm²)','section'],['Tipo de aislamiento','insulation'],['Material conductor','conductorMaterial',['Por confirmar','Cobre','Aluminio']],['Ampacidad de referencia (A), indicar método en ficha','referenceAmpacity'],['Reactancia por conductor (Ω/km)','reactanceOhmKm']]};
function equipDetails(t,m={}){return (equipmentSpecs[t]||[]).map(([l,k,o])=>o?modalSelect(l,k,m[k]||o[0],o):mfield(l,k,m[k]||'')).join('')}
document.addEventListener('change',e=>{if(e.target.name==='equipmentType'&&$('equipFields')){let current=Object.fromEntries(new FormData($('modalForm')));$('equipFields').innerHTML=equipDetails(e.target.value,current)}});
window.addEventListener('beforeunload',e=>{if(pendingSave()){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&dirty&&autoSaveEnabled)persist()});
/* V3.3 — informes ejecutivos independientes, sin mutar la simulación de origen. */
const REPORT_SECTIONS=[['cover','Portada e índice'],['summary','Resumen ejecutivo'],['parameters','Parámetros originales del simulador'],['compare','Comparación de siete escenarios'],['flow','Gráficas de flujo energético'],['soc','Gráficas de SOC y reserva'],['phases','Cuatro fases del día'],['hourly','Balance horario del período'],['visual','Fotografías y propuestas visuales'],['docs','Documentación técnica'],['schedule','Plan de ejecución y cronograma'],['limits','Conclusiones y validaciones']];
const REPORT_SCENARIOS=[['active','Escenario configurado'],['sunGrid','Soleado · con red'],['cloudGrid','Nublado · con red'],['darkGrid','Sin sol · con red'],['sunOff','Soleado · con corte de red'],['cloudOff','Nublado · con corte de red'],['darkOff','Sin sol · con corte de red']];
const REPORT_DEFAULT={mode:'executive',orientation:'portrait',sun:null,cloud:40,cutSource:'site',outStart:0,outHours:24,sections:REPORT_SECTIONS.map(x=>x[0]),images:{},scenarios:REPORT_SCENARIOS.map(x=>x[0])};
const reportConfig=p=>({...copy(REPORT_DEFAULT),...(p.reportConfig||{})});
const reportImageKey=(s,a)=>s.id+':'+a.assetId;
function reportAssets(s,c){return (s.images||[]).filter(a=>safeImage(a.data)&&(c.images?.[reportImageKey(s,a)]??!!a.publish));}
// V3.6 prueba: por defecto los ensayos 'con corte' heredan el apagón del expediente.
// Si un expediente no declara corte, la prueba comparativa usa 24 horas sin red.
// El usuario puede elegir duración de prueba independiente sin alterar su instalación.
function reportCut(s,c){
 const siteMode=c.cutSource!=='manual';
 const declared=Number(s.outHours),valid=Number.isFinite(declared)&&declared>0;
 const hours=siteMode?(valid?declared:24):Number(c.outHours);
 const start=siteMode?(valid?Number(s.outStart):0):Number(c.outStart);
 const clamp=(v,a,b,fallback)=>Number.isFinite(v)?Math.max(a,Math.min(b,Math.round(v))):fallback;
 return {outStart:clamp(start,0,23,0),outHours:clamp(hours,1,24,24)};
}
function reportScenario(s,c,id){let x={...s};if(id!=='active'){let solar=id.startsWith('cloud')?(c.sun??s.sun)*c.cloud/100:id.startsWith('dark')?0:(c.sun??s.sun);let original=pvModel(s);if(original.mode==='hourly'&&original.hsp>0){let base=c.sun??original.hsp;solar=id.startsWith('cloud')?base*c.cloud/100:id.startsWith('dark')?0:base;x.pvScenarioFactor=solar/original.hsp}let cut=reportCut(s,c);Object.assign(x,{sun:solar,outStart:cut.outStart,outHours:id.endsWith('Off')?cut.outHours:0,outages:[]});}let r=energy(x);return {id,label:REPORT_SCENARIOS.find(a=>a[0]===id)[1],x,r};}
function reportTotals(r){let sum=k=>r.rows.reduce((a,b)=>a+(b[k]||0),0);let initial=r.rows[0].socStart, final=r.rows.at(-1).soc;let served=r.loadTotal-r.unmet;return {served,coverage:r.loadTotal?served/r.loadTotal*100:null,initial,final,min:Math.min(initial,...r.rows.map(a=>a.soc)),charge:sum('ch'),dis:sum('dis'),loss:sum('loss'),solarDirect:sum('pvDirect'),solarCharge:sum('pvCharge'),gridCharge:sum('gridRecharge'),gridLoad:r.gridTotal-sum('gridRecharge'),genCharge:sum('genRecharge'),genLoad:sum('genDirect'),genHours:r.rows.filter(a=>a.genRunning).length,outage:r.rows.filter(a=>!a.available).length,deficitHours:r.rows.filter(a=>a.need>1e-7).length,first:r.rows.find(a=>a.need>1e-7)?.h,closure:r.pvTotal+r.gridTotal+r.genTotal+initial-served-final-r.spill-sum('loss')};}
const rn=(v,d=1)=>Number.isFinite(v)?fmt(v,d):'—',rh=h=>String(h).padStart(2,'0')+':00';
function rtable(headers,rows,cl=''){return `<table class="r-table ${cl}"><thead><tr>${headers.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>'<tr>'+a.map(v=>`<td>${E(v)}</td>`).join('')+'</tr>').join('')}</tbody></table>`}
const rm=(v,label)=>`<div class="r-metric"><small>${E(label)}</small><strong>${E(v)}</strong></div>`;
const rmetrics=arr=>`<div class="r-metrics">${arr.map(a=>rm(a[0],a[1])).join('')}</div>`;
const rtitle=(n,t,sub='')=>`<div class="r-heading"><span>${E(n)}</span><div><h2>${E(t)}</h2>${sub?'<p>'+E(sub)+'</p>':''}</div></div>`;
const rsection=(n,t,body,sub='',cls='')=>`<section class="r-section ${cls}">${rtitle(n,t,sub)}${body}</section>`;
function reportConclusion(q){let {r,x}=q,t=reportTotals(r);if(r.groupStatus==='invalid')return 'Despacho por grupos no calculado: '+r.groupErrors.join('; ')+'. Las cifras agregadas no acreditan cobertura por tablero.';let prefix=r.groupStatus==='groups'?'Balance por tableros validados en el modelo (no aprobación OEM). ':'';if(!r.loadTotal)return 'No se ha registrado demanda; no puede evaluarse la cobertura.';return `${prefix}Período ${simPeriod(r)}. La demanda atendida es ${rn(t.served)} de ${rn(r.loadTotal)} kWh (${rn(t.coverage)} %). ${r.unmet>1e-7?`Quedan ${rn(r.unmet)} kWh sin atender en ${t.deficitHours} intervalo(s) horario(s); el primero comienza a las ${timeAt(r,r.rows.findIndex(a=>a.need>1e-7))}. Revisar capacidades, prioridades o fuentes de respaldo.`:'No se observa energía no atendida en las condiciones simuladas. Esto no garantiza la continuidad real.'} ${r.bat>0?`La batería termina en ${rn(t.final/r.bat*100)} % de SOC y alcanza un mínimo de ${rn(t.min/r.bat*100)} %.`:'No se ha configurado almacenamiento activo.'} ${r.spill>1e-7?`Se desaprovechan ${rn(r.spill)} kWh solares AC disponibles.`:''}`;}
function reportChart(q,mode){let {r,x}=q,t=reportTotals(r),soc=mode==='soc',W=760,H=226,L=53,R=17,T=19,B=42,C=W-L-R,D=H-T-B,series=soc?[['SOC','#087b69', [r.bat?t.initial/r.bat*100:0,...r.rows.map(a=>r.bat?a.soc/r.bat*100:0)]],['Reserva','#aa7b25',Array(r.rows.length+1).fill(r.bat?100-x.dod:0)]]:[['Demanda','#163e53',r.rows.map(a=>a.load)],['Solar FV','#d79a1c',r.rows.map(a=>a.pv)],['Red · total','#4678b8',r.rows.map(a=>a.grid)],['Batería · descarga','#0a8b73',r.rows.map(a=>a.dis)],['Déficit','#b94c46',r.rows.map(a=>a.need)],...(x.genEnabled&&x.modules.includes('Generador')?[['Generador','#7758a0',r.rows.map(a=>a.gen)]]:[])];let max=soc?100:Math.max(1,...series.flatMap(a=>a[2]));if(!soc)max=Math.ceil(max/5)*5;let xx=i=>L+i*C/r.rows.length,yy=v=>T+D-v/max*D;let grid=Array.from({length:5},(_,i)=>{let v=max*i/4;return `<line x1="${L}" y1="${yy(v)}" x2="${W-R}" y2="${yy(v)}" stroke="#d8e5e6"/><text x="${L-8}" y="${yy(v)+4}" text-anchor="end">${E(rn(v,0))}</text>`}).join('');let hours=tickIndices(r.rows.length).map(h=>`<text x="${xx(h)}" y="${H-12}" text-anchor="middle">${timeAt(r,h)}</text>`).join('');let shade=r.rows.filter(a=>!a.available).map(a=>`<rect x="${xx(a.i)}" y="${T}" width="${C/r.rows.length}" height="${D}" fill="#f7e8dc"/>`).join('');let lines=series.map(([name,col,v],j)=>{let pts=v.map((n,i)=>`${xx(i+(soc?0:.5))},${yy(n)}`).join(' ');return `<polyline points="${pts}" fill="none" stroke="${col}" stroke-width="${j===0?3:2.2}" stroke-linejoin="round" ${soc&&j===1?'stroke-dasharray="6 4"':''}/>`}).join('');return `<div class="r-chart"><h3>${soc?'Estado de carga de las baterías (SOC)':'Flujo energético durante '+r.rows.length+' horas'}</h3><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${soc?'Estado de carga':'Flujo energético'}" viewBox="0 0 ${W} ${H}"><g font-size="11" font-family="Arial,sans-serif" fill="#48636b">${shade}${grid}<text x="7" y="13">${soc?'%':'kW'}</text>${hours}${lines}</g></svg><div class="r-legend">${series.map(([name,col])=>`<span><i style="background:${col}"></i>${E(name)}</span>`).join('')}<span><i style="background:#f7e8dc"></i>Red interrumpida</span></div>${!soc?'<small>Red total incluye recarga; las líneas no son fuentes apiladas. Potencia media por intervalo horario. +1d = día siguiente; +2d = dos días después, etc.</small>':r.bat?'':'<small>Sin almacenamiento activo: no aplica el SOC.</small>'}</div>`}
function reportPhases(q){let {r}=q,groups=[];for(let a of r.rows){let k=a.day+':'+Math.floor(a.h/6),g=groups.at(-1);if(!g||g.k!==k){g={k,rows:[],name:['Madrugada','Mañana','Tarde','Noche'][Math.floor(a.h/6)]};groups.push(g)}g.rows.push(a)}let sum=(rr,k)=>rr.reduce((n,a)=>n+(a[k]||0),0);return rtable(['Período','Demanda','FV','Red total','Gen.','Descarga','Recarga','Déficit','SOC final %'],groups.map(g=>{let rr=g.rows;return [`${g.name} ${timeAt(r,rr[0].i)}–${timeAt(r,rr.at(-1).i+1)} · ${weekDayLabel(rr[0])}`,...['load','pv','grid','gen','dis','ch','need'].map(k=>rn(sum(rr,k))),r.bat?rn(rr.at(-1).soc/r.bat*100):'—']}),'r-small')+'<p class="r-caption">Fases civiles en orden de simulación. Si el inicio divide una fase, aparece en dos tramos; no se duplican horas. Energías en kWh; +1d = día siguiente; +2d = dos días después, etc.</p>'+`<div class="r-phase-notes">${groups.map(g=>{let rr=g.rows,f=rr.filter(a=>!a.available).length;return `<p><b>${g.name} (${timeAt(r,rr[0].i)}):</b> ${f?f+' h de corte de red. ':''}FV ${rn(sum(rr,'pv'))} kWh. Descarga ${rn(sum(rr,'dis'))} kWh. Recarga ${rn(sum(rr,'ch'))} kWh. ${sum(rr,'need')>1e-7?'Déficit '+rn(sum(rr,'need'))+' kWh.':'Sin déficit calculado.'}</p>`}).join('')}</div>`}
function reportCivilTable(r){return rtable(['Día / actividad','Horas','Demanda','FV','Red','Gen.','Recarga','Déficit','SOC inicial %','SOC final %'],civilRows(r).map(a=>[weekDayLabel(a),String(a.hours),...['load','pv','grid','gen','ch','need'].map(k=>rn(a[k])),r.bat?rn(a.start/r.bat*100):'—',r.bat?rn(a.end/r.bat*100):'—']),'r-small')+'<p class="r-caption">Días civiles; primero y último pueden ser parciales. Energías en kWh. SOC continuo, sin reinicios a medianoche.</p>'}
function reportCycleTable(r){return rtable(['Ciclo','Período','Demanda','FV','Red','Gen.','Gen. recarga','Horas gen.','Recarga','Déficit','SOC inicial %','SOC final %'],cycleRows(r).map(a=>[a.n+' · '+a.hours+' h',a.from+' → '+a.to,...['load','pv','grid','gen','genRecharge','genHours','ch','need'].map(k=>rn(a[k])),r.bat?rn(a.start/r.bat*100):'—',r.bat?rn(a.end/r.bat*100):'—']),'r-small')+'<p class="r-caption">Energías en kWh. Los ciclos son consecutivos desde el inicio simulado; el último puede ser parcial.</p>'}
function reportHourly(q){let {r}=q,t=reportTotals(r),st=v=>r.bat?rn(v/r.bat*100)+' % / '+rn(v):'—';return rtable(['Hora inicio','Demanda','FV','Red','Gen.','Gen. recarga','Desc.','Carga','Déficit','SOC ini. % / kWh','SOC fin. % / kWh','Red disp.'],r.rows.map(a=>[timeAt(r,a.i)+' · '+weekDayLabel(a),...['load','pv','grid','gen','genRecharge','dis','ch','need'].map(k=>rn(a[k])),st(a.socStart),st(a.soc),a.available?'Sí':'No']).concat([['TOTAL',rn(r.loadTotal),rn(r.pvTotal),rn(r.gridTotal),rn(r.genTotal),rn(t.genCharge),rn(t.dis),rn(t.charge),rn(r.unmet),st(t.initial),st(t.final),'—']]),'r-hourly')+`<p class="r-caption">${simPeriod(r)}. Cada fila corresponde a una hora desde la hora indicada. +1d = día siguiente; +2d = dos días después, etc. Potencia media kW (numéricamente igual a kWh por intervalo). Red y generador incluyen sus recargas respectivas. En modo solo recarga se muestran flujos brutos del bus DC; el SOC es neto. SOC inicial y final en % y kWh.</p>`}
function reportBalance(q){let {r}=q,t=reportTotals(r);return rmetrics([[rn(r.loadTotal)+' kWh','Demanda'],[rn(t.served)+' kWh','Demanda atendida'],[rn(r.unmet)+' kWh','Déficit'],[t.coverage===null?'No aplica':rn(t.coverage)+' %','Cobertura'],[rn(r.pvTotal)+' kWh','FV disponible'],[rn(r.gridTotal)+' kWh','Red total'],[rn(r.genTotal)+' kWh','Generador'],[rn(t.dis)+' kWh','Descarga AC']])+rtable(['Balance adicional','Energía (kWh)'],[['Solar a cargas',rn(t.solarDirect)],['Solar a batería',rn(t.solarCharge)],['Red a cargas',rn(t.gridLoad)],['Red a batería',rn(t.gridCharge)],['Generador a cargas',rn(t.genLoad)],['Generador a recarga',rn(t.genCharge)],['Horas con aporte del generador',String(t.genHours)],['Recarga total',rn(t.charge)],['Pérdidas de batería',rn(t.loss)],['Excedente FV no aprovechado',rn(r.spill)],['Energía almacenada inicial / final',rn(t.initial)+' / '+rn(t.final)]]);}
function reportSources(q){let {r}=q,t=reportTotals(r),items=[['Solar directa',t.solarDirect,'#d79a1c'],['Red directa',t.gridLoad,'#4678b8'],['Generador directo',t.genLoad,'#7758a0'],['Batería',t.dis,'#087b69'],['Déficit',r.unmet,'#b94c46']];if(!r.loadTotal)return '<p>No hay consumo para distribuir.</p>';let widths=items.map(a=>Math.max(0,a[1]/r.loadTotal*100));return `<div class="r-distribution"><h3>Cómo se atiende la demanda</h3><div class="r-bar">${items.map((a,i)=>`<i style="width:${widths[i]}%;background:${a[2]}"></i>`).join('')}</div><div class="r-legend">${items.map(a=>`<span><i style="background:${a[2]}"></i>${E(a[0])}: ${rn(a[1])} kWh</span>`).join('')}</div></div>`}
function reportArchitecture(s){let c=capacity(s),sources=[];if(s.modules.includes('Fotovoltaica'))sources.push(['Fotovoltaica',rn(c.pv)+' kWp','#d79a1c']);sources.push(['Red eléctrica',rn(s.gridLimit)+' kW disponibles','#4678b8']);if(s.modules.includes('Generador')&&s.genEnabled)sources.push(['Generador',rn(s.generator)+' kW','#7758a0']);let W=760,H=164,box=(x,y,w,h,title,sub,col)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#f2f8f6" stroke="${col}"/><text x="${x+w/2}" y="${y+23}" text-anchor="middle" font-weight="bold">${E(title)}</text><text x="${x+w/2}" y="${y+39}" text-anchor="middle" font-size="12" fill="#526d75">${E(sub)}</text>`;let n=sources.length,left=sources.map(([a,b,col],i)=>{let w=210,x=(W-w*n)/2+i*w+4;return box(x,6,w-8,49,a,b,col)+`<path d="M${x+(w-8)/2} 55 V68 H380 V78" fill="none" stroke="${col}" stroke-width="2"/>`}).join('');let battery=s.modules.includes('Baterías')?box(30,111,190,49,'Almacenamiento',rn(c.bat)+' kWh','#087b69')+'<path d="M280 103 V135 H220" stroke="#087b69" stroke-width="2" stroke-dasharray="4 3" fill="none"/>':'';return `<div class="r-chart"><h3>Arquitectura funcional de la solución</h3><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Diagrama funcional de las fuentes y cargas" viewBox="0 0 ${W} ${H}"><g font-size="14" font-family="Arial,sans-serif" fill="#173840">${left}${box(265,78,230,49,'Conversión y distribución',rn(c.inv)+' kW de inversores','#087b69')}${battery}<path d="M495 103 H535 V135 H540" fill="none" stroke="#4678b8" stroke-width="2"/>${box(540,111,190,49,'Cargas empresariales',rn(energy(s).peak)+' kW pico','#4678b8')}</g></svg><small>Esquema conceptual; no muestra conexiones eléctricas, transferencias ni protecciones reales. Validar mediante plano unifilar.</small></div>`}
// Informe: las dos parejas Parámetro / Valor comparten cuatro anchos estables.
// No se pierde ningún dato: los textos explicativos largos van en notas de ancho completo.
function reportParameterTable(rows){
 const alwaysWide=new Set(['Advertencias FV','Calendario semanal','Tratamiento y desglose de carga','Perfil POA introducido','Temperatura de célula horaria']);
 const normal=[],wide=[];
 for(const row of rows){
  const [name,value]=row,detail=String(value??'Pendiente');
  (alwaysWide.has(name)||detail.length>74?wide:normal).push([name,detail]);
 }
 const leftCount=Math.ceil(normal.length/2),left=normal.slice(0,leftCount),right=normal.slice(leftCount);
 const main=`<div class="r-param-wrap"><table class="r-table r-param-table"><colgroup><col style="width:36%"><col style="width:14%"><col style="width:36%"><col style="width:14%"></colgroup><thead><tr><th>Parámetro</th><th>Valor</th><th>Parámetro</th><th>Valor</th></tr></thead><tbody>${left.map((a,i)=>{const b=right[i];return `<tr><td>${E(a[0])}</td><td>${E(a[1])}</td><td>${b?E(b[0]):''}</td><td>${b?E(b[1]):''}</td></tr>`}).join('')}</tbody></table></div>`;
 return main+(wide.length?`<div class="r-param-notes"><h3>Datos extensos, observaciones y advertencias</h3><dl>${wide.map(([name,value])=>`<div class="r-param-note"><dt>${E(name)}</dt><dd>${E(value).replace(/\s+\|\s+/g,'<br>')}</dd></div>`).join('')}</dl></div>`:'');
}
function reportParams(s){let labels=Object.keys(configs).filter(k=>!(k in pvDefaults&&!s.modules.includes('Fotovoltaica'))&&!(k.startsWith('ev')&&!s.modules.includes('Carga EV'))&&!(k==='generator'&&!s.modules.includes('Generador')));let rows=labels.map(k=>[configs[k][0],String(s.useLoads&&['work','rest'].includes(k)?demandField(s,k).value:simValue(s,k)??'Pendiente')]);if(s.modules.includes('Fotovoltaica')){let m=pvModel(s);rows.push(['Método FV',m.mode],['Arquitectura FV',m.coupled?'DC compatible; energía equivalente de bus':'Límite AC común'],['HSP efectivos',rn(m.hsp)],['Perfil POA introducido',(s.pvHourly||[]).join(' ')||'No introducido'],['Temperatura de célula horaria',(s.pvHourlyTemp||[]).join(' ')||'No introducida'],['Advertencias FV',m.warnings.join(' | ')],['PR histórico','Solo se aplica en modo histórico'])}rows.push(['Calendario semanal',calendarSummary(s)],['Carga EV en descanso',s.evOnRest?'Permitida':'No'],['Duración de simulación',durationHours(s)+' h'],['Inicio de simulación',clockHour(energy(s).startHour)+(s.simStart==null?' (igual al inicio laboral)':' (independiente)')],['Red eléctrica',`${s.voltage} V · ${s.phases} fases · ${s.frequency} Hz`],['Origen de la demanda',s.useLoads?'Inventario detallado':'Perfil laboral simplificado'],['Tratamiento y desglose de carga',loadModeSummary(s)],['Apagones adicionales',(s.outages||[]).map(o=>(o.weekday==null||o.weekday<0?'Diario':weekNames[o.weekday])+' '+rh(o.start)+' · '+o.hours+' h').join('; ')||'Ninguno'],['Generador habilitado',s.genEnabled&&s.modules.includes('Generador')?'Sí':'No'],...(s.genEnabled&&s.modules.includes('Generador')?[["Arranque del generador",({deficit:'Por déficit',schedule:'Horarios',soc:'SOC',combined:'SOC dentro de horarios'})[s.genMode||'deficit']],["Destino",({loads:'Cargas',charge:'Recarga / bus DC',both:'Cargas y recarga'})[s.genTarget||'loads']],["Intervalos diarios",(s.genIntervals||[]).map(o=>rh(o.start)+' · '+o.hours+' h').join('; ')||'Ninguno'],["Límite diario",(s.genMaxHours??24)+' h'],["SOC arranque / parada",(s.genSocStart??50)+' / '+(s.genSocStop??90)+' %'],["Límite recarga generador",(s.genChargeLimit??1500)+' kW'],["Solo apagón",s.genOnlyOutage?'Sí':'No']]:[]),['Autonomía objetivo',s.autonomy+' h'],['Strings / MPPT',(s.strings||'Por confirmar')+' / '+(s.mppt||'Por confirmar')],['Optimizadores',s.optimize?'Previstos; comprobar compatibilidad':'No previstos'],['Estado levantamiento',s.surveyStatus||'Pendiente']);return reportParameterTable(rows)+(s.useLoads?rtable(['Equipo','Cantidad','kW/u','Inicio','Horas','Simult. %','Prioridad'],s.loads.map(a=>[a.name,a.qty,a.kw,rh(a.start),a.hours,a.sim,a.priority])):'')+(s.modules.includes('Fotovoltaica')?pvSummaryHTML(s).replace('<details>','<div>').replace('</details>','</div>').replace('<summary>','<h3>').replace('</summary>','</h3>'):'')+'<p class="r-caption">HSP = horas solares pico, no horas de luz. DoD = profundidad de descarga; SOC = estado de carga. Modelo horario sin arranque de motores, potencia reactiva, exportación a red ni pérdidas de equipos distintas de las incluidas en el rendimiento FV y eficiencias de batería. El modelo no desconecta cargas por prioridad.</p>'}
function reportCompare(s,c,qq){return `<p class="r-note">Mismo consumo, equipos y SOC inicial en cada prueba. Período: ${simPeriod(energy(s))}. Soleado: ${rn(c.sun??(s.pvMode==='hourly'?pvModel(s).hsp:s.sun))} HSP objetivo; nublado: ${rn(c.cloud,0)} % de irradiancia/HSP relativo (no necesariamente igual porcentaje de generación); sin sol: 0 HSP. Los escenarios con red eliminan los cortes; los escenarios con corte simulan ${rn(reportCut(s,c).outHours,0)} h desde las ${rh(reportCut(s,c).outStart)} (si son 24 h, sin red todo el día). El origen del corte es ${c.cutSource==='manual'?'la prueba manual':'el expediente (o 24 h de prueba si no hay un corte declarado)'}. El consumo respeta los días laborables y de descanso; las condiciones solares y los cortes se repiten diariamente. El SOC inicial se aplica una sola vez por escenario. El escenario configurado conserva todos los apagones originales.</p>`+rtable(['Escenario','FV kWh','Red kWh','Gen. kWh','Déficit kWh','Cobertura %','SOC mín. %','SOC final %'],qq.map(q=>{let r=q.r,t=reportTotals(r);return [q.label+(r.groupStatus==='invalid'?' · solo agregado (grupos inválidos)':r.groupStatus==='groups'?' · por grupos':''),rn(r.pvTotal),rn(r.gridTotal),rn(r.genTotal),rn(r.unmet),rn(t.coverage),r.bat?rn(t.min/r.bat*100):'—',r.bat?rn(t.final/r.bat*100):'—']}),'r-compare')+`<div class="r-compare-bars">${qq.map(q=>{let t=reportTotals(q.r);return `<div><span>${E(q.label)}</span><div class="r-bar"><i style="background:#087b69;width:${t.coverage??0}%"></i><i style="background:#b94c46;width:${t.coverage===null?0:100-t.coverage}%"></i></div><b>${t.coverage===null?'N/A':rn(t.coverage)+' %'}</b></div>`}).join('')}</div><div class="r-legend"><span><i style="background:#087b69"></i>Demanda atendida</span><span><i style="background:#b94c46"></i>Déficit</span></div>`;}
function reportGallery(s,c,opts){let a=reportAssets(s,c),orig=a.filter(z=>['Original','Inspección'].includes(z.type)&&opts.original!==false),prop=a.filter(z=>z.type==='Propuesta'&&opts.proposal!==false),others=a.filter(z=>!['Original','Inspección','Propuesta'].includes(z.type)&&opts.proposal!==false),used=new Set(),blocks=[];const fig=(z,t)=>`<figure><div class="r-photo-label">${E(t)}</div><img src="${safeImage(z.data)}" alt="${E(z.name||'Fotografía')}"><figcaption><b>${E(z.zone||'General')}</b><br>${E(z.caption||z.name||'')}${z.work?'<br>'+E(z.work):''}</figcaption></figure>`;for(let v of prop){let o=orig.find(z=>v.originalId&&z.assetId===v.originalId)||orig.find(z=>z.zone===v.zone&&z.zone&&!/general|clasificar/i.test(z.zone));if(o){used.add(o.assetId);blocks.push(`<div class="r-pair"><h3>${E(v.zone||'Zona')} · comparación ${v.originalId&&o.assetId===v.originalId?'vinculada':'por zona'}</h3><div>${fig(o,'Situación actual')}${fig(v,'Solución propuesta')}</div></div>`)}else blocks.push(`<div class="r-pair"><h3>${E(v.zone||'Zona')} · propuesta sin original vinculado</h3><div>${fig(v,'Solución propuesta')}</div></div>`)}let rest=orig.filter(z=>!used.has(z.assetId)).map(z=>fig(z,'Fotografía original')).concat(others.map(z=>fig(z,z.type||'Complementaria')));for(let i=0;i<rest.length;i+=2)blocks.push(`<div class="r-pair"><h3>Registro visual complementario</h3><div>${rest.slice(i,i+2).join('')}</div></div>`);return blocks.join('')||'<p class="r-note">No hay fotografías seleccionadas para este informe. Selecciónalas y confirma su autorización antes de entregar.</p>'}
function reportDocs(s,p,c){let chosen=c.mode==='technical'?DOC:['Levantamiento técnico','Memoria descriptiva','Cargas prioritarias','Plan de ejecución','Ingeniería y protecciones','Ampliaciones y límites'];return chosen.map(t=>`<div class="r-doc"><h3>${E(t)}</h3><div>${E(generated(s,p,t)).replace(/\n/g,'<br>')}</div>${s.docs[t]?`<div class="r-manual"><strong>Aportación técnica del expediente</strong><div>${E(s.docs[t]).replace(/\n/g,'<br>')}</div></div>`:''}</div>`).join('')}
