function designLinkSummary(s){let count=s.inverterCount>0?s.inverterCount:null;return count?`${count} × ${s.unitInverter} kW = ${s.inverter} kW. MPPT: ${s.pvMppt||'pendiente'}.`:`Potencia total manual: ${s.inverter} kW. Indica número y potencia unitaria si deseas vincularlos.`}
function designSharedFields(s,calc=false){return formDesign(s,[['inverterCount','Cantidad de inversores','Ej. 2 · Si se informa, cantidad × potencia individual fija el total.'],['unitInverter','Potencia por inversor (kW)','Ej. 35 · Potencia AC nominal por unidad.'],['pvParallel','Strings totales','Ej. 20 · Mismo total del simulador.'],['pvMppt','MPPT totales','Ej. 12 · Mismo total del simulador.'],['mpptPerInverter','MPPT por inversor','Ej. 6 · Para unidades idénticas; total automático.'],['dcPerInverter','Entrada FV admisible por inversor (kW)','Ej. 90 · Confirmar mediante ficha OEM.'],['optimizerMode','Arquitectura de módulos','No se modifica PR automáticamente. Microinversores requieren estudio AC independiente.',['Sin optimizadores','Selectivos DC','Todos DC','Microinversores AC']],['optimizerCount','Optimizadores selectivos (ud)','Ej. 30 · Solo se usa en modo selectivo.'],['shadeLoss','Pérdida FV residual (%)','Ej. 5 · Pérdida adicional comprobada, no repetir pérdidas del PR.']],calc)+`<p id="designLinkSummary" class="notice">${E(designLinkSummary(s))}</p>${s.optimizerMode==='Microinversores AC'?'<p class="warn">Microinversores: rama AC independiente del inversor BESS. Por defecto no opera durante cortes sin confirmación de isla.</p>':''}`}
