function technicalCheck(s){let count=s.inverterCount>0&&Number.isInteger(s.inverterCount)?s.inverterCount:null,unit=count&&s.unitInverter>0?s.unitInverter:null,ns=Number(s.pvSeries)||0,np=Number(s.pvParallel)||0,mp=Number(s.pvMppt)||0,voc=Number(s.pvVoc)||0,vmp=Number(s.pvVmp)||0,imp=Number(s.pvImp)||0,isc=Number(s.pvIsc)||0,pf=v35Number(s.designPF)??1,top=s.gridTopology,v=Number(s.voltage),ac=null,errors=[],pending=[];
if(count&&unit&&Math.abs(count*unit-s.inverter)>1e-6)errors.push('Cantidad × potencia unitaria no coincide con potencia total.');if(s.strings&&np&&Number(s.strings)!==np)errors.push('Strings históricos contradictorios; revisar total FV.');if(s.mppt&&mp&&Number(s.mppt)!==mp)errors.push('MPPT históricos contradictorios; revisar total FV.');
if(v>0&&pf>0&&pf<=1&&topologyLabels.slice(1).includes(top))ac=(unit||s.inverter)*1000/(v*pf*(top==='Trifásico'?Math.sqrt(3):1));else pending.push('Topología, tensión o factor de potencia AC por confirmar.');
let cold=ns&&voc?ns*voc*(1+(Number(s.pvVocCoeff??-.28)/100)*(Number(s.pvCold??5)-25)):null,hot=ns&&vmp&&v35Number(s.hotCell)!==null?ns*vmp*(1+(Number(s.pvVmpCoeff??-.3)/100)*(Number(s.hotCell)-25)):null;
let rows=[];if(s.modules.includes('Fotovoltaica')&&s.optimizerMode!=='Microinversores AC'){if(!ns||!np||ns*np!==Number(s.panels)||!mp||!count||!s.mpptPerInverter||count*s.mpptPerInverter!==mp||np<1||mp>12000)pending.push('Reparto por inversor pendiente: comprobar cantidad de paneles, serie, strings y MPPT.');else{let base=Math.floor(np/count),extra=np%count;for(let i=0;i<count;i++){let strings=base+(i<extra?1:0),group=[],q=Math.floor(strings/s.mpptPerInverter),rem=strings%s.mpptPerInverter;for(let j=0;j<s.mpptPerInverter;j++){group.push(q+(j<rem?1:0))}rows.push({unit:i+1,strings,group,kwp:strings*ns*s.watts/1000});if(s.dcPerInverter>0&&strings*ns*s.watts/1000>s.dcPerInverter)errors.push('Inversor '+(i+1)+': potencia FV nominal supera el límite DC declarado.');}}
if(!cold||!hot||!imp||!isc||!s.pvMaxVoc||!s.pvMpptMin||!s.pvMpptMax||!s.pvMpptA||!s.pvMpptIsc||!s.dcPerInverter)pending.push('Faltan datos de ficha FV, temperatura o límites de entrada.');if(cold&&s.pvMaxVoc&&cold>=s.pvMaxVoc*(1-(s.voltageMargin||0)/100))errors.push('Voc frío supera límite de diseño. No conectar.');if(hot&&s.pvMpptMin&&hot<s.pvMpptMin)errors.push('Vmp caliente inferior a ventana MPPT.');if(mp&&np&&imp&&s.pvMpptA&&Math.ceil(np/mp)*imp>s.pvMpptA)errors.push('Imp nominal por MPPT supera límite.');if(mp&&np&&isc&&s.pvMpptIsc&&Math.ceil(np/mp)*isc>s.pvMpptIsc)errors.push('Isc nominal por MPPT supera límite.');if(s.optimizerMode==='Microinversores AC'&&s.microIslandMode==='Aprobada por fabricante'&&!s.microIslandKW)pending.push('Falta límite de acoplamiento AC en isla aprobado por fabricante.');}
let dc=s.batteryMinV>0&&s.bdischarge>0?s.bdischarge*1000/(s.batteryMinV*Math.max(.01,s.eff/100)):null;
if(s.modules.includes('Baterías')){if(!dc||!s.bmsProtocol||!s.batteryConnection||s.batteryConnection==='Por confirmar'||!s.bmsChargeKW||!s.bmsDischargeKW||!s.batteryMaxV)pending.push('BMS, tensión, arquitectura y límites de carga/descarga pendientes.');if(s.batteryMaxV>0&&s.batteryMinV>s.batteryMaxV)errors.push('Rango de tensión BESS incoherente.');if(s.bmsDischargeKW>0&&s.bdischarge>s.bmsDischargeKW)errors.push('Descarga configurada superior al BMS.');if(s.bmsChargeKW>0&&s.bcharge>s.bmsChargeKW)errors.push('Carga configurada superior al BMS.');}
let section=ac&&s.acDistance>0&&s.designDrop>0?((top==='Trifásico'?Math.sqrt(3):2)*.0175*s.acDistance*ac/(v*s.designDrop/100)):null;
let area=s.panels>0&&s.panelLength>0&&s.panelWidth>0?s.panels*s.panelLength*s.panelWidth:null,roofArea=s.roofLength>0&&s.roofWidth>0?s.roofLength*s.roofWidth:null;
if(area&&roofArea&&area>roofArea)errors.push('Área de módulos supera área rectangular declarada; faltan pasillos y separaciones.');if(!s.shortCircuit||!s.earthDesign||!s.anchorPlan||!s.windData||!s.factoryConfirmation||!s.confirmedBy)pending.push('Faltan cálculos normativos, estructura/tierra, confirmación OEM o revisión especializada.');
let model=s.modules.includes('Fotovoltaica')?pvModel(s):null;if(model?.micro){rows=[];let invalid=model.warnings.filter(w=>w.startsWith('PELIGRO')||w.includes('supera'));errors.push(...invalid);pending.push(...model.warnings.filter(w=>!invalid.includes(w)&&w.startsWith('Microinversores')));cold=s.pvVoc>0?s.pvVoc*(1+(s.pvVocCoeff??-.28)/100*((s.pvCold??5)-25)):null;hot=s.pvVmp>0&&s.hotCell!=null?s.pvVmp*(1+(s.pvVmpCoeff??-.3)/100*(s.hotCell-25)):null;}else if(s.pvAssignments?.length){rows=[];if(model?.layout&&model.assignments?.length){for(let i=1;i<=(count||0);i++){let gs=model.assignments.filter(g=>g.unit===i);rows.push({unit:i,strings:gs.reduce((a,g)=>a+g.strings,0),group:gs.map(g=>'MPPT '+g.mppt+': '+g.strings+'×'+g.series),kwp:gs.reduce((a,g)=>a+g.strings*g.series*s.watts/1000,0)})}cold=model.coldVoc||null;hot=s.pvVmp>0&&s.hotCell!=null?Math.min(...model.assignments.map(g=>g.series*s.pvVmp*(1+(s.pvVmpCoeff??-.3)/100*(s.hotCell-25)))):null;}else pending.push('Asignación individual incompleta o no válida.');errors.push(...(model?.warnings||[]).filter(w=>w.includes('supera')||w.startsWith('PELIGRO')))}for(let ref of Object.values(s.catalogEnergyRefs||{})){if(!catalogRefMatches(s,ref))pending.push('Ficha de catálogo modificada: '+ref.name);if(Object.values(ref.values||{}).some(v=>v===null))pending.push('Ficha incompleta: '+ref.name+'; los valores de inicio no confirman compatibilidad.')}return {count,unit,ac,dc,cold,hot,section,area,roofArea,rows,errors:[...new Set(errors)],pending:[...new Set(pending)]};}
function engineeringAudit(s){let a=technicalCheck(s),f=(v,u)=>v==null?'Pendiente':fmt(v,2)+' '+u;return `<div class="grid">${metric(f(a.ac,'A'),'Corriente AC por unidad (o total si no hay cantidad)')}${metric(f(a.dc,'A'),'Corriente BESS estimada en descarga')}${metric(f(a.cold,'V'),'Voc frío por string')}${metric(f(a.hot,'V'),'Vmp caliente por string')}${metric(f(a.section,'mm²'),'Sección mínima teórica por caída · cobre 20 °C')}${metric(f(a.area,'m²'),'Superficie neta de módulos')}</div><p class="warn">No son calibres ni protecciones aprobados. Falta comprobar ampacidad, temperatura, instalación, selectividad, poder de corte, neutro, puesta a tierra y viento. Fase partida: comprobar equilibrio de cargas L–N.</p>${a.rows.length?`<div class="scroll"><table><tr><th>Inversor</th><th>Strings</th><th>Strings por MPPT (0 = libre)</th><th>FV kWp</th></tr>${a.rows.map(r=>`<tr><td>${r.unit}</td><td>${r.strings}</td><td>${E(r.group.join(' / '))}</td><td>${fmt(r.kwp)}</td></tr>`).join('')}</table></div>`:''}${a.errors.map(t=>`<p class="warn">${E(t)}</p>`).join('')}${a.pending.map(t=>`<p class="muted">${E(t)}</p>`).join('')}`}
function storageFields(s,calc){return formDesign(s,[['batterySOH','Estado de salud SOH (%)','100 = nominal; capacidad efectiva = nominal × SOH.'],['bmsChargeKW','Límite BMS carga (kW)','Vacío = sin verificar.'],['bmsDischargeKW','Límite BMS descarga (kW)','Vacío = sin verificar.'],['auxKW','Consumo auxiliar permanente (kW)','Ej. 0.4 · No duplicar cargas del inventario.']],calc)}
function fuelFields(s,calc){return formDesign(s,[['genBrand','Marca','Ej. fabricante','text'],['genModel','Modelo','Ej. referencia','text'],['genKva','Potencia aparente (kVA)','De placa.'],['genPF','Factor de potencia nominal','Ej. 0.8 · De placa.'],['genFuel25','Combustible al 25% (L/h)','De curva del fabricante.'],['genFuel50','Combustible al 50% (L/h)','De curva del fabricante.'],['genFuel75','Combustible al 75% (L/h)','De curva del fabricante.'],['genFuel100','Combustible al 100% (L/h)','De curva del fabricante.'],['genTank','Tanque (L)','Capacidad nominal.'],['genAvailableFuel','Combustible disponible (L)','Medición; no tanque nominal.'],['genMinLoad','Carga mínima recomendada (%)','De manual.'],['genFuelMode','Tratamiento del combustible','Modo opcional: limita el aporte según la curva y combustible disponible.',['Solo estimar','Limitar por combustible']],['genFuelIdle','Consumo a ralentí (L/h)','De la ficha; obligatorio para limitar.'],['genWarmup','Calentamiento (min)','De manual; incluir 0 si no aplica.'],['genCooldown','Enfriamiento (min)','De manual; incluir 0 si no aplica.'],...(canSeeFinance()?[['genFuelCost','Costo por litro (privado)','USD/L · Solo presupuesto local.']]:[])],calc)+`<div id="fuelResult">${fuelSummary(s)}</div>`}
function fuelSummary(s){if(s.acGroupDispatch===true){let d=independentGroupDispatch(s);if(!d.summary)return '<p class="warn">Combustible por grupos no calculado: '+E(d.errors.join('; '))+'</p>';return '<p>Consumo de generadores por tablero. Las horas y litros de diferentes equipos no se duplican como un único generador.</p>'+rtable(['Tablero','Generación kWh','Combustible usado L','Restante L','Intervalos bajo carga mínima'],d.groups.map((g,i)=>[g.name,fmt(g.genTotal,2),g.fuelUsed==null?'No limitado':fmt(g.fuelUsed,2),g.fuelLeft==null?'—':fmt(g.fuelLeft,2),g.rows.filter(r=>r.genRuntime>0&&r.gen/r.genRuntime<(s.genMinLoad||0)/100*(s.acGroups[i].genKW||0)).length]))}let r=calculate(s);if(r.fuelModel){if(!r.fuelValid)return `<p class="warn">${E(r.fuelWarnings.join('; '))} Introduce combustible disponible, curva de 0–100% y tiempos de arranque/parada.</p>`;let runtime=r.rows.reduce((z,h)=>z+h.genRuntime,0),idle=r.rows.reduce((z,h)=>z+h.genIdleTime,0),low=r.rows.filter(h=>h.genRuntime>0&&h.gen/h.genRuntime<((s.genMinLoad||0)/100)*s.generator).length;return `<p>Consumido ${fmt(r.fuelUsed,2)} L de ${fmt(s.genAvailableFuel,2)} L · restante ${fmt(r.fuelLeft,2)} L. Operación ${fmt(runtime,2)} h; calentamiento/enfriamiento ${fmt(idle,2)} h. ${low?low+' intervalos por debajo de carga mínima. ':''}Modelo horario aproximado; la fracción terminal es conservadora y no comprueba transitorios.</p>`}let curve=[s.genFuel25,s.genFuel50,s.genFuel75,s.genFuel100].map(v35Number);if(curve.some(v=>v===null||v<=0)||!s.generator)return '<p class="muted">Curva de combustible incompleta; autonomía por combustible pendiente.</p>';let liters=0,low=0;for(let h of r.rows.filter(x=>x.genRunning)){let pct=h.gen/s.generator*100;if(pct<(s.genMinLoad||0))low++;let p=Math.max(25,Math.min(100,pct)),i=Math.min(2,Math.floor((p-25)/25)),frac=(p-(25+25*i))/25;liters+=curve[i]+frac*(curve[i+1]-curve[i])}let available=v35Number(s.genAvailableFuel),hours=r.rows.filter(x=>x.genRunning).length;return `<p>Combustible estimado: ${fmt(liters)} L en ${hours} h. ${available!==null&&liters>0?`Autonomía aproximada al consumo medio: ${fmt(available/(liters/hours))} h.`:''} ${available!==null&&available<liters?'Combustible disponible insuficiente.':''} ${low?`${low} h por debajo de carga mínima. `:''}Estimación lineal desde 25%; no incluye arranque, calentamiento ni agotamiento automático.</p>`}
function outageFields(s,calc){let days=['Todos','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];return `<p class="muted">Selecciona un día o repetición diaria. El apagón puede continuar al día siguiente.</p><div class="scroll"><table><tr><th>Día de inicio</th><th>Hora</th><th>Duración h</th><th></th></tr>${(s.outages||[]).map((o,i)=>`<tr><td><select onchange="setOutage(${i},'weekday',this.value,${calc},true)">${days.map((d,j)=>`<option value="${j-1}" ${(o.weekday??-1)===j-1?'selected':''}>${d}</option>`).join('')}</select></td>${['start','hours'].map(k=>`<td><input type="number" min="0" max="${k==='start'?23:24}" value="${E(o[k])}" oninput="setOutage(${i},'${k}',this.value,${calc})"></td>`).join('')}<td>${B('Eliminar',`removeOutage(${i},${calc})`,'danger small')}</td></tr>`).join('')}</table></div>${B('Agregar apagón',`addOutage(${calc})`)}`}
function setOutage(i,k,v,calc){let s=calc?calcSite:site(),n=Number(v);s.outages[i][k]=Math.max(k==='weekday'?-1:0,Math.min(k==='weekday'?6:k==='start'?23:24,n||0));if(calc)refreshDerived();else touch()}
function addOutage(calc){let s=calc?calcSite:site();(s.outages??=[]).push({weekday:-1,start:12,hours:1});if(!calc)touch();render()}
function removeOutage(i,calc){let s=calc?calcSite:site();s.outages.splice(i,1);if(!calc)touch();render()}
function liveBars(s){let m=energy(s),sum=k=>m.rows.reduce((a,r)=>a+(Number(r[k])||0),0),ratio=(v,t)=>t>0?100*v/t:null,bar=(label,v,t)=>{let pc=ratio(v,t);return `<div style="margin:10px 0"><div class="row between"><b>${E(label)}</b><span>${pc===null?'—':fmt(pc,1)+'%'} · ${fmt(v)} kWh</span></div>${pc===null?'<p class="muted">No aplica: denominador cero.</p>':`<progress aria-label="${E(label)}" aria-valuetext="${fmt(pc,1)}%" max="100" value="${Math.max(0,Math.min(100,pc))}" style="width:100%;accent-color:#127766"></progress>`}</div>`};let start=m.rows[0].socStart,end=m.end,pvPotential=m.pvTotal+sum('pvClipped')+sum('pvShadeLoss');return `${balanceNotice(m)}<p><b>Pico ${fmt(m.peak)} kW</b> · Consumo ${fmt(m.loadTotal)} kWh en ${m.rows.length} h</p>${bar('Demanda cubierta',Math.max(0,m.loadTotal-m.unmet),m.loadTotal)}${bar('Energía no atendida',m.unmet,m.loadTotal)}${bar('Solar directa / demanda',sum('pvDirect'),m.loadTotal)}${bar('Red directa / demanda',Math.max(0,m.gridTotal-sum('gridRecharge')),m.loadTotal)}${bar('Generador directo / demanda',sum('genDirect'),m.loadTotal)}${bar('Descarga batería / demanda',sum('dis'),m.loadTotal)}${bar('Recorte FV / potencial FV',sum('pvClipped'),pvPotential)}${bar('Excedente / FV disponible',m.spill,m.pvTotal)}${bar('SOC final / capacidad efectiva',end,m.bat)}<p>FV disponible: ${fmt(m.pvTotal)} kWh · Pérdida FV adicional: ${fmt(sum('pvShadeLoss'))} kWh · Pérdidas de almacenamiento: ${fmt(sum('loss'))} kWh · SOC inicial ${m.bat?fmt(start/m.bat*100)+'%':'—'}, mínimo ${m.bat?fmt(Math.min(start,...m.rows.map(r=>r.soc))/m.bat*100)+'%':'—'}, cambio ${fmt(end-start)} kWh. Red a recarga: ${fmt(sum('gridRecharge'))} kWh.</p>${end<start-1e-6?'<p class="warn">El escenario consume reserva inicial. Cobertura completa no demuestra sostenibilidad repetitiva.</p>':''}`}
function visualSignature(s){return JSON.stringify([s.panels,s.watts,s.inverter,s.battery,s.pvSeries,s.pvParallel,s.pvMppt,s.optimizerMode,s.roof,s.modules,s.inverterCount,s.unitInverter,s.pvAssignments,s.mountOrientation,s.mountTilt,s.panelLength,s.panelWidth,s.panelsPerRow,s.rowGap,s.mountModuleGap,s.pathway,s.roofLength,s.roofWidth,s.batteryConnection,s.acConnection])}
