function timelineCalendar(s){let today=new Date().toISOString().slice(0,10),dated=s.tasks.filter(t=>t.start&&t.end&&t.start<=t.end),first=dated.map(t=>t.start).sort()[0],last=dated.map(t=>t.end).sort().at(-1),span=first&&last?Math.max(1,(Date.parse(last)-Date.parse(first))/86400000+1):1;return `<p>${E(first||'Sin inicio')} — ${E(last||'Sin fin')}</p>${s.tasks.map(t=>{let dep=t.dependsOn&&s.tasks.find(d=>d.name===t.dependsOn),msg=[];if(t.start&&t.end&&t.start>t.end)msg.push('Fechas invertidas');if(t.end&&t.end<today&&Number(t.progress)<100)msg.push('Retrasada');if(t.dependsOn&&!dep)msg.push('Dependencia no localizada');if(dep&&(dep===t||dep.dependsOn===t.name))msg.push('Dependencia circular');if(dep?.end&&t.start&&dep.end>t.start)msg.push('Comienza antes de terminar dependencia');let valid=t.start&&t.end&&t.start<=t.end&&first;return `<div style="margin:12px 0"><b>${E(t.name||'Actividad')}</b> · ${E(t.start||'—')} a ${E(t.end||'—')} ${valid?`<div style="height:12px;background:#e2e8e5;border-radius:4px"><div style="height:12px;border-radius:4px;background:#127766;margin-left:${100*(Date.parse(t.start)-Date.parse(first))/86400000/span}%;width:${100*((Date.parse(t.end)-Date.parse(t.start))/86400000+1)/span}%"></div></div>`:''}${msg.length?`<p class="warn">${E(msg.join(' · '))}</p>`:''}</div>`}).join('')||empty('No hay actividades.')}`}
function addLogisticsTasks(){for(let name of ['Fabricación','Transporte internacional','Recepción e inspección'])if(!site().tasks.some(t=>t.name===name))site().tasks.push({id:uid(),name,start:'',end:'',owner:'',status:'Pendiente',progress:0,weight:1});touch();render()}

