function equipmentDialog(id){let m=state.library.find(x=>x.id===id&&x.kind==='consumer')||{id:uid(),kind:'consumer',priority:'P2 — Esencial',sim:100,hours:8,start:8};let fields=[['Nombre','name','text'],['Familia','family','text'],['Subcategoría','subcategory','text'],['Marca','brand','text'],['Modelo','model','text'],['Potencia nominal kW','nominal','number'],['Potencia normal kW','normal','number'],['Potencia máxima kW','max','number'],['Potencia arranque kW','startKW','number'],['Resistencia descongelación kW','defrostKW','number'],['Tensión V','voltage','number'],['Factor de potencia','pf','number'],['Corriente nominal A','amps','number'],['Corriente arranque A','startA','number'],['Simultaneidad / ciclo efectivo %','sim','number'],['Horas de uso al día','hours','number'],['Inicio de uso h','start','number'],['Fuente / ficha / medición','source','text'],['URL ficha técnica','datasheet','text'],['URL de imagen','imageUrl','text'],['Energía anual de ensayo kWh','annualKWh','number'],['Rango de tensión y frecuencia','voltageRange','text'],['Frecuencia exclusiva de ficha (Hz; vacío si admite varias)','frequencyHz','number'],['Origen del dato','sourceType','text'],['Restricciones de alimentación OEM','supplyRestriction','text']];modal('Ficha de equipo consumidor',`<div class="fields">${fields.map(([l,k,t])=>mfield(l,k,m[k]??'',t,k==='name')).join('')}${modalSelect('Prioridad','priority',m.priority,priorities)}</div><label class="check"><input type="checkbox" name="verified" ${m.verified?'checked':''}> Verificado por especialista</label>`,f=>{let d=Object.fromEntries(f);for(let [,k,t] of fields)if(t==='number'){d[k]=v35Number(d[k]);if(d[k]!==null&&d[k]<0){toast('Los valores no pueden ser negativos');return false}}if((d.pf!==null&&(d.pf<=0||d.pf>1))||(d.sim!==null&&d.sim>100)||(d.hours!==null&&d.hours>24)||(d.start!==null&&d.start>23)||(d.max!==null&&d.nominal!==null&&d.max<d.nominal)){toast('Revisa los límites de potencia, factor de potencia y horario.');return false}if(f.has('verified')&&!d.source.trim()){toast('Indica fuente antes de verificar.');return false}Object.assign(m,d,{verified:f.has('verified')});if(!id)state.library.push(m);touch();render()})}
function addEquipmentDialog(){modal('Agregar equipo',`<p>Selecciona una ficha o agrega un equipo manualmente. La instalación conserva una copia independiente.</p>${B('Agregar manualmente',"$('dialog').close();addRow('loads')",'')}${B('Cargar ejemplos',"seedEquipment();$('dialog').close();addEquipmentDialog()") }<input id="equipmentSearch" placeholder="Buscar equipo" oninput="equipmentPicker(this.value)"><div id="equipmentPicker"></div>`,()=>false);equipmentPicker('');$('modalForm').querySelector('button[type=submit]').style.display='none'}
