if(s.optimizerMode==='Selectivos DC')update('opt',r=>{r.qty=s.optimizerCount>0?Math.ceil(Math.min(s.panels,s.optimizerCount)*(1+(s.reserveConnectors??s.reserve)/100)):'';r.note='Optimizadores selectivos; confirmar selección y compatibilidad OEM'});
