 if(valid){update('gen',r=>{r.excluded=true});for(let g of groups)if(+g.genKW>0)add('gen_group_'+g.id,'Respaldo','Generador '+g.genKW+' kW · '+g.name,'ud',1,'Potencia aparente '+g.genKVA+' kVA; FP '+g.genPF+'; confirmar transferencia dedicada y modelo.',{datasheet:g.genReference,dataStatus:'Calculado preliminar',currentType:'AC'});}
 else update('gen',r=>{r.name='Generadores por grupo · '+s.generator+' kW totales';r.qty='';r.installed=null;r.spare=null;r.dataStatus='Pendiente';r.note='Falta conciliar cantidades, potencias y referencias de transferencia por grupo; no es un único equipo.'});
