function financePanel(s){let f=s.privateFinance||{};return panel('Logística, costos y rentabilidad · privado',`<div class="fields">${privateExpenseFields.map(([k,l])=>`<label class="field">${E(l)}<input type="number" min="0" step="any" value="${E(f[k]??'')}" oninput="setFinance('${k}',this.value)"></label>`).join('')}</div><label class="check"><input type="checkbox" id="financeConfirmed" ${f.confirmed?'checked':''} onchange="setFinance('confirmed',this.checked)"> He revisado todos los costos adicionales; los campos vacíos no aplican.</label><div id="financeSummary">${financeSummary(s)}</div><p class="muted">Recargo sobre costo ≠ margen sobre venta. Los precios sugeridos no se emiten sin revisión. Evita duplicar partidas incluidas en el precio EXW.</p>`)}
