function exportProfiles(p){return panel('Perfiles de entrega',`<p>El perfil técnico utiliza los controles de informe y ZIP de esta página. Los demás generan expedientes separados.</p><div class="actions">${B('Solicitud a proveedor (RFQ)','supplierDialog()')}${B('Oferta comercial al cliente · ZIP','commercialZip(project())')}</div><details><summary>Comprobaciones previas de contenido</summary>${exportAudit(p)}</details><p class="warn">La exclusión de costos estructurados no detecta secretos escritos dentro de imágenes, textos o documentos libres. Revísalos antes de compartir.</p>`)}

function canSeeFinance(){return !shared||me?.role==='admin'}
function securityPanel(){if(globalThis.EVEngineeringStore)return panel('Cuenta y permisos','<p>Acceso mediante la cuenta de Bonaire. El servidor valida la autorización de ingeniería y de las secciones compartidas. Los permisos se administran en Bonaire. No se crean cuentas locales.</p>');if(!shared)return panel('Acceso empresarial','<p class="warn">Modo autónomo sin cuentas ni permisos de aplicación. Cualquier persona que acceda a este perfil del navegador puede ver los datos, incluidos costos. Protege tu cuenta de Windows y descarga respaldos privados. Para trabajo compartido, el servidor sigue siendo opcional y requiere autenticación.</p>');return panel('Cuenta y permisos',`<p>${E(me?.username)} · ${E(me?.role==='admin'?'Administrador':'Trabajador técnico')}</p><p class="muted">Solo el administrador recibe costos, presupuestos, ofertas privadas y revisiones con datos internos. Los trabajadores no pueden eliminar expedientes completos ni instalaciones existentes.</p>${B('Cambiar contraseña','changeLocalPassword()')}${B('Bloquear / cerrar sesión','logout()')}${me?.role==='admin'?B('Usuarios y permisos','manageLocalUsers()')+B('Auditoría de cambios','localAuditDialog()')+(project()?B('Acceso a este expediente','projectAccessDialog()'):''):''}`)}
async function changeLocalPassword(){modal('Cambiar contraseña local',`<label class="field">Contraseña actual<input name="old" type="password" autocomplete="current-password" required></label><label class="field">Contraseña nueva<input name="new" type="password" minlength="12" maxlength="1024" autocomplete="new-password" required></label><label class="field">Repetir contraseña nueva<input name="repeat" type="password" minlength="12" autocomplete="new-password" required></label>`,async f=>{if(f.get('new')!==f.get('repeat'))return toast('Las contraseñas no coinciden'),false;try{await persist();if(dirty)return toast('Resuelve el guardado antes de cambiar contraseña'),false;await api('/api/password',{method:'POST',body:JSON.stringify({old:f.get('old'),new:f.get('new')})});if(db)await putStore('v35draft:'+me.username,null);location.reload()}catch(e){toast(e.message);return false}},'Cambiar contraseña')}
async function manageLocalUsers(){if(me?.role!=='admin')return;try{let r=await api('/api/users');modal('Usuarios locales',`<div class="scroll"><table><tr><th>Cuenta</th><th>Rol</th><th>Estado</th><th></th></tr>${r.users.map(u=>`<tr><td>${E(u.username)}</td><td>${E(u.role)}</td><td>${u.active?'Activa':'Desactivada'}</td><td>${u.active&&u.username!==me.username?B('Desactivar',`disableLocalUser(${arg(u.username)})`,'danger small'):''}</td></tr>`).join('')}</table></div><h3>Crear una cuenta</h3>${mfield('Nombre de usuario','username','','text',true)}${modalSelect('Rol','role','worker',['worker','admin'])}<label class="field">Contraseña temporal<input name="password" type="password" minlength="12" maxlength="1024" autocomplete="new-password" required><small class="field-help">Entrega de forma segura; la persona debe cambiarla al entrar.</small></label>`,async f=>{try{await api('/api/users/create',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});toast('Cuenta creada');setTimeout(manageLocalUsers,100)}catch(e){toast(e.message);return false}},'Crear cuenta')}catch(e){toast(e.message)}}
async function disableLocalUser(username){if(!confirm('¿Desactivar esta cuenta y revocar sus sesiones?'))return;try{await api('/api/users/disable',{method:'POST',body:JSON.stringify({username})});$('dialog').close();await manageLocalUsers()}catch(e){toast(e.message)}}
async function localAuditDialog(){try{let r=await api('/api/audit');modal('Auditoría local',`<div class="scroll"><table><tr><th>Usuario</th><th>Operación</th><th>Registro</th><th>Revisión</th><th>Fecha local</th></tr>${r.events.map(a=>`<tr><td>${E(a.username)}</td><td>${E(a.event)}</td><td>${E(a.kind+' / '+a.record_id)}</td><td>${E(a.rev)}</td><td>${E(new Date(a.created_at*1000).toLocaleString())}</td></tr>`).join('')}</table></div>`,()=>{},'Cerrar')}catch(e){toast(e.message)}}
async function projectAccessDialog(){let p=project();if(!p||!shared||me?.role!=='admin')return;try{let r=await api('/api/users'),list=r.users.filter(u=>u.role!=='admin'&&u.active);modal('Permisos del expediente',`<p>Los administradores mantienen acceso. Si restringes el expediente, solo los trabajadores seleccionados reciben sus datos en el servidor.</p><label class="check"><input name="all" type="checkbox" ${p.allowedUsers==null?'checked':''}> Todos los trabajadores activos</label>${list.map(u=>`<label class="check"><input name="allowedUser" type="checkbox" value="${E(u.username)}" ${p.allowedUsers==null||p.allowedUsers.includes(u.username)?'checked':''}> ${E(u.username)}</label>`).join('')}`,f=>{p.allowedUsers=f.has('all')?null:f.getAll('allowedUser');touch();render()},'Guardar permisos')}catch(e){toast(e.message)}}
async function legacyRecovery(){let saved=db&&await getStore('workspace').catch(()=>null);$('nav').innerHTML='<div class="brand"><img src="favicon.svg" width="42" height="42" alt=""><div><strong>ENERGÍA VITAL</strong><small>PRO STUDIO</small></div></div>';$('top').innerHTML='<span>Acceso local protegido</span>';$('main').innerHTML=`<div class="panel"><h1>Inicia el servidor local</h1><p>La aplicación empresarial requiere autenticación local. No necesita Internet ni Cloudflare.</p><p>En Windows, ejecuta INICIAR_SERVIDOR_WINDOWS.bat y abre http://127.0.0.1:8765. Si aún no tienes cuenta, crea el primer administrador con CREAR_ADMIN_WINDOWS.bat.</p>${saved?'<p class="warn">Se encontró una base anterior de este navegador sin autenticación. Conserva un respaldo privado y migra desde una sesión de administrador. No guardes tu JSON en una carpeta compartida.</p>'+B('Recuperar respaldo JSON anterior','downloadLegacyWorkspace()',''):''}<p class="muted">Esta pantalla no abre ni modifica expedientes sin sesión. La base anterior permanece intacta.</p></div>`}
async function downloadLegacyWorkspace(){let saved=db&&await getStore('workspace');if(saved&&confirm('El JSON anterior puede contener información privada sin cifrar. ¿Descargar para migración?'))downloadJSON('EV_respaldo_legacy_privado',saved)}

function pvAssignmentFields(s,calc){let arr=s.pvAssignments||[],mode=designValue(s,'optimizerMode');return `<details ${mode==='Microinversores AC'?'open':''}><summary>Rama alternativa · microinversores AC</summary><p class="warn">Solo se utiliza al elegir Microinversores AC. Por defecto se apagan sin red (anti-isla). La operación en isla necesita autorización del fabricante y un sistema formador de red compatible.</p>${formDesign(s,[['microCount','Cantidad de microinversores','Ej. 50 · Unidades del modelo.'],['microAC','Potencia AC individual (kW)','Ej. 0.8 · De ficha.'],['microInputs','Entradas por microinversor','Ej. 2 · Módulos admisibles.'],['microMaxV','Tensión máxima por entrada (V)','Ej. 60 · De ficha.'],['microMaxIsc','Isc permitida por entrada (A)','Ej. 20 · De ficha.'],['microMinV','Mínima tensión MPPT (V)','Ej. 25 · De ficha.'],['microMpptMax','Máxima tensión MPPT (V)','Ej. 50 · De ficha.'],['microIslandMode','Operación durante apagones','No se presupone compatibilidad.',['No autorizada','Aprobada por fabricante']],['microIslandKW','Límite de acoplamiento en isla (kW)','Debe estar aprobado por OEM.']],calc)}</details><details ${arr.length?'open':''}><summary>Asignación detallada por inversor y MPPT DC</summary><p>Si se declaran entradas individuales, sustituyen el reparto uniforme en el método FV avanzado. Cada entrada admite strings de igual longitud; pueden diferir entre entradas. No conectar hasta verificar toda la configuración.</p><div class="actions">${B('Generar reparto equilibrado',`generateAssignments(${calc})`)}${B('Añadir entrada',`addAssignment(${calc})`)}${B('Volver al reparto automático',`clearAssignments(${calc})`)}</div><div id="assignmentTable">${assignmentTable(s,calc)}</div></details>`}
function assignmentTable(s,calc){let arr=s.pvAssignments||[],fields=[['unit','Inversor'],['mppt','MPPT'],['series','Mód./string'],['strings','Strings'],['maxA','Imp límite A'],['maxIsc','Isc límite A'],['minV','V MPPT mín'],['maxV','V MPPT máx'],['maxVoc','Voc máx V']];return `<p>${arr.length} entradas declaradas · ${arr.reduce((n,a)=>n+(Number(a.series)||0)*(Number(a.strings)||0),0)} / ${s.panels} módulos. Campos eléctricos en blanco utilizan los límites comunes.</p>${arr.length?`<div class="scroll"><table><tr>${fields.map(([,l])=>`<th>${E(l)}</th>`).join('')}<th></th></tr>${arr.map((a,i)=>`<tr>${fields.map(([k])=>`<td><input type="number" min="0" step="any" value="${E(a[k]??'')}" oninput="setAssignment(${i},'${k}',this.value,${calc})" aria-label="${k} ${i+1}"></td>`).join('')}<td>${B('×',`removeAssignment(${i},${calc})`,'danger small')}</td></tr>`).join('')}</table></div>`:''}`}
function assignRefresh(calc,rerender=false){if(calc)refreshDerived();else touch();if(rerender)render()}
function generateAssignments(calc){let s=calc?calcSite:site(),count=Math.trunc(s.inverterCount||0),mp=Math.trunc(s.mpptPerInverter||0),series=Math.trunc(s.pvSeries||0),strings=Math.trunc(s.pvParallel||0);if(!count||!mp||!series||series*strings!==s.panels||count*mp>12000)return toast('Completa cantidad, MPPT por unidad, serie y strings de acuerdo a los paneles.');if(s.pvAssignments?.length&&!confirm('¿Sustituir la asignación manual actual?'))return;s.pvAssignments=[];let base=Math.floor(strings/count),extra=strings%count;for(let i=0;i<count;i++){let st=base+(i<extra?1:0),q=Math.floor(st/mp),r=st%mp;for(let j=0;j<mp;j++){let strings=q+(j<r?1:0);if(strings)s.pvAssignments.push({unit:i+1,mppt:j+1,series,strings})}}assignRefresh(calc,true)}
function setAssignment(i,k,v,calc){let s=calc?calcSite:site();if(!s.pvAssignments[i])return;s.pvAssignments[i][k]=v35Number(v);assignRefresh(calc)}
function addAssignment(calc){let s=calc?calcSite:site();(s.pvAssignments??=[]).push({unit:1,mppt:1,series:s.pvSeries||1,strings:1});assignRefresh(calc,true)}
function removeAssignment(i,calc){let s=calc?calcSite:site();s.pvAssignments.splice(i,1);assignRefresh(calc,true)}
function clearAssignments(calc){let s=calc?calcSite:site();if(s.pvAssignments?.length&&!confirm('¿Volver al reparto automático? Se elimina la asignación individual guardada.'))return;s.pvAssignments=[];assignRefresh(calc,true)}

