if(!validKind||!v||!ib||!l||!a||!p||!Number.isInteger(p)||!rho||temp===null||temp< -40||temp>250||!pf||pf>1||x===null||x<0)pending.push('Faltan datos válidos de circuito, temperatura, PF o reactancia.');
