let max=pos('dropMax');if(!max)pending.push('Objetivo de caída pendiente.');else if(drop!==null&&drop>max+1e-9)issues.push('Caída de tensión superior al objetivo.');
let fs=['factorTemp','factorGroup','factorOther'].map(n);if(pos('izRef')&&p&&Number.isInteger(p)&&fs.every(f=>f!==null&&f>0&&f<=1))iz=pos('izRef')*p*fs.reduce((a,b)=>a*b,1);else pending.push('Ampacidad de referencia y factores (0 < factor ≤ 1) pendientes.');
let br=pos('breakerA'),i2=pos('tripA');if(!br||!i2)pending.push('In e I2 de ficha pendientes.');if(ib&&br&&ib>br)issues.push('Ib superior a In.');if(br&&i2&&i2<br)issues.push('I2 inferior a In; revisar datos de ficha.');if(iz!==null&&br&&br>iz)issues.push('In superior a ampacidad corregida Iz.');if(iz!==null&&i2&&i2>1.45*iz)issues.push('I2 superior a 1,45 × Iz (criterio IEC de sobrecarga; verificar aplicabilidad).');if(iz!==null&&ib&&ib>iz)issues.push('Ib superior a Iz.');
if(!pos('breakerV')||!v||!['DC','AC'].includes(c.breakerKind))pending.push('Tensión y tipo AC/DC de protección pendientes.');else {if(pos('breakerV')<v)issues.push('Tensión asignada inferior a tensión declarada.');if(c.breakerKind!==(ac?'AC':'DC'))issues.push('Protección AC/DC incompatible.');}
