function circuitRemove(id){if(!confirm('¿Eliminar esta comprobación de circuito?'))return;site().designCircuits=site().designCircuits.filter(c=>c.id!==id);touch();render()}
function circuitResult(c){let r=circuitCheck(c);return `<p>Caída: <b>${r.drop===null?'Pendiente':fmt(r.drop,3)+' %'}</b> · Iz corregida: <b>${r.iz===null?'Pendiente':fmt(r.iz,2)+' A'}</b></p>${r.issues.map(v=>`<p class="warn">${E(v)}</p>`).join('')}${r.pending.map(v=>`<p class="muted">${E(v)}</p>`).join('')}${!r.issues.length&&!r.pending.length?'<p>Comprobaciones numéricas declaradas sin discrepancia. No certifica la instalación.</p>':''}`}
function circuitsPanel(s){return panel('Circuitos, conductores y protecciones',`<p class="notice">Registra cada circuito real a partir del unifilar. La ampacidad base y sus factores se toman de la ficha o tabla aplicable; no se inventan. Para DC, introduce la tensión máxima de diseño y comprueba polaridad y corte DC según fabricante. Para AC, tensión L–L en trifásico o del circuito en monofásico. Paralelos requieren reparto uniforme y autorización. Si activas el despiece, indica las repeticiones y el total de conductores de potencia por circuito (sin PE). Elige la partida genérica que realmente sustituye; no se elimina ninguna automáticamente por coincidencia de nombre.</p>${B('Agregar circuito','newCircuit()')}${(s.designCircuits||[]).map(c=>`<details open><summary>${E(c.name)}</summary>${circuitCatalogControls(c)}<div class="fields">${circuitFields.map(([k,label,t])=>{let v=c[k]??'',action=`circuitEdit(${arg(c.id)},'${k}',this.value)`;return `<label class="field">${E(label)}${Array.isArray(t)?`<select onchange="${action}">${t.map(x=>`<option ${x===v?'selected':''}>${E(x)}</option>`).join('')}</select>`:`<input type="${t==='text'?'text':'number'}" step="any" value="${E(v)}" oninput="${action}">`}</label>`}).join('')}</div><div id="circuit-${E(c.id)}">${circuitResult(c)}</div>${B('Eliminar circuito',`circuitRemove(${arg(c.id)})`,'danger small')}</details>`).join('')}<p class="warn">Cálculo aproximado con resistencia DC a temperatura declarada, reactancia por conductor y corriente equilibrada. Verificar resistencia AC real, corrientes armónicas, neutro, PE, energía pasante, curvas y desconexión automática antes de comprar o instalar.</p>`)}
function mountingCheck(s){let n=k=>v35Number(s[k]),panels=n('panels'),per=n('panelsPerRow'),w=n('panelWidth'),h=n('panelLength'),gap=n('mountModuleGap'),rowGap=n('rowGap'),path=n('pathway'),tilt=n('mountTilt'),rw=n('roofWidth'),rl=n('roofLength');let pending=[],issues=[],layout=null,bom=null;
if(!s.modules.includes('Fotovoltaica'))return {layout,pending,issues,bom};if(!(panels>0&&Number.isInteger(panels)&&per>0&&Number.isInteger(per)&&per<=panels&&w>0&&h>0&&gap>=0&&gap!==null&&rowGap>=0&&rowGap!==null&&path>=0&&path!==null&&tilt>=0&&tilt!==null&&tilt<=90&&['Vertical','Horizontal'].includes(s.mountOrientation)))pending.push('Faltan geometría, orientación o separaciones del montaje.');else{let along=s.mountOrientation==='Horizontal'?h:w,across=s.mountOrientation==='Horizontal'?w:h,rows=Math.ceil(panels/per),width=per*along+(per-1)*gap+2*path,depth=rows*across*Math.cos(tilt*Math.PI/180)+(rows-1)*rowGap+2*path;layout={rows,width,depth,area:width*depth};if(!(rw>0&&rl>0))pending.push('Dimensiones útiles de cubierta pendientes.');else if(!((width<=rw&&depth<=rl)||(width<=rl&&depth<=rw)))issues.push('La distribución rectangular no cabe en las dimensiones declaradas.');}
if(!s.anchorPlan||!s.windData||!String(s.mountReview??'').trim())pending.push('Cálculo de viento, soporte, anclajes y revisión de cubierta pendientes.');if(s.mountSystem==='Riel continuo con grapa compartida'){let rails=n('mountRailsPerRow'),end=n('mountRailEnd');if(layout&&Number.isInteger(rails)&&rails>0&&end!==null&&end>=0){let along=s.mountOrientation==='Horizontal'?h:w,count=layout.rows,railLength=(panels*along+(panels-count)*gap+2*count*end)*rails;bom={rails:Math.round(railLength*100)/100,midClamp:(panels-count)*rails,endClamp:2*count*rails};}else pending.push('Número de rieles y extensión de extremos de riel pendientes.')}return {layout,pending,issues,bom};}
function mountingResult(s){let r=mountingCheck(s),l=r.layout;return `${l?`<p>Filas: ${l.rows} · Envolvente rectangular: ${fmt(l.width,2)} × ${fmt(l.depth,2)} m · ${fmt(l.area,2)} m².</p>`:''}${r.bom?`<p>Despiece geométrico: ${fmt(r.bom.rails,2)} m de riel lineal; ${r.bom.midClamp} grapas intermedias y ${r.bom.endClamp} finales. Se incorpora al inventario detallado.</p>`:''}${r.issues.map(x=>`<p class="warn">${E(x)}</p>`).join('')}${r.pending.map(x=>`<p class="muted">${E(x)}</p>`).join('')}<p>Geometría preliminar sin obstáculos ni verificación de sombras, cargas, bordes, u otros retranqueos. La cantidad de anclajes y su resistencia requieren proyecto estructural.</p>`}
function mountingPanel(s){return s.modules.includes('Fotovoltaica')?panel('Montaje y geometría de cubierta',formDesign(s,[['mountOrientation','Orientación del módulo','Orientación en la fila.',['Por confirmar','Vertical','Horizontal']],['mountModuleGap','Separación entre módulos (m)','De fabricante; no incluye calles.'],['mountTilt','Inclinación respecto a horizontal (°)','Ej. 10 · Supone cubierta horizontal.'],['mountSystem','Sistema de montaje','Seleccionar solo si lo confirma el fabricante.',['Por confirmar','Riel continuo con grapa compartida','Otro sistema']],['mountRailsPerRow','Rieles por fila (ud)','De plano y sistema elegido.'],['mountRailEnd','Extensión de riel en cada extremo (m)','De manual de montaje.'],['mountReview','Referencia de revisión estructural','Plano, viento, capacidad de cubierta y anclajes.','text']])+`<div id="mountingResult">${mountingResult(s)}</div>`):''}


let draftKey=null,draftQueue=Promise.resolve(),activityAt=0,locking=false;
async function setupDraftKey(){if(!crypto.subtle)throw Error('Se requiere navegador con cifrado seguro (localhost)');let r=await api('/api/draft-key'),bytes=Uint8Array.from(r.key.match(/../g),v=>parseInt(v,16));draftKey=await crypto.subtle.importKey('raw',bytes,'AES-GCM',false,['encrypt','decrypt']);bytes.fill(0)}
async function writeDraft(value){if(!me||!db||!draftKey)throw Error('No hay clave de borrador autenticada');let username=me.username,key=draftKey;let job=draftQueue.catch(()=>{}).then(async()=>{if(value===null)return putStore('v35draft:'+username,null);let iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode(username)},key,new TextEncoder().encode(JSON.stringify(value)));return putStore('v35draft:'+username,{encrypted:1,iv,cipher})});draftQueue=job;return job}
async function readDraft(){let raw=await getStore('v35draft:'+me.username);if(!raw)return null;if(raw.encrypted===1){let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:raw.iv,additionalData:new TextEncoder().encode(me.username)},draftKey,raw.cipher);return JSON.parse(new TextDecoder().decode(plain))}if(raw.state&&raw.base){await writeDraft(raw);return raw}throw Error('Formato de borrador desconocido; no se ha sobrescrito')}
function startActivity(){for(let name of ['pointerdown','keydown','touchstart'])document.addEventListener(name,()=>{if(!me||locking||logoutBusy||Date.now()-activityAt<60000)return;activityAt=Date.now();api('/api/activity',{method:'POST',body:'{}'}).catch(e=>{if(e.code===401)lockExpired()})},{passive:true})}
async function lockExpired(){if(locking||!me)return;locking=true;clearTimeout(saveTimer);let saved=!dirty;if(dirty&&db){try{await writeDraft({state:copy(state),base:copy(base)});saved=true}catch(e){window.addEventListener('beforeunload',warnUnsavedLock);}}if(saved){state={companies:[],projects:[],library:[],templates:[]};base={};pid=sid=companyId=null;calcSite=emptySite('Calculadora');dirty=false;}me=null;draftKey=null;collision=false;$('dialog').close();$('dialog').innerHTML='';login();$('loginError').textContent=saved?'Sesión cerrada o vencida. Vuelve a autenticarte.':'Sesión cerrada. No se pudo guardar el borrador. No cierres esta pestaña; solicita asistencia para recuperar los cambios en memoria.';if(!saved)$('loginForm').onsubmit=e=>{e.preventDefault();$('loginError').textContent='Cambios en memoria no respaldados. No recargues. Solicita asistencia.';};locking=false}
function warnUnsavedLock(e){e.preventDefault();e.returnValue='';}

// Logistics is per purchase quantity, not installed quantity. Unknown values stay pending.
function logisticsTotals(s){let rows=inventory(s),n=k=>v35Number(k),out={rows:rows.length,weight:0,cbm:0,pendingWeight:[],pendingCBM:[]};for(let m of rows){let q=n(m.qty),w=n(m.weightKg),v=n(m.cbm);if(q===0)continue;if(q===null||q<0||w===null||w<0)out.pendingWeight.push(m.name);else out.weight+=q*w;if(q===null||q<0||v===null||v<0)out.pendingCBM.push(m.name);else out.cbm+=q*v;}return out}
function logisticsSummary(s){let l=logisticsTotals(s);return `<div class="grid">${metric(fmt(l.weight,2)+' kg','Peso bruto conocido'+(l.pendingWeight.length?' · parcial':''))}${metric(fmt(l.cbm,3)+' m³','Volumen embalado conocido'+(l.pendingCBM.length?' · parcial':''))}${metric(l.pendingWeight.length+' / '+l.pendingCBM.length,'Partidas pendientes de peso / CBM')}</div>${!l.rows?'<p class="muted">Sin partidas de compra.</p>':''}${l.pendingWeight.length||l.pendingCBM.length?'<p class="warn">Totales incompletos: no calcular transporte definitivo sin completar peso y volumen.</p>':''}<p class="muted">Valores por unidad embalada × cantidad de compra. Confirmar si el proveedor consolida cajas o pallets; no sumar embalajes dos veces.</p>`}
function salePublicSpec(m){return [m.brand,m.model,m.power?'Potencia/capacidad: '+m.power:'',m.voltage?'Tensión: '+m.voltage+' V':'',m.amps?'Corriente: '+m.amps+' A':'',m.poles?'Polos: '+m.poles:'',m.currentType?'Tipo: '+m.currentType:'',m.breaking?'Corte: '+m.breaking+' kA':'',m.section?'Sección: '+m.section+' mm²':''].filter(Boolean).join(' · ')}
function offerPriceTotal(o){return Math.round(o.rows.reduce((n,r)=>n+Math.round(Number(r.qty)*Number(r.price)*100),0))/100}
function duplicateOffer(i){let s=site(),old=s.commercialOffers?.[i];if(!old)return;let o=copy(old);o.id=uid();o.parentOffer=old.id||null;o.name=old.name+' · revisión';o.date=now();o.status='Borrador';o.statusHistory=[];delete o.issuedAt;o.validUntil='';o.brand=copy(publicIdentity());s.commercialOffers.push(o);touch();render()}
function editOffer(i){let s=site(),o=s.commercialOffers?.[i];if(!o||(o.status!=='Borrador'||o.issuedAt))return toast('Una oferta emitida permanece intacta. Crea una revisión.');modal('Editar oferta borrador',mfield('Nombre','name',o.name,'text',true)+mfield('Validez hasta','validUntil',o.validUntil||'','date')+mfield('Condiciones de pago, garantía, plazo y alcance','terms',o.terms,'text',true)+`<div class="scroll"><table><tr><th>Material y especificaciones</th><th>Cantidad fija</th><th>Venta unitaria ${E(o.currency||'USD')}</th></tr>${o.rows.map((r,j)=>`<tr><td>${E(r.name)}<small>${E(r.spec||'')}</small></td><td>${E(r.qty)} ${E(r.unit)}</td><td><input name="price${j}" type="number" min="0" step="0.01" value="${E(r.price)}" required></td></tr>`).join('')}</table></div>`,form=>{let values=o.rows.map((r,j)=>v35Number(form.get('price'+j)));if(values.some(v=>v===null||v<0))return toast('Precios inválidos'),false;o.name=form.get('name');o.validUntil=form.get('validUntil');o.terms=form.get('terms');o.rows.forEach((r,j)=>r.price=values[j]);touch();render()})}


function safeHttps(url){try{return new URL(url).protocol==='https:'}catch(e){return false}}
function equipmentSampleSummary(){let refs=state.library.filter(m=>m.kind==='consumer'&&m.sourceType?.includes('Referencia documental')),groups={};for(let m of refs){let key=(m.family||'Otra')+(m.subcategory?' / '+m.subcategory:m.family==='Refrigeración'?' / Sin subcategoría registrada':'');(groups[key]??=[]).push(m);}let positive=(ms,k)=>ms.map(m=>v35Number(m[k])).filter(n=>n!==null&&n>0).sort((a,b)=>a-b),median=a=>{let j=Math.floor(a.length/2);return !a.length?null:a.length%2?a[j]:(a[j-1]+a[j])/2},cell=n=>n===null?'—':fmt(n,3);return `<details><summary>Resumen de referencias documentales (${refs.length})</summary><p class="muted">Estudio doméstico: ${domesticStudy(refs).count} fichas únicas con máximo publicado frente a objetivo de 100 (${domesticStudy(refs).hz60} con 60 Hz declarado); las fichas importadas pendientes de revisión y las posibles variantes excluidas no cuentan para el objetivo doméstico de máximos. Muestra de conveniencia, no representativa del mercado. Las potencias máximas publicadas no son picos de arranque ni potencia media. No se extrapolan los equipos de bebidas o vinos a refrigeradores domésticos. Los resultados no se aplican automáticamente al diseño.</p><div class="scroll"><table><tr><th>Familia y subcategoría</th><th>Referencias</th><th>Nominales disponibles</th><th>Mediana nominal kW</th><th>Máximo nominal kW</th><th>Máximos documentados</th><th>Mediana de máximos kW</th><th>Mayor máximo kW</th><th>Sin máximo</th></tr>${Object.entries(groups).map(([k,ms])=>{let a=positive(ms,'nominal'),b=positive(ms,'max');return `<tr><td>${E(k)}</td><td>${ms.length}</td><td>${a.length}</td><td>${cell(median(a))}</td><td>${cell(a.length?a.at(-1):null)}</td><td>${b.length}</td><td>${cell(median(b))}</td><td>${cell(b.length?b.at(-1):null)}</td><td>${ms.length-b.length}</td></tr>`}).join('')}</table></div></details>`}
function supplyReviewIssues(s){return (s.loads||[]).filter(r=>typeof r.supplyRestriction==='string'&&r.supplyRestriction.trim()).map(r=>(r.name||'Equipo')+': '+r.supplyRestriction+' No constituye confirmación de compatibilidad.');}
function loadDesignAudit(s){let rows=s.loads||[],missing=rows.filter(r=>!['Medido','Verificado por especialista'].includes(r.dataStatus)),pfMissing=rows.filter(r=>!(r.pf>0&&r.pf<=1)),frequencyMismatch=rows.filter(r=>Number(r.frequencyHz)>0&&Number(s.frequency)>0&&Number(r.frequencyHz)!==Number(s.frequency)),peakRows=rows.filter(r=>r.startA>0||r.startKW>0);return `<p>${rows.length} equipos · ${missing.length} sin validación de campo · ${pfMissing.length} sin factor de potencia declarado.</p>${supplyReviewIssues(s).map(v=>`<p class="warn">${E(v)}</p>`).join('')}${frequencyMismatch.map(r=>`<p class="warn">${E(r.name)}: ficha de ${E(r.frequencyHz)} Hz, sede ${E(s.frequency)} Hz. No usar como confirmación de compatibilidad.</p>`).join('')}${peakRows.length?`<div class="scroll"><table><tr><th>Equipo</th><th>Arranque declarado por unidad</th><th>Origen</th></tr>${peakRows.map(r=>`<tr><td>${E(r.name)}</td><td>${r.startA>0?fmt(r.startA,2)+' A':''}${r.startKW>0?' / '+fmt(r.startKW,2)+' kW':''}</td><td>${E(r.dataStatus||'Pendiente')}</td></tr>`).join('')}</table></div>`:''}<p class="warn">Los arranques no se suman automáticamente: comprobar duración, secuencia, PF de arranque, selectividad y sobrecarga admisible del inversor. La potencia elegida en la tabla de cargas sigue siendo la entrada del balance horario.</p>`}
function loadSourceDialog(i){let r=site().loads[i];if(!r)return;modal('Datos del equipo en esta instalación',`<p>La ficha de proyecto es independiente de la biblioteca. Introduce datos del equipo real y el criterio elegido para la potencia de simulación.</p><div class="fields">${modalSelect('Estado','dataStatus',r.dataStatus||'Pendiente',['Pendiente','Supuesto preliminar','Referencia documental','Medido','Verificado por especialista'])}${modalSelect('Tipo de potencia adoptada','designPowerType',r.designPowerType||'No declarado',['No declarado','Nominal','Normal','Máxima declarada','Medición representativa','Estimación conservadora'])}${mfield('Potencia adoptada kW','kw',r.kw,'number',true)}${mfield('Factor de potencia','pf',r.pf??'','number')}${mfield('Tensión V','voltage',r.voltage??'','number')}${mfield('Frecuencia exclusiva de ficha (Hz)','frequencyHz',r.frequencyHz??'','number')}${mfield('Rango eléctrico de la ficha','voltageRange',r.voltageRange??'','text')}${mfield('Corriente de arranque A','startA',r.startA??'','number')}${mfield('Potencia de arranque kW','startKW',r.startKW??'','number')}${mfield('Fuente y fecha de medida','source',r.source??'','text')}${mfield('Ficha o referencia','datasheet',r.datasheet??'','text')}${mfield('Restricciones de alimentación OEM','supplyRestriction',r.supplyRestriction??'','text')}<label class="field">Tablero AC del equipo<select name="acGroupId"><option value="">Sin asignar</option>${(site().acGroups||[]).map(g=>`<option value="${E(g.id)}" ${g.id===r.acGroupId?'selected':''}>${E(g.name)}</option>`).join('')}</select><small>Se usa al activar reparto de equipos por tablero.</small></label></div><h3>Días de funcionamiento</h3><label class="check"><input type="checkbox" name="customDays" ${Array.isArray(r.activeDays)?'checked':''}> Usar días propios (si no, días laborables de la sede)</label><div class="fields">${weekNames.map((d,i)=>`<label class="check"><input name="equipmentDay" type="checkbox" value="${i}" ${(Array.isArray(r.activeDays)?r.activeDays:workSchedule(site())).includes(i)?'checked':''}>${E(d)}</label>`).join('')}</div>`,f=>{let z=Object.fromEntries(f);delete z.customDays;delete z.equipmentDay;z.activeDays=f.has('customDays')?f.getAll('equipmentDay').map(Number):null;for(let k of ['kw','pf','voltage','frequencyHz','startA','startKW']){z[k]=v35Number(z[k]);if(z[k]!==null&&z[k]<0)return toast('Valores negativos no válidos'),false}if(z.kw===null||(z.pf!==null&&(z.pf<=0||z.pf>1)))return toast('Revisa potencia o PF'),false;if(['Medido','Verificado por especialista'].includes(z.dataStatus)&&!z.source.trim())return toast('Indica fuente o medición'),false;Object.assign(r,z);touch();render()})}


// Portable private backups: passphrase key never persisted; old JSON imports remain supported.
const backupKdfRounds=600000,backupLimit=200*1024*1024;
function bytes64(bytes){let out='';for(let i=0;i<bytes.length;i+=24576)out+=btoa(String.fromCharCode(...bytes.subarray(i,i+24576)));return out}
function from64(s){if(typeof s!=='string'||s.length>Math.ceil((backupLimit+16)/3)*4||s.length%4!==0||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Datos cifrados inválidos');let raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
async function backupKey(password,salt){if(!crypto?.subtle)throw Error('El navegador no ofrece cifrado seguro. Inicia el servidor local.');if(typeof password!=='string'||password.length<12||password.length>1024)throw Error('Contraseña de 12 a 1024 caracteres');let seed=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:backupKdfRounds,hash:'SHA-256'},seed,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptBackup(data,password){let bytes=new TextEncoder().encode(JSON.stringify(data));if(bytes.length>backupLimit)throw Error('Respaldo demasiado grande para un único archivo cifrado. Divide por proyectos.');let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await backupKey(password,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('EVStudioEncryptedBackup:1')},key,bytes);return {format:'EVStudioEncryptedBackup',version:1,algorithm:'AES-256-GCM',kdf:'PBKDF2-SHA256',rounds:backupKdfRounds,salt:bytes64(salt),iv:bytes64(iv),cipher:bytes64(new Uint8Array(cipher))}}
async function decryptBackup(raw,password){if(raw.format!=='EVStudioEncryptedBackup'||raw.version!==1||raw.algorithm!=='AES-256-GCM'||raw.kdf!=='PBKDF2-SHA256'||raw.rounds!==backupKdfRounds)throw Error('Formato de respaldo cifrado no compatible');let salt=from64(raw.salt),iv=from64(raw.iv),cipher=from64(raw.cipher);if(salt.length!==16||iv.length!==12||cipher.length<16)throw Error('Cabecera no válida');let key=await backupKey(password,salt);try{let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('EVStudioEncryptedBackup:1')},key,cipher);return JSON.parse(new TextDecoder().decode(plain))}catch(e){throw Error('Contraseña incorrecta o archivo dañado')}}
function backupPasswordDialog(id=null){let p=id?state.projects.find(q=>q.id===id):null;if(id&&!p)return;modal('Crear respaldo privado cifrado',`<p>Se cifra todo el contenido del respaldo, incluidas fotografías y documentos. Guarda la contraseña separadamente; no puede recuperarse si se pierde. El programa no la envía a la red.</p><label class="field">Contraseña<input name="password" type="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><label class="field">Repetir contraseña<input name="repeat" type="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label>`,async f=>{if(f.get('password')!==f.get('repeat')){toast('Las contraseñas no coinciden');return false}try{let data=p?{kind:'project',companies:[company(p.companyId)].filter(Boolean),projects:[p],library:[],templates:[]}:{kind:'workspace',...state};let payload={schema:3,release:'3.5-desarrollo',exported:now(),...copy(data)};let bytes=new TextEncoder().encode(JSON.stringify(payload)).length;if(bytes>backupLimit)throw Error('Respaldo cifrado superior a 200 MiB de datos. Exporta un JSON privado o divide por proyectos.');if(!confirmLargeBackup(bytes,'cifrar y descargar el respaldo'))return false;let encrypted=await encryptBackup(payload,f.get('password'));download('EV_'+(p?slug(p.name):'respaldo_general')+'_privado.evbackup',JSON.stringify(encrypted),'application/json');toast('Respaldo cifrado generado');return true}catch(e){toast(e.message);return false}},'Cifrar y descargar')}


const designCatalogMap={
 'Módulo fotovoltaico':{required:'moduleWatts',target:'watts',map:{moduleWatts:'watts',voc:'pvVoc',isc:'pvIsc',vmp:'pvVmp',imp:'pvImp',vocCoeff:'pvVocCoeff',vmpCoeff:'pvVmpCoeff',powerCoeff:'pvGamma',noct:'pvNoct',lengthM:'panelLength',widthM:'panelWidth'}},
 'Inversor / PCS':{required:'ratedACkw',target:'unitInverter',map:{ratedACkw:'unitInverter',mpptCount:'mpptPerInverter',maxDc:'pvMaxVoc',maxInputDCkw:'dcPerInverter',mpptMinV:'pvMpptMin',mpptMaxV:'pvMpptMax',mpptOperatingA:'pvMpptA',mpptShortCircuitA:'pvMpptIsc'}},
 'Batería / BESS':{required:'ratedKwh',target:'unitBattery',map:{ratedKwh:'unitBattery',minBatteryV:'batteryMinV',maxBatteryV:'batteryMaxV'}}};
function catalogDesignValues(m){let out={},map=designCatalogMap[m.equipmentType]?.map||{};for(let [src,dst] of Object.entries(map)){let v=v35Number(m[src]);if(v===null||(!['pvVocCoeff','pvVmpCoeff','pvGamma'].includes(dst)&&v<=0)||(['pvVocCoeff','pvVmpCoeff','pvGamma'].includes(dst)&&(v>0||v< -2))||(dst==='mpptPerInverter'&&!Number.isInteger(v)))v=null;out[dst]=v;}return out}
function catalogRefMatches(s,ref){return Object.entries(ref.values||{}).every(([k,v])=>v===null?(s[k]==null||s[k]===''||s[k]===0):Number(s[k])===Number(v))}
function provenanceLabel(s,k){let val=s[k];if(val===null||val===undefined||val==='')return 'Estado: pendiente / valor de inicio si aplica';let meta=s.dataSources?.[k];if(meta&&JSON.stringify(meta.value)===JSON.stringify(val))return 'Estado: '+meta.status+(meta.source?' · '+meta.source:'');for(let ref of Object.values(s.catalogEnergyRefs||{})){if(ref.values&&Object.hasOwn(ref.values,k)&&JSON.stringify(ref.values[k])===JSON.stringify(val))return 'Estado: referencia de catálogo · '+ref.name;}return 'Estado: dato introducido o supuesto inicial, sin validar'}
function catalogDesignPanel(s,calc){let types=Object.keys(designCatalogMap);return panel('Seleccionar equipos de biblioteca',`<p>Aplica una ficha al diseño de ${calc?'la calculadora':'esta instalación'}. Los límites que la nueva referencia no define quedan pendientes, no se heredan de otro modelo. Las especificaciones manuales anteriores de esa partida se archivan; la referencia nueva necesita su propio costo. No se modifica la biblioteca.</p>${types.map(t=>`<div class="row between"><span>${E(t)} · ${E(s.catalogEnergyRefs?.[t]?(s.catalogEnergyRefs[t].name+(catalogRefMatches(s,s.catalogEnergyRefs[t])?'':' · Datos modificados')):'Selección manual')}</span>${B('Seleccionar ficha',`designCatalogDialog(${arg(t)},${calc})`)}</div>`).join('')}`)}
function designCatalogDialog(type,calc){let s=calc?calcSite:site(),entries=state.library.filter(m=>m.kind!=='consumer'&&m.equipmentType===type);if(!entries.length)return toast('No hay fichas de este tipo. Crea o edita una referencia en Biblioteca técnica / Materiales.');modal('Seleccionar '+type,`<p>Selecciona una ficha técnica. Las potencias nominales deben estar en su campo específico, sin texto ni unidades mezcladas.</p><input id="designRefSearch" placeholder="Buscar modelo, marca o nombre" oninput="designCatalogResults(${arg(type)},${calc},this.value)"><div id="designRefResults"></div>`,()=>false,'Seleccionar');designCatalogResults(type,calc,'');$('modalForm').querySelector('button[type=submit]').style.display='none'}
function designCatalogResults(type,calc,q){let entries=state.library.filter(m=>m.kind!=='consumer'&&m.equipmentType===type&&normSearch([m.name,m.brand,m.model].join(' ')).includes(normSearch(q)));$('designRefResults').innerHTML=entries.map(m=>`<div class="row between"><span>${E([m.name,m.brand,m.model].filter(Boolean).join(' · '))} · ${m.verified?'Referida como verificada':'Ficha no verificada'}</span>${B('Revisar y aplicar',`designCatalogConfirm(${arg(m.id)},${calc})`)}</div>`).join('')||empty('Sin coincidencias')}
function designCatalogConfirm(id,calc){let m=state.library.find(x=>x.id===id),s=calc?calcSite:site();if(!m||!designCatalogMap[m.equipmentType])return;let d=catalogDesignValues(m),t=m.equipmentType,qty=t==='Inversor / PCS'?(s.inverterCount||1):t==='Batería / BESS'?(s.battery&&s.unitBattery?Math.ceil(s.battery/s.unitBattery):1):s.panels||1;if(!d[designCatalogMap[t].target])return toast('Completa la potencia o capacidad nominal específica de esta ficha antes de aplicarla.');$('dialog').close();modal('Confirmar selección de diseño',`<p>${E(m.name)} · ${E(m.brand||'')} ${E(m.model||'')} · ${E(m.datasheet||'Ficha pendiente')}. Este cambio puede modificar el inventario, la simulación y las instalaciones vinculadas.</p>${mfield('Cantidad de unidades','qty',qty,'number',true)}<div class="scroll"><table><tr><th>Parámetro</th><th>Actual</th><th>Ficha nueva</th></tr>${Object.entries(d).map(([k,v])=>`<tr><td>${E(designLabels[k]||k)}</td><td>${E(s[k]??'Pendiente')}</td><td>${E(v??'Pendiente')}</td></tr>`).join('')}</table></div>${t==='Batería / BESS'?'<p class="warn">No se presupone que las potencias ni las tensiones de varios módulos se puedan sumar o aplicar al banco. Debes confirmar BMS, configuración y límites globales.</p>':''}<label class="check"><input name="confirm" type="checkbox" required> He revisado las diferencias; sustituir la ficha anterior.</label>`,f=>{let n=v35Number(f.get('qty'));if(!Number.isInteger(n)||n<1||n>12000)return toast('Cantidad entera entre 1 y 12.000'),false;applyCatalogDesign(s,m,n);if(calc)refreshDerived();else touch();render()},'Aplicar ficha')}
const designLabels={watts:'Potencia nominal W',pvVoc:'Voc módulo V',pvIsc:'Isc módulo A',pvVmp:'Vmp módulo V',pvImp:'Imp módulo A',pvVocCoeff:'Coeficiente Voc %/°C',pvVmpCoeff:'Coeficiente Vmp %/°C',pvGamma:'Coeficiente potencia %/°C',pvNoct:'NOCT °C',panelLength:'Largo módulo m',panelWidth:'Ancho módulo m',unitInverter:'Potencia AC por unidad kW',mpptPerInverter:'MPPT/unidad',pvMaxVoc:'Máxima tensión DC V',dcPerInverter:'Límite FV kW/unidad',pvMpptMin:'MPPT mín. V',pvMpptMax:'MPPT máx. V',pvMpptA:'Corriente MPPT A',pvMpptIsc:'Isc MPPT A',unitBattery:'Capacidad por módulo kWh',batteryMinV:'Tensión mínima V',batteryMaxV:'Tensión máxima V'};
function applyCatalogDesign(s,m,qty){let t=m.equipmentType,values=catalogDesignValues(m);if(!values[designCatalogMap[t]?.target]||!Number.isInteger(qty)||qty<1)throw Error('Ficha o cantidad inválida');if(t==='Módulo fotovoltaico'){s.panels=qty;s.modules=[...new Set([...s.modules,'Fotovoltaica'])];if(s.pvAssignments?.length)s.pvAssignments=[];s.pvSeries=0;s.pvParallel=0;s.strings=0;s.pvMode='advanced';}else if(t==='Inversor / PCS'){s.inverterCount=qty;s.inverter=qty*values.unitInverter;s.inverterModel=[m.brand,m.model,m.name].filter(Boolean).join(' · ');s.designSource='Modelo de catálogo';s.pvMppt=values.mpptPerInverter?qty*values.mpptPerInverter:0;s.mppt=s.pvMppt;s.pvDcMax=values.dcPerInverter?qty*values.dcPerInverter:null;s.pvAssignments=[];s.factoryConfirmation='';s.acConnection='Por confirmar';s.batteryConnection='Por confirmar';}else if(t==='Batería / BESS'){s.battery=qty*values.unitBattery;s.modules=[...new Set([...s.modules,'Baterías'])];if(qty!==1){values.batteryMinV=null;values.batteryMaxV=null;s.bmsChargeKW=null;s.bmsDischargeKW=null;}else {s.bmsChargeKW=v35Number(m.maxCharge);s.bmsDischargeKW=v35Number(m.maxDischarge)}s.bmsProtocol=m.protocol||'';s.batteryConnection='Por confirmar';s.factoryConfirmation='';}Object.assign(s,values);let autoKey={'Módulo fotovoltaico':'pv','Inversor / PCS':'inv','Batería / BESS':'bess'}[t];if(s.overrides?.[autoKey]){let old=copy(s.overrides[autoKey]);(s.previousCatalogOverrides??=[]).push({key:autoKey,date:now(),data:old});delete s.overrides[autoKey]}(s.catalogEnergyRefs??={})[t]={catalogId:m.id,brand:m.brand||'',model:m.model||'',name:[m.brand,m.model,m.name].filter(Boolean).join(' · '),source:m.datasheet||'',date:now(),verified:!!m.verified,values:copy(values)};for(let k of Object.keys(values))if(s.dataSources)delete s.dataSources[k];}
function dataSourcesDialog(calc=false,surveyOnly=false){let s=calc?calcSite:site(),keys=[...new Set(surveyOnly?V35_SURVEY_KEYS:[...V35_ENGINEERING_KEYS.filter(k=>!['designCircuits','catalogEnergyRefs'].includes(k)),...Object.keys(designLabels),'inverterCount','pvSeries','pvParallel','pvCold','batterySOH','bmsChargeKW','bmsDischargeKW'])].filter(k=>typeof s[k]!=='object'||s[k]===null);modal('Estado y fuente de datos',`<p>Valores actuales, no edición de cantidades. Los estados se invalidan automáticamente si se cambia el valor.</p><div class="scroll"><table><tr><th>Dato</th><th>Valor actual</th><th>Estado</th><th>Fuente / fecha</th></tr>${keys.map((k,i)=>{let a=s.dataSources?.[k],current=a&&JSON.stringify(a.value)===JSON.stringify(s[k]);return `<tr><td>${E(designLabels[k]||k)}</td><td>${E(s[k]??'Pendiente')}</td><td><select name="status${i}">${['Sin declarar','Pendiente','Supuesto preliminar','Medido','De ficha','Calculado preliminar','Confirmado OEM','Verificado por especialista'].map(v=>`<option ${current&&a.status===v?'selected':''}>${E(v)}</option>`).join('')}</select></td><td><input name="source${i}" value="${E(current?a.source||'':'')}"></td></tr>`}).join('')}</table></div>`,f=>{let records={...(s.dataSources||{})};for(let [i,k] of keys.entries()){let st=f.get('status'+i),src=String(f.get('source'+i)||'').trim();if(['Medido','De ficha','Confirmado OEM','Verificado por especialista'].includes(st)&&(!src||s[k]===null||s[k]===undefined||s[k]===''))return toast('Completa valor y fuente: '+(designLabels[k]||k)),false;if(st==='Sin declarar')delete records[k];else records[k]={value:copy(s[k]??null),status:st,source:src,date:now()}}s.dataSources=records;if(calc)refreshDerived();else touch();render()},'Guardar estados')}

// Supplier quotes are private snapshots. A quote never silently replaces a newer BOM.
function quoteSignature(m){return JSON.stringify([m.name,m.family,m.unit,m.brand,m.model,m.note,m.power,m.voltage,m.amps,m.poles,m.currentType,m.breaking,m.section,m.qty,m.installed,m.spare,m.dataStatus,m.designCatalogId,m.datasheet,m.insulation,m.verified])}
function supplierRowsForQuote(m){return [salePublicSpec(m),m.note,m.datasheet?'Ficha: '+m.datasheet:'',m.dataStatus?'Estado: '+m.dataStatus:'',m.installed!=null?'Instalación: '+m.installed:'',m.spare!=null?'Reserva: '+m.spare:''].filter(Boolean).join(' · ')}
function quoteRows(s){return inventory(s).map((m,i)=>({key:costKey(m,i),name:m.name,unit:m.unit||'',qty:v35Number(m.qty),spec:supplierRowsForQuote(m),ref:[m.brand,m.model].filter(Boolean).join(' / '),signature:quoteSignature(m),price:null,weightKg:null,cbm:null,offeredRef:'',included:false}))}
function quoteCompare(s,q){let current=quoteRows(s),by=new Map(current.map(r=>[r.key,r])),seen=new Set(),issues=[],eligible=[];if(q.currency!=='USD')issues.push('Moneda no USD: convertir explícitamente antes de aplicar.');if(q.validUntil&&q.validUntil<localDateKey())issues.push('Cotización vencida.');for(let r of q.rows||[]){if(seen.has(r.key)){issues.push('Referencia duplicada: '+r.name);continue}seen.add(r.key);let m=by.get(r.key);if(!m||m.signature!==r.signature){issues.push('Partida modificada o retirada: '+r.name);continue}if(m.qty===null||m.qty<0){issues.push('Cantidad sin confirmar: '+r.name);continue}if(r.price===null||v35Number(r.price)===null||r.price<0){issues.push('Precio pendiente: '+r.name);continue}if(r.included&&r.price!==0){issues.push('Partida incluida en kit con precio no cero: '+r.name);continue}if(r.offeredRef&&r.offeredRef!==r.ref){issues.push('Modelo alternativo no validado: '+r.name);continue}if((r.weightKg!=null&&(!Number.isFinite(r.weightKg)||r.weightKg<0))||(r.cbm!=null&&(!Number.isFinite(r.cbm)||r.cbm<0))){issues.push('Datos logísticos inválidos: '+r.name);continue}eligible.push(r)}for(let r of current)if(!seen.has(r.key))issues.push('Partida nueva sin cotizar: '+r.name);return {issues,eligible,total:issues.length?null:Math.round(eligible.reduce((sum,r)=>sum+r.qty*r.price,0)*100)/100}}
function localDateKey(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function quoteLogistics(q){let r={weight:0,cbm:0,pendingWeight:0,pendingCBM:0};for(let m of q.rows||[]){if(m.qty===0)continue;for(let [k,t,p] of [['weightKg','weight','pendingWeight'],['cbm','cbm','pendingCBM']]){let v=v35Number(m[k]),n=v35Number(m.qty);if(v===null||n===null||v<0||n<0)r[p]++;else r[t]+=v*n}}return r}
function quotePanel(s){if(!canSeeFinance())return '';let qs=s.supplierQuotes||[];return panel('Cotizaciones de fábrica · privado',`<p>Crea el registro antes de enviar la solicitud para fijar la lista de materiales, o registra la respuesta contra una lista que hayas comprobado que coincide. Registra una respuesta EXW con referencia, cantidades y ficha del inventario. No se cambian automáticamente los materiales ni los costos. Se exige conciliar todas las partidas antes de aplicar una cotización.</p>${B('Registrar cotización','quoteDialog()')}${qs.map((q,i)=>{let r=quoteCompare(s,q),l=quoteLogistics(q);return `<div class="tile"><b>${E(q.code)} · ${E(q.supplier)}</b><p>${E(q.date)} · ${q.appliedAt?'Aplicada '+E(q.appliedAt):r.issues.length?'Pendiente de conciliación':'Lista para revisión'} · ${r.total===null?'Total pendiente':fmt(r.total,2)+' USD'}</p><p>Logística recibida: ${fmt(l.weight,2)} kg${l.pendingWeight?' (parcial; '+l.pendingWeight+' pendientes)':''} · ${fmt(l.cbm,3)} m³${l.pendingCBM?' (parcial; '+l.pendingCBM+' pendientes)':''}. No sustituye datos técnicos del inventario.</p>${r.issues.slice(0,12).map(a=>`<p class="warn">${E(a)}</p>`).join('')}${r.issues.length>12?'<p>Hay más observaciones.</p>':''}<div class="actions">${!q.appliedAt?B('Editar respuesta',`quoteDialog(${i})`)+B('Aplicar costos',`confirmQuote(${i})`):B('Ver respuesta',`quoteDialog(${i})`)}${B('Solicitud original sin precios',`printQuoteRequest(${i})`)+B('Nueva revisión',`reviseQuote(${i})`)}</div></div>`}).join('')}`)}
function quoteDialog(i=null){if(!canSeeFinance())return;let s=site(),old=i===null?null:s.supplierQuotes?.[i],q=old||{id:uid(),code:'RFQ-'+((s.supplierQuotes||[]).length+1),supplier:'',date:localDateKey(),validUntil:'',currency:'USD',rows:quoteRows(s)};if(!q.rows.length)return toast('No hay materiales para cotizar');let locked=Boolean(q.appliedAt);modal(locked?'Cotización registrada · solo lectura':'Registrar respuesta EXW',`<div class="fields">${mfield('Código / referencia','code',q.code,'text',true)}${mfield('Proveedor','supplier',q.supplier,'text',true)}${mfield('Fecha de oferta','date',q.date,'date',true)}${mfield('Vigencia','validUntil',q.validUntil||'','date')}</div><p>USD · EXW unitario. Peso bruto y CBM son por unidad embalada. Deja en blanco los datos desconocidos. Si el equipo ofrecido difiere, registra la desviación y valida técnicamente antes de actualizar el inventario.</p><div class="scroll"><table><tr><th>Partida / especificación</th><th>Cantidad</th><th>Ref. ofrecida</th><th>EXW USD/u</th><th>kg/u</th><th>m³/u</th><th>Incluida en kit</th></tr>${q.rows.map((r,j)=>`<tr><td>${E(r.name)}<small class="field-help">${E(r.spec)} · ${E(r.ref)}</small></td><td>${E(r.qty??'Pendiente')} ${E(r.unit)}</td><td><input name="ref${j}" value="${E(r.offeredRef||'')}" ${locked?'readonly':''}></td>${['price','weightKg','cbm'].map(k=>`<td><input type="number" min="0" step="any" name="${k}${j}" value="${E(r[k]??'')}" ${locked?'readonly':''}></td>`).join('')}<td><input type="checkbox" name="included${j}" ${r.included?'checked':''} ${locked?'disabled':''}></td></tr>`).join('')}</table></div>`,f=>{if(locked)return;let rows=q.rows.map((r,j)=>({...r,offeredRef:String(f.get('ref'+j)||'').trim(),price:v35Number(f.get('price'+j)),weightKg:v35Number(f.get('weightKg'+j)),cbm:v35Number(f.get('cbm'+j)),included:f.has('included'+j)}));if(rows.some(r=>['price','weightKg','cbm'].some(k=>r[k]!==null&&r[k]<0)))return toast('Revisa los valores negativos'),false;let updated={...q,identity:q.identity||[cname(project()),project().name,s.name].join(' · '),technical:q.technical||technicalText(s),code:String(f.get('code')).trim(),supplier:String(f.get('supplier')).trim(),date:f.get('date'),validUntil:f.get('validUntil'),rows};if(i===null)(s.supplierQuotes??=[]).push(updated);else s.supplierQuotes[i]=updated;touch();render()},locked?'Cerrar':'Guardar respuesta')}
function reviseQuote(i){if(!canSeeFinance())return;let s=site(),q=s.supplierQuotes?.[i];if(!q)return;let old=new Map(q.rows.map(r=>[r.key,r])),rows=quoteRows(s).map(r=>{let p=old.get(r.key);return p?.signature===r.signature?{...r,price:p.price,weightKg:p.weightKg,cbm:p.cbm,offeredRef:p.offeredRef,included:p.included}:r});s.supplierQuotes.push({...copy(q),id:uid(),parentId:q.id,code:q.code+' · revisión',identity:[cname(project()),project().name,s.name].join(' · '),technical:technicalText(s),date:localDateKey(),validUntil:'',rows,appliedAt:null,appliedBy:null});touch();render();quoteDialog(s.supplierQuotes.length-1)}
function applyQuote(s,q){if(!canSeeFinance()||q.appliedAt)throw Error('Cotización no modificable');let r=quoteCompare(s,q);if(r.issues.length||!r.eligible.length)throw Error(r.issues[0]||'Sin partidas');let previous=copy(s.materialCosts||{}),updated={...previous};for(let row of r.eligible){updated[row.key]={...(updated[row.key]||{}),cost:row.price,currency:'USD',quoteId:q.id,quoteSignature:row.signature,weightKg:row.weightKg,cbm:row.cbm}}s.materialCosts=updated;(s.quoteCostHistory??=[]).push({quoteId:q.id,date:now(),previous});if(s.privateFinance)s.privateFinance.confirmed=false;q.appliedAt=now();q.appliedBy=me?.username||'local';return r.total}
function quoteRequestHTML(q){return clientPage('Solicitud de cotización EXW',`<section><h2>${E(q.code)}</h2><p>${E(q.identity||'Instalación')} · ${E(q.date)}</p><p>Solicitud preliminar: completar marca, modelo, EXW USD/u, peso bruto y CBM unitarios embalados, plazo y garantía. No es una orden de compra.</p><details open><summary>Requisitos técnicos conservados al registrar</summary><div style="white-space:pre-wrap">${E(q.technical||'Pendiente de documento técnico')}</div></details><table><tr><th>ID</th><th>Material</th><th>Especificación</th><th>Cantidad solicitada</th><th>EXW USD/u</th><th>kg/u</th><th>m³/u</th></tr>${q.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${E(r.name)}</td><td>${E([r.ref,r.spec].filter(Boolean).join(' · '))}</td><td>${E(r.qty??'Pendiente')} ${E(r.unit)}</td><td>—</td><td>—</td><td>—</td></tr>`).join('')}</table><p>Confirmar accesorios faltantes, compatibilidad, cantidades y desviaciones de las especificaciones. Dentro de kits, identificar partidas incluidas para evitar doble facturación.</p></section>`,false)}
function printQuoteRequest(i){if(!canSeeFinance())return;let q=site().supplierQuotes?.[i];if(!q)return;if(!confirm('Revisa las notas técnicas y especificaciones originales. No se incluyen precios ni costos de la respuesta. ¿Continuar?'))return;openPrintable(quoteRequestHTML(q),false)}
function confirmQuote(i){if(!canSeeFinance())return;let s=site(),q=s.supplierQuotes?.[i];if(!q)return;let r=quoteCompare(s,q);if(r.issues.length)return toast(r.issues[0]);if(!confirm('Aplicar '+fmt(r.total,2)+' USD de costo EXW a '+r.eligible.length+' partidas. Se conservarán los costos anteriores y tendrás que reconfirmar la logística. ¿Continuar?'))return;try{applyQuote(s,q);touch();render()}catch(e){toast(e.message)}}

// Circuit-specific catalog snapshots; unknown values clear old equipment limits.
const circuitCatalogMap={protection:{type:'Protección eléctrica',fields:{amps:'breakerA',ratedVoltageV:'breakerV',poles:'breakerPoles',breaking:'breakKA',i2A:'tripA'}},wire:{type:'Conductor / accesorio',fields:{section:'section',referenceAmpacity:'izRef',reactanceOhmKm:'x'}}};
function circuitRefValues(m,kind){let d=circuitCatalogMap[kind],out={};for(let [a,b] of Object.entries(d.fields)){let n=v35Number(m[a]);out[b]=n!==null&&(a==='reactanceOhmKm'?n>=0:n>0)?n:null}if(kind==='protection'){out.breakerKind=['AC','DC'].includes(m.currentType)?m.currentType:'Por confirmar';if(!out.breakerV)out.breakerV=null;if(out.breakerPoles&&!Number.isInteger(out.breakerPoles))out.breakerPoles=null;}else out.material=['Cobre','Aluminio'].includes(m.conductorMaterial)?m.conductorMaterial:'Por confirmar';return out}
function circuitRefMatches(c,ref){return Object.entries(ref.values||{}).every(([k,v])=>v===null?v35Number(c[k])===null:String(c[k])===String(v))}
function applyCircuitRef(c,m,kind){let d=circuitCatalogMap[kind];if(!d||m.equipmentType!==d.type)throw Error('El tipo de ficha no corresponde al componente');let v=circuitRefValues(m,kind),ref={catalogId:m.id,name:m.name,brand:m.brand||'',model:m.model||'',source:m.datasheet||'',verified:m.verified===true,values:v,date:now()};Object.assign(c,v);(c.catalogRefs??={})[kind]=ref;if(kind==='wire'){c.factorTemp=null;c.factorGroup=null;c.factorOther=null;}return ref}
function circuitRefStatus(c){return Object.entries(c.catalogRefs||{}).map(([kind,r])=>{let match=circuitRefMatches(c,r),complete=Object.values(r.values||{}).every(v=>v!==null&&v!=='Por confirmar');return {kind,ref:r,match,complete}})}
function circuitCatalogDialog(id,kind){let c=site().designCircuits?.find(x=>x.id===id),d=circuitCatalogMap[kind];if(!c||!d)return;let rows=state.library.filter(m=>m.kind!=='consumer'&&m.equipmentType===d.type);if(!rows.length)return toast('Crea la ficha de '+d.type+' en Biblioteca técnica primero.');modal('Seleccionar '+d.type,`<p>El circuito conservará una copia de la ficha. Se borran valores de la referencia anterior que no consten en la nueva; no cambia la biblioteca. La selección no certifica coordinación ni protección.</p><label class="field">Buscar<input id="circuitRefSearch" oninput="filterCircuitReferences(this.value)"></label><div id="circuitRefList">${rows.map(m=>`<label class="check" data-search="${E(normSearch([m.name,m.brand,m.model].join(' ')))}"><input type="radio" name="ref" value="${E(m.id)}" required>${E([m.name,m.brand,m.model].filter(Boolean).join(' · '))} · ${E(m.datasheet||'Sin fuente')}</label>`).join('')}</div>`,f=>{let m=rows.find(x=>x.id===f.get('ref'));if(!m)return false;applyCircuitRef(c,m,kind);touch();render()},'Aplicar ficha')}
function filterCircuitReferences(q){let v=normSearch(q);document.querySelectorAll('#circuitRefList [data-search]').forEach(el=>{el.hidden=!el.dataset.search.includes(v);if(el.hidden)el.querySelector('input').checked=false;})}
function circuitCatalogControls(c){return `<div class="actions">${B('Elegir protección de biblioteca',`circuitCatalogDialog(${arg(c.id)},'protection')`)}${B('Elegir conductor de biblioteca',`circuitCatalogDialog(${arg(c.id)},'wire')`)}</div>${circuitRefStatus(c).map(({ref,match,complete})=>`<p class="${match&&complete&&ref.source?'muted':'warn'}">${E([ref.name,ref.brand,ref.model].filter(Boolean).join(' · '))} · ${match?'Instantánea conservada':'Ficha modificada'} · ${complete?'campos declarados':'ficha incompleta'} · ${E(ref.source||'sin fuente')}</p>`).join('')}`}
function circuitRefPurchase(c,kind){let r=c.catalogRefs?.[kind];if(!r)return {};let match=circuitRefMatches(c,r);return {brand:match?r.brand:'',model:match?r.model:'',datasheet:match?r.source:'',designCatalogId:r.catalogId+(match?'':':modificado')}}

const auxTypes=['ATS','SPD AC','SPD DC'];
const auxFieldsCommon=[['name','Descripción','text'],['qty','Cantidad instalada'],['brand','Marca','text'],['model','Modelo','text'],['source','Ficha técnica / fuente','text'],['requiredV','Tensión máxima de diseño (V)'],['ratedV','Tensión asignada aplicable (V)'],['faultKA','Cortocircuito disponible (kA)'],['withstandKA','Capacidad de cortocircuito del conjunto (kA)'],['configuration','Esquema de conexión / dispositivo asociado según ficha','text'],['replace','Sustituir partida automática',['No sustituir','atsSwitch','spdAc','spdDc']]];
const auxFieldsATS=[['loadA','Corriente prevista (A)'],['ratedA','Corriente asignada en categoría de uso (A)'],['requiredPoles','Polos requeridos según unifilar'],['ratedPoles','Polos del ATS'],['requiredCoil','Tensión de mando disponible'],['ratedCoil','Tensión de mando admitida'],['utilCategory','Categoría de utilización (carga/transferencia)','text'],['interlock','Enclavamiento y transición verificados',['Pendiente','Confirmado mediante ficha/unifilar']]];
const auxFieldsSPD=[['requiredUc','Uc/Ucpv mínima según red y diseño (V)'],['ratedUc','Uc/Ucpv asignada (V)'],['equipmentUw','Tensión soportada del equipo Uw (kV)'],['effectiveUp','Up efectiva incluidos conductores (kV)'],['requiredType','Tipo requerido',['Pendiente','T1','T2','T1+T2','T3']],['ratedType','Tipo del SPD',['Pendiente','T1','T2','T1+T2','T3']],['backup','Protección de respaldo y conexión a tierra','text']];
function auxFields(a){return [...auxFieldsCommon,...(a.type==='ATS'?auxFieldsATS:auxFieldsSPD)]}
function auxCheck(a){let pending=[],issues=[],n=k=>v35Number(a[k]),pos=k=>n(k)>0?n(k):null;function min(req,rated,label){let r=pos(req),v=pos(rated);if(r===null||v===null)pending.push(label+': dato pendiente');else if(v<r)issues.push(label+': dato de ficha inferior al requerido')}
if(!auxTypes.includes(a.type))issues.push('Tipo no válido');if(!Number.isInteger(n('qty'))||n('qty')<=0)pending.push('Cantidad instalada pendiente');min('requiredV','ratedV','Tensión asignada');min('faultKA','withstandKA','Capacidad de cortocircuito del conjunto');if(!String(a.source||'').trim()||!String(a.configuration||'').trim())pending.push('Ficha, configuración y dispositivo asociado pendientes');if(!a.brand||!a.model)pending.push('Marca/modelo por confirmar');if(a.type==='ATS'){min('loadA','ratedA','Corriente asignada');if(!Number.isInteger(pos('requiredPoles'))||!Number.isInteger(pos('ratedPoles')))pending.push('Polos pendientes');else if(pos('requiredPoles')!==pos('ratedPoles'))issues.push('Polos distintos al unifilar');let x=pos('requiredCoil'),y=pos('ratedCoil');if(!x||!y)pending.push('Tensión de mando pendiente');else if(x!==y)issues.push('Tensión de mando diferente a ficha');if(!a.utilCategory||a.interlock!=='Confirmado mediante ficha/unifilar')pending.push('Categoría de uso, enclavamiento y transición pendientes')}else{min('requiredUc','ratedUc','Uc/Ucpv');let up=pos('effectiveUp'),uw=pos('equipmentUw');if(!up||!uw)pending.push('Up efectiva y Uw pendientes');else if(up>=uw)issues.push('Up efectiva alcanza o supera Uw');let req=a.requiredType,r=a.ratedType;if(!req||!r||req==='Pendiente'||r==='Pendiente')pending.push('Tipo de SPD pendiente');else if(req!==r&&!(r==='T1+T2'&&['T1','T2'].includes(req)))issues.push('Tipo SPD no cumple requisito declarado');if(!a.backup)pending.push('Protección de respaldo, tierra y coordinación pendientes')}
let expected={ATS:'atsSwitch','SPD AC':'spdAc','SPD DC':'spdDc'}[a.type];if(a.replace&&a.replace!=='No sustituir'&&a.replace!==expected)issues.push('Sustitución de partida no corresponde al tipo');return {issues,pending}}
function auxiliaryPanel(s){return panel('Transferencias ATS y protección contra sobretensión SPD',`<p>Comprobación preliminar por dispositivo. La capacidad de cortocircuito debe corresponder al conjunto y a la protección asociada especificada por el fabricante. Para SPD, Uc/Ucpv y Up se determinan según puesta a tierra, tensión máxima y coordinación; no se deducen solo de la tensión nominal.</p><div class="actions">${auxTypes.map(t=>B('Agregar '+t,`auxDialog(null,${arg(t)})`)).join('')}</div>${(s.auxProtections||[]).map(a=>{let r=auxCheck(a);return `<div class="tile"><b>${E(a.type+' · '+a.name)}</b>${r.issues.map(x=>`<p class="warn">${E(x)}</p>`).join('')}${r.pending.map(x=>`<p class="muted">${E(x)}</p>`).join('')}${!r.issues.length&&!r.pending.length?'<p>Valores declarados sin discrepancia; requiere revisión normativa y coordinación.</p>':''}${B('Editar',`auxDialog(${arg(a.id)},${arg(a.type)})`)}${B('Eliminar',`removeAux(${arg(a.id)})`,'danger small')}</div>`}).join('')}`)}
function auxDialog(id,type){let s=site(),old=id?s.auxProtections?.find(x=>x.id===id):null;if(!auxTypes.includes(type)||id&&!old)return;let a=old||{id:uid(),type,name:type,replace:'No sustituir'};modal('Ficha de '+type,`<div class="fields">${auxFields(a).map(([k,label,t])=>Array.isArray(t)?modalSelect(label,k,a[k]||t[0],t):mfield(label,k,a[k]??'',t==='text'?'text':'number',k==='name')).join('')}</div><p class="notice">Las tensiones de mando diferentes o configuraciones especiales deben verificarse con el fabricante. No se emite aprobación automática.</p>`,f=>{let updated={...a};for(let [k,,t] of auxFields(a))updated[k]=t?String(f.get(k)||'').trim():v35Number(f.get(k));if(!old)(s.auxProtections??=[]).push(updated);else Object.assign(old,updated);touch();render()})}
function removeAux(id){if(!confirm('¿Eliminar esta comprobación?'))return;site().auxProtections=site().auxProtections.filter(x=>x.id!==id);touch();render()}

function acGroupFields(){return [['name','Nombre del grupo','text'],['topology','Topología',topologyLabels.slice(1)],['units','Inversores del grupo'],['unitKW','Potencia activa por unidad (kW)'],['unitKVA','Potencia aparente por unidad (kVA)'],['voltage','Tensión L–L (L–N si monofásico convencional)'],['voltageLN','Tensión L–N (V)'],['pf','Factor de potencia común (0–1)'],['lineLimitA','Límite de corriente por línea del grupo (A)'],['loadL1','Carga L1–N simultánea (kW)'],['loadL2','Carga L2–N simultánea (kW)'],['loadL3','Carga L3–N simultánea (kW)'],['balancedKW','Carga equilibrada L–L o trifásica total (kW)'],['parallelApproval','Paralelo dentro del grupo',['No confirmado','Confirmado por fabricante']],['reference','Medición, ficha o plano de referencia','text'],['loadShare','Asignación del perfil de demanda (%)'],['batteryShare','Asignación de batería independiente (%)'],['gridShare','Asignación de capacidad de red (%)'],['dcLimitKW','Límite FV DC de este grupo (kW)'],['bessChargeKW','Banco común: límite DC de carga de esta rama (kW)'],['bessDischargeKW','Banco común: límite DC de descarga de esta rama (kW)'],['bessReference','Banco común: ficha o plano de rama DC autorizado','text'],['genKW','Generador dedicado: kW (0 sin generador)'],['genKVA','Generador: kVA'],['genPF','Generador: FP'],['genReference','Generador: modelo y referencia de transferencia dedicada','text'],['genChargeApproval','Recarga BESS común desde generador',['No confirmado','Confirmado por fabricante']],['genChargeKW','Límite individual de recarga por generador (kW)'],['genChargeReference','Ficha y plano de carga DC/transferencia autorizada','text'],['genAvailableFuel','Combustible disponible del grupo (L)'],['genFuelIdle','Consumo ralentí (L/h)'],['genFuel25','Consumo 25 % (L/h)'],['genFuel50','Consumo 50 % (L/h)'],['genFuel75','Consumo 75 % (L/h)'],['genFuel100','Consumo 100 % (L/h)'],['genWarmup','Calentamiento (min)'],['genCooldown','Enfriamiento (min)'],['microPanels','Microinversores: módulos asignados'],['microUnits','Microinversores: unidades asignadas'],['microReference','Microinversores: ficha y referencia AC','text'],['microCoupleApproval','Acoplamiento AC con inversor BESS',['No confirmado','Confirmado por fabricante']],['microIslandApproval','Isla AC por grupo',['No confirmado','Confirmado por fabricante']],['microIslandKW','Isla AC: límite de aporte FV (kW)']]}
function acArchitectureResult(s){let a=acArchitectureCheck(s),f=v=>v==null?'Pendiente':fmt(v,2);return `<p>Grupos: ${a.rows.length} · Inversores: ${a.units} · Potencia declarada: ${fmt(a.capacity)} kW.</p>${a.rows.length?`<div class="scroll"><table><tr><th>Grupo independiente</th><th>kW carga</th><th>kVA</th><th>Corriente por línea (A)</th><th>Neutro (A)</th><th>Desequilibrio de corriente %</th></tr>${a.rows.map(r=>`<tr><td>${E(r.g.name)}</td><td>${f(r.demand)}</td><td>${f(r.apparent)}</td><td>${r.currents.map((v,i)=>'L'+(i+1)+' '+f(v)).join(' / ')||'Pendiente'}</td><td>${f(r.neutral)}</td><td>${f(r.imbalance)}</td></tr>`).join('')}</table></div>`:''}${a.issues.map(x=>`<p class="warn">${E(x)}</p>`).join('')}${a.pending.map(x=>`<p class="muted">${E(x)}</p>`).join('')}`}
function acArchitecturePanel(s){return panel('Grupos AC independientes y balance de fases',`<p>Define tableros separados, con su demanda simultánea, unidades y límites de placa. No presupone paralelo AC entre grupos ni autorización para compartir BESS. Cálculo estático con tensión nominal y PF común, corrientes sinusoidales; no incluye armónicos, arranques ni despacho horario separado.</p><p class="notice">Para fase partida, carga equilibrada = carga entre L1 y L2. Para trifásico, carga equilibrada = carga trifásica total. Introduce cero si esa rama no existe. La comprobación por grupos, activada abajo, se utiliza en las cifras principales si es válida.</p>${B('Agregar grupo AC','acGroupDialog()')}${(s.acGroups||[]).map(g=>`<div class="actions"><b>${E(g.name)}</b>${B('Editar',`acGroupDialog(${arg(g.id)})`)}${B('Eliminar',`removeAcGroup(${arg(g.id)})`,'danger small')}</div>`).join('')}<div id="acArchitectureResult">${acArchitectureResult(s)}</div>${groupDispatchPanel(s)}`)}
function acGroupDialog(id){let s=site(),old=id?s.acGroups?.find(g=>g.id===id):null;if(id&&!old)return;let g=old||{id:uid(),name:'Grupo '+((s.acGroups||[]).length+1),topology:topologyLabels.slice(1).includes(s.gridTopology)?s.gridTopology:topologyLabels[1],units:1,parallelApproval:'No confirmado'};modal('Grupo AC independiente',`<div class="fields">${acGroupFields().map(([k,label,t])=>Array.isArray(t)?modalSelect(label,k,g[k]||t[0],t):mfield(label,k,g[k]??'',t==='text'?'text':'number',k==='name')).join('')}</div><p class="notice">Corriente máxima por línea: límite del grupo confirmado en la ficha, no suma supuesta de salidas. Solo dato preliminar sin armónicos.</p>`,f=>{let newGroup={...g};for(let [k,,t] of acGroupFields())newGroup[k]=t?String(f.get(k)||'').trim():v35Number(f.get(k));if(old)Object.assign(old,newGroup);else(s.acGroups??=[]).push(newGroup);touch();render()})}
function removeAcGroup(id){if(!confirm('¿Eliminar el grupo AC?'))return;site().acGroups=site().acGroups.filter(g=>g.id!==id);touch();render()}
function groupDispatchHTML(s){let d=independentGroupDispatch(s);if(!d.active)return '<p class="muted">Comprobación separada desactivada. El balance principal es agregado y puede ocultar déficit de un tablero.</p>';if(d.errors.length)return `<div class="warn"><b>Despacho separado no calculado</b>${d.errors.map(x=>`<p>${E(x)}</p>`).join('')}</div>`;let t=d.summary;return `<p><b>Déficit estimado del modelo separado: ${fmt(t.unmet,2)} kWh</b> · referencia agregada: ${fmt(t.aggregateUnmet,2)} kWh. ${d.common?'Banco común DC: SOC único, sin paralelo AC.':'No se transfieren excedentes ni SOC entre grupos.'}</p>${d.common?`<p><b>BESS común:</b> ${fmt(d.bank.capacity,2)} kWh efectivos · SOC inicial ${fmt(d.bank.start,2)} kWh · SOC final ${fmt(d.bank.end,2)} kWh (${fmt(d.bank.capacity?d.bank.end/d.bank.capacity*100:0,1)} %) · SOC mínimo ${fmt(Math.min(d.bank.start,...d.bank.history.map(r=>r.soc)),2)} kWh · BMS DC carga/descarga ${fmt(d.bank.chargeLimitDC,2)} / ${fmt(d.bank.dischargeLimitDC,2)} kW.</p>`:''}<div class="scroll">${rtable(['Grupo / unidades','Paneles','Conversión limitada kW','Demanda kWh','FV kWh','Red kWh','Generador kWh','Combustible L usado / restante','Déficit kWh','Cobertura %','Excedente kWh','Carga BESS kWh','Descarga BESS kWh','Batería efectiva kWh','SOC final kWh / %'],d.groups.map(g=>[`${g.name} · ${g.firstUnit}–${g.lastUnit}`,String(g.panels),fmt(g.limit,2),fmt(g.loadTotal,2),fmt(g.pvTotal,2),fmt(g.gridTotal,2),fmt(g.genTotal,2),g.fuelUsed==null?'—':`${fmt(g.fuelUsed,2)} / ${fmt(g.fuelLeft,2)}`,fmt(g.unmet,2),g.loadTotal?fmt((1-g.unmet/g.loadTotal)*100,1):'—',fmt(g.spill,2),fmt(g.rows.reduce((a,r)=>a+r.ch,0),2),fmt(g.rows.reduce((a,r)=>a+r.dis,0),2),d.common?'Común':fmt(g.effectiveBattery,2),d.common?'SOC único':`${fmt(g.rows.at(-1).soc,2)} / ${g.effectiveBattery?fmt(g.rows.at(-1).soc/g.effectiveBattery*100,1)+' %':'—'}`]))}</div>${d.notes.map(x=>`<p class="muted">${E(x)}</p>`).join('')}`}
function groupDispatchPanel(s){return panel('Comprobación energética por grupos independientes',`<p class="warn">El resultado principal utiliza el balance por grupo si la comprobación es válida. Si está incompleta, muestra una referencia agregada con advertencia. No constituye aprobación de arquitectura. Permite bancos independientes o un banco común autorizado, con límites DC maestros y por rama, referencia OEM y protocolo BMS. Admite generadores dedicados con transferencia durante apagones y microinversores AC con bancos independientes o banco común autorizado. En banco común, recarga del generador e isla AC solo con autorización explícita y límites por rama. Se conserva la prioridad a descarga, sin recarga concurrente; se bloquea generador e isla de microinversores en el mismo tablero. Declara fichas, valores y reparto en cada grupo.</p><p>Los grupos se asignan a los inversores por orden de creación. Edita su reparto en Ingeniería. Demanda residual y red deben sumar 100 % cuando se utilizan; batería solo para bancos independientes. En banco común declara límites DC de cada rama, incluso cero si no está conectada.</p><label class="check"><input type="checkbox" ${s.acGroupDispatch?'checked':''} onchange="site().acGroupDispatch=this.checked;touch();render()"> Activar comprobación por grupo</label><label class="field">Perfil de demanda por grupo<select onchange="site().acDemandMode=this.value;touch();render()"><option value="Porcentaje" ${s.acDemandMode!=='Equipos por tablero'?'selected':''}>Porcentaje del perfil común</option><option value="Equipos por tablero" ${s.acDemandMode==='Equipos por tablero'?'selected':''}>Equipos por tablero (asignar en ficha de carga)</option></select><small>Las cargas adicionales, EV y descanso usan el reparto porcentual. Si falta asignación de algún equipo, no se calcula el despacho.</small></label><div id="groupDispatchResult">${groupDispatchHTML(s)}</div>`)}
// Comprobaciones preliminares de PE y esquema de tierra. No selecciona tiempos,
// límites de contacto ni factor k por suposición: deben venir del proyecto/norma.
const groundPurchaseFields=[['peLength','Conductor PE según plano','m'],['earthElectrodes','Electrodos de tierra','ud'],['groundBars','Barras equipotenciales','ud'],['groundClamps','Conectores y abrazaderas de tierra','ud'],['pvBonds','Puentes equipotenciales de módulos y rieles','ud'],['inspectionBoxes','Arquetas de inspección','ud']];
const groundFields=[['scheme','Esquema de conexión a tierra',['Por confirmar','TT','TN-S','TN-C-S','TN-C','IT']],['plan','Plano y norma/referencia de diseño','text'],['measurementRef','Fecha, instrumento y registro de medición','text'],['reviewer','Especialista responsable','text'],['resistance','Resistencia de tierra medida (Ω)'],['resistanceTarget','Límite de resistencia según diseño (Ω)'],['faultKA','Corriente de defecto PE de cálculo (kA)'],['clearingS','Tiempo de despeje confirmado (s)'],['kFactor','Factor térmico k del conductor (A√s/mm²)'],['peSection','Sección PE propuesta (mm²)'],['loopZ','Impedancia de bucle medida Zs (Ω)'],['loopMax','Zs máxima según coordinación (Ω)'],['rcdMA','IΔn del diferencial (mA)'],['touchLimit','Límite de tensión de contacto del diseño (V)'],['continuity','Continuidad equipotencial medida',['Pendiente','Conforme al protocolo declarado','No conforme']],['purchase','Despiece',['Solo comprobación','Incluir despiece del plano']],['replace','Sustitución de partidas',['Conservar partidas pendientes','Sustituir partida general según plano completo']],...groundPurchaseFields.map(([k,l,u])=>[k,l+' ('+u+')'])];
function groundingCheck(g){g=g||{};let issues=[],pending=[],n=k=>v35Number(g[k]),positive=k=>n(k)!==null&&n(k)>0,section=null,touch=null;
 if(!['TT','TN-S','TN-C-S','TN-C','IT'].includes(g.scheme))pending.push('Esquema de tierra pendiente.');
 for(let [k,l] of [['plan','Plano y norma'],['measurementRef','Registro de medición'],['reviewer','Especialista responsable']])if(!String(g[k]||'').trim())pending.push(l+' pendiente.');
 if(!positive('resistance')||!positive('resistanceTarget'))pending.push('Medición de resistencia y criterio de aceptación pendientes.');else if(n('resistance')>n('resistanceTarget'))issues.push('Resistencia medida supera el límite declarado.');
 if(['faultKA','clearingS','kFactor','peSection'].every(positive)){section=n('faultKA')*1000*Math.sqrt(n('clearingS'))/n('kFactor');if(!Number.isFinite(section)){section=null;issues.push('Datos térmicos fuera de rango.')}else if(n('peSection')+1e-9<section)issues.push('Sección PE inferior al mínimo térmico adiabático calculado.');if(n('clearingS')>5)pending.push('Tiempo superior a 5 s; revisar método térmico aplicable.');}else pending.push('Faltan corriente de defecto, tiempo, factor k o sección PE.');
 if(g.scheme==='TT'){if(positive('rcdMA')&&positive('touchLimit')&&positive('resistance')){touch=n('resistance')*n('rcdMA')/1000;if(touch>n('touchLimit'))issues.push('Producto RA × IΔn supera tensión de contacto declarada.');}else pending.push('TT: faltan RA, IΔn o tensión de contacto admisible.');}
 if(['TN-S','TN-C-S','TN-C'].includes(g.scheme)){if(!positive('loopZ')||!positive('loopMax'))pending.push('TN: impedancia de bucle y límite coordinado pendientes.');else if(n('loopZ')>n('loopMax'))issues.push('Impedancia de bucle supera máximo declarado.');if(g.scheme==='TN-C')pending.push('TN-C: verificar restricciones PEN y transición a PE/N con el especialista.');}
 if(g.scheme==='IT')pending.push('IT: revisar vigilancia de aislamiento, segundo defecto y desconexión con el especialista.');
 if(g.continuity==='No conforme')issues.push('Continuidad equipotencial no conforme.');else if(g.continuity!=='Conforme al protocolo declarado')pending.push('Prueba de continuidad pendiente.');
 if(g.purchase==='Incluir despiece del plano')for(let [k,l,u] of groundPurchaseFields){let v=n(k);if(v===null)pending.push('Cantidad pendiente: '+l);else if(v<0||u==='ud'&&!Number.isInteger(v))issues.push('Cantidad inválida: '+l);}
 return {issues,pending,section,touch};}
function groundingText(g){let r=groundingCheck(g),f=(v,u)=>v==null?'Pendiente':fmt(v,3)+' '+u;return `Puesta a tierra: ${g.scheme||'pendiente'}; plano/referencia ${g.plan||'pendiente'}; RA medida ${f(v35Number(g.resistance),'Ω')}; criterio RA ${f(v35Number(g.resistanceTarget),'Ω')}; sección térmica PE ${f(r.section,'mm²')}; sección declarada ${f(v35Number(g.peSection),'mm²')}; RA × IΔn ${f(r.touch,'V')}; continuidad ${g.continuity||'pendiente'}. ${[...r.issues,...r.pending].join('; ')||'Datos declarados sin discrepancia en estas comprobaciones'}. Requiere coordinación, desconexión, sección mecánica, corrosión y revisión normativa; no es aprobación.`;}
function groundingResult(g){if(!g)return '<p class="muted">Ficha estructurada de tierra pendiente.</p>';let r=groundingCheck(g);return `<p>${E(groundingText(g))}</p>${r.issues.map(x=>`<p class="warn">${E(x)}</p>`).join('')}${r.pending.map(x=>`<p class="muted">${E(x)}</p>`).join('')}`;}
function groundingPanel(s){return panel('Puesta a tierra y equipotencialidad',`<p>Compara mediciones con criterios de proyecto, verifica sección térmica adiabática PE y registra el despiece del plano. No estima electrodos por resistencia ni fija límites universales. Las cantidades desconocidas quedan pendientes; cero explícito indica que no aplica.</p>${B(s.grounding?'Editar ficha de tierra':'Crear ficha de tierra','groundingDialog()')}<div id="groundingResult">${groundingResult(s.grounding)}</div>`)}
function groundingDialog(){let s=site(),g=s.grounding||{};modal('Ficha de puesta a tierra',`<div class="fields">${groundFields.map(([k,l,t])=>Array.isArray(t)?modalSelect(l,k,g[k]||t[0],t):mfield(l,k,g[k]??'',t==='text'?'text':'number')).join('')}</div><p class="notice">Los límites, k y tiempos deben proceder de la norma, fichas y coordinación aplicables. El cálculo térmico no reemplaza secciones mínimas mecánicas ni el diseño de protección. Solo sustituir partidas genéricas si el plano abarca toda la instalación.</p>`,f=>{s.grounding=Object.fromEntries(groundFields.map(([k,,t])=>[k,t?String(f.get(k)||'').trim():v35Number(f.get(k))]));touch();render()})}

const IDENTITY_DEFAULTS=Object.freeze({name:'Bonaire Energía Vital',division:'División de ingeniería',contact:'',footer:'Energía Vital Pro Studio'});
let identityRecord={rev:0,data:{...IDENTITY_DEFAULTS}};
function validatedIdentity(input){let out={};for(let [key,max] of Object.entries({name:100,division:100,contact:160,footer:120})){let v=input?.[key];if(typeof v!=='string'||v.length>max||/[\x00-\x1f]/.test(v))return null;out[key]=v.trim()}return out.name?out:null}
function receiveIdentity(record){if(!record||!Number.isInteger(record.rev)||record.rev<identityRecord.rev)return false;let data=validatedIdentity(record.data);if(!data)return false;let changed=JSON.stringify(data)!==JSON.stringify(identityRecord.data);identityRecord={rev:record.rev,data};return changed}
function publicIdentity(){return identityRecord.data}
function safeFooter(v){return String(v||'').replace(/[^\p{L}\p{N} .·_-]/gu,' ').slice(0,120)}
function brandMark(size=44){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="${size}" height="${size}" role="img" aria-label="Energía Vital" style="flex-shrink:0;vertical-align:middle"><rect width="64" height="64" rx="13" fill="#124a43"/><path d="M10 46h44M15 40l5-16h24l5 16zM21 32h22M28 24l-2 16m10-16 2 16" fill="none" stroke="#9bd4c7" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M35 6 16 32h15l-2 21 22-30H35z" fill="#f5cc62" stroke="#124a43" stroke-width="2.4" stroke-linejoin="round"/></svg>`}
function identityPanel(){let d=publicIdentity(),admin=shared&&me?.role==='admin';return panel('Identidad pública · marca e informes',`<div class="row" style="align-items:center;gap:14px">${brandMark(64)}<div><h3>${E(d.name)}</h3><p>${E(d.division)}</p></div></div><p class="notice">Estos campos son públicos: se incluirán en nuevas entregas. No introduzcas datos bancarios, claves ni información interna. La marca gráfica es una propuesta original integrada en el programa.</p>${admin?`<form id="identityForm" onsubmit="event.preventDefault();savePublicIdentity(this)"><input type="hidden" name="rev" value="${identityRecord.rev}"><div class="fields">${[['name','Nombre comercial',100],['division','División o departamento',100],['contact','Contacto público',160],['footer','Pie de informe',120]].map(([k,l,max])=>`<label class="field">${E(l)}<input name="${k}" maxlength="${max}" value="${E(d[k])}" ${k==='name'?'required':''}></label>`).join('')}</div><button type="submit">Guardar identidad empresarial</button></form><p class="muted">Se guarda en la base SQLite local y se aplica a los usuarios autorizados. No modifica los informes archivados ni las ofertas emitidas.</p>`:'<p class="muted">Solo el administrador autenticado puede cambiar la identidad empresarial.</p>'}`)}
async function savePublicIdentity(form){if(!shared||me?.role!=='admin')return toast('Reservado al administrador');let raw=Object.fromEntries(new FormData(form)),data=validatedIdentity(raw);if(!data)return toast('Revisa los datos de identidad');try{let r=await api('/api/identity',{method:'POST',body:JSON.stringify({rev:Number(raw.rev),data})});receiveIdentity(r.identity);render();toast('Identidad guardada en la base local')}catch(e){toast(e.message);if(e.code===409){try{let r=await api('/api/state');receiveIdentity(r.identity);render()}catch{}}}}


function exportSimulationData(s){
 const primitive=v=>typeof v==='number'&&Number.isFinite(v)||typeof v==='string'||typeof v==='boolean'?v:null;
 const pick=(r,keys)=>Object.fromEntries(keys.map(k=>[k,primitive(r?.[k])]));
 const list=(v,keys)=>Array.isArray(v)?v.map(r=>pick(r,keys)):[];
 const keys=[...Object.keys(configs),'pvMode','pvCoupled','simStart','simHours','startWeekday','evOnRest','restMode','inventoryWork','inventoryRest','useLoads','loadCalendarMode','genEnabled','genMode','genTarget','genMaxHours','genSocStart','genSocStop','genChargeLimit','genOnlyOutage','batterySOH','bmsChargeKW','bmsDischargeKW','auxKW','shadeLoss','optimizerMode','inverterCount','unitInverter','mpptPerInverter','dcPerInverter','microCount','microAC','microInputs','microMaxV','microMaxIsc','microMinV','microMpptMax','microIslandMode','microIslandKW','genFuelMode','genFuelIdle','genFuel25','genFuel50','genFuel75','genFuel100','genAvailableFuel','genWarmup','genCooldown','genKva','genPF','genMinLoad','acConnection','batteryConnection','batteryMinV','batteryMaxV','acDemandMode'];
 let o=Object.fromEntries(keys.map(k=>[k,primitive(k==='restDay'?s.restDay:simValue(s,k))]));
 for(let k of ['pvHourly','pvHourlyTemp','workDays','modules'])o[k]=Array.isArray(s[k])?s[k].map(primitive):k==='workDays'?[0,1,2,3,4,5,6]:[];
 o.loads=list(s.loads,['name','kw','qty','sim','start','hours','priority','acGroupId']);o.loads.forEach((r,i)=>{if(Array.isArray(s.loads[i].activeDays))r.activeDays=s.loads[i].activeDays.map(primitive)});o.outages=list(s.outages,['start','hours','weekday']);o.genIntervals=list(s.genIntervals,['start','hours']);
 o.pvAssignments=list(s.pvAssignments,['unit','mppt','series','strings','maxA','minV','maxV','maxVoc','maxIsc']);o.acGroupDispatch=s.acGroupDispatch===true;
 o.acGroups=list(s.acGroups,['id',...acGroupFields().map(f=>f[0]).filter(k=>!['reference','bessReference','genReference','microReference','genChargeReference'].includes(k))]);
 // A reference is needed for model validation but its internal text need not travel.
 for(let [i,g] of o.acGroups.entries())for(let k of ['reference','bessReference','genReference','microReference','genChargeReference'])g[k]=String(s.acGroups[i][k]||'').trim()?'Referencia declarada en el expediente original':'';
 for(let k of ['factoryConfirmation','bmsProtocol'])o[k]=String(s[k]||'').trim()?'Referencia declarada en el expediente original':'';
 return o;
}
function exportGroupHTML(x){
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const f=v=>v==null||!Number.isFinite(v)?'—':v.toFixed(1),d=independentGroupDispatch(x);
 if(!d.active)return x.acGroups?.length?'<p><b>Balance agregado solamente.</b> No garantiza cobertura individual de los tableros.</p>':'';
 let intro='<h2>Simulación por tableros independientes</h2><p>Cuando la comprobación es válida, los resultados generales representan la suma de flujos por grupos y SOC sin duplicar bancos. Si no es válida, son solo una referencia agregada. La configuración por tablero conserva los límites de la entrega original; si cambias totales incompatibles, esta simulación no se calcula.</p>';
 if(d.errors.length)return intro+'<p><b>No calculado por grupos:</b></p><ul>'+d.errors.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul>';
 return intro+'<p><b>Déficit por grupos: '+f(d.summary.unmet)+' kWh</b> · referencia agregada: '+f(d.summary.aggregateUnmet)+' kWh.</p>'+(d.common?'<p>Banco común: '+f(d.bank.capacity)+' kWh efectivos · SOC final '+f(d.bank.end)+' kWh. Único banco, sin paralelo AC.</p>':'')+'<table><tr><th>Tablero</th><th>Demanda kWh</th><th>FV kWh</th><th>Red kWh</th><th>Generador kWh</th><th>Déficit kWh</th><th>Cobertura %</th><th>SOC final kWh</th></tr>'+d.groups.map(g=>'<tr>'+[esc(g.name),f(g.loadTotal),f(g.pvTotal),f(g.gridTotal),f(g.genTotal),f(g.unmet),f(g.loadTotal?100*(1-g.unmet/g.loadTotal):null),d.common?'Banco común':f(g.rows.at(-1).soc)].map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table>'+d.notes.map(v=>'<p>'+esc(v)+'</p>').join('');
}


function balanceNotice(r){return r.groupStatus==='groups'?'<p class="notice">Balance por tableros independientes; referencia agregada de déficit: '+fmt(r.aggregateUnmet,2)+' kWh. No equivale a aprobación OEM.</p>':r.groupStatus==='invalid'?'<p class="warn">Balance por grupos incompleto: '+E((r.groupErrors||[]).join('; '))+'. Los valores siguientes son referencias agregadas, no cobertura validada.</p>':'';}


let deliveryReview=null;
function deliveryReviewSignature(){let p=project();return p?JSON.stringify([p.id,p.updated,reportConfig(p),publicIdentity(),expSections.map((_,i)=>!!$('ex'+i)?.checked),p.sites.map(s=>[s.id,s.updated,s.name,s.images.map(a=>[a.assetId,a.publish,a.caption,a.designSnapshot]),s.files.map(a=>[a.name,a.publish]),s.tasks.length,s.materials.length])]):null;}
