function applyOfflineDiff(raw,changes){let d=copy(raw);if(!Array.isArray(changes))throw Error('Diario inválido');for(const x of changes){if(!Array.isArray(x.path)||x.path.some(k=>typeof k!=='string'||['__proto__','constructor','prototype'].includes(k)))throw Error('Ruta inválida');if(!x.path.length){if(x.remove)throw Error('Diario inválido');d=copy(x.value);continue}let o=d;for(const k of x.path.slice(0,-1)){if(!o||typeof o!=='object'||!own(o,k))throw Error('Ruta de recuperación no disponible');o=o[k]}let k=x.path.at(-1);if(!o||typeof o!=='object')throw Error('Ruta inválida');if(x.remove)delete o[k];else o[k]=copy(x.value)}return d}
