function journalOffline(next){try{let j={target:next.rev,patches:[{base:offlineRev,changes:offlineDiff(offlineCommitted,next.state)}]};if(offlineInFlight&&offlineInFlight.rev!==next.rev)j.patches.push({base:offlineInFlight.rev,changes:offlineDiff(offlineInFlight.state,next.state)});localStorage.setItem(OFF_JOURNAL,JSON.stringify(j));return true}catch{return false}}
