async function manualOfflineSave(){if(!offlinePending&&dirty)queueOfflineSave();let ok=await flushOffline();if(!dirty&&(db||globalThis.EVEngineeringStore))toast(globalThis.EVEngineeringStore?.scope==='online'?'Guardado online confirmado':'Guardado local confirmado');else if(!ok)toast('No se confirmó el guardado. Descarga un respaldo general.');}
