let routeReady=false,routeApplying=false;
function routeHash(){return '#/'+(project()?['proyectos',pid,site()?.id||'',page]:page==='company'&&companyId?['empresas',companyId]:[page]).map(x=>encodeURIComponent(x)).join('/')}
function restoreRoute(){let h=location.hash;try{let a=h.replace(/^#\/?/,'').split('/').map(decodeURIComponent);if(a[0]==='proyectos'&&a.length===4&&SUB.some(x=>x[0]===a[3])){let p=state.projects.find(x=>x.id===a[1]);if(p&&p.sites.some(s=>s.id===a[2])){pid=p.id;sid=a[2];page=a[3]}else{pid=sid=null;page='projects'}}else if(a[0]==='empresas'&&company(a[1])){pid=sid=null;companyId=a[1];page='company'}else if(MAIN.some(x=>x[0]===a[0])){pid=sid=null;page=a[0]}else{pid=sid=null;page='home'}}catch{pid=sid=null;page='home'}routeReady=true}
function updateRoute(){if(!routeReady||routeApplying)return;let h=routeHash();if(location.hash!==h){try{history.pushState(null,'',h)}catch{location.hash=h}}}
function onRouteChange(){if(!routeReady||(shared&&(!me||locking)))return;routeApplying=true;try{restoreRoute();render();window.scrollTo(0,0)}finally{routeApplying=false}}
window.addEventListener('hashchange',onRouteChange);window.addEventListener('popstate',onRouteChange);
// Paginación para listas de trabajo: conserva índices originales aun en página 2+.
const listPages=Object.create(null);
function resetListPage(k){listPages[k]=0}
function pageSlice(items,k,n){let max=Math.max(0,Math.ceil(items.length/n)-1);listPages[k]=Math.max(0,Math.min(max,listPages[k]||0));return items.slice(listPages[k]*n,(listPages[k]+1)*n)}
function pageControls(items,k,n){let total=Math.ceil(items.length/n),i=listPages[k]||0;if(total<=1)return '';return `<div class="list-pagination row" style="grid-column:1/-1;justify-content:center;gap:12px;margin:14px 0"><button class="secondary small" type="button" ${i===0?'disabled':''} onclick="goListPage(${arg(k)},${i-1})">Anterior</button><span>${i+1} / ${total} · ${items.length} registros</span><button class="secondary small" type="button" ${i>=total-1?'disabled':''} onclick="goListPage(${arg(k)},${i+1})">Siguiente</button></div>`}
function pageCards(items,k,card,n=12){return pageSlice(items,k,n).map(card).join('')+pageControls(items,k,n)}
function goListPage(k,i){listPages[k]=i;render()}

// Portable workspace synchronization. No deletions inferred from absence in a file.
const mergeKinds=['companies','projects','library','templates'];
const mergeLabels={companies:'Empresa',projects:'Expediente',library:'Biblioteca',templates:'Plantilla'};
const mergeId=x=>typeof x==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(x);
function mergeEqual(a,b){if(a===b)return true;if(a===null||b===null||typeof a!==typeof b||typeof a!=='object'||a===undefined||b===undefined||Array.isArray(a)!==Array.isArray(b))return false;let ak=Object.keys(a),bk=Object.keys(b);return ak.length===bk.length&&ak.every(k=>Object.prototype.hasOwnProperty.call(b,k)&&mergeEqual(a[k],b[k]))}
function mergeRead(raw){
 if(!raw||!['workspace','project','company','workspace-sync'].includes(raw.kind)||!validImportedValue(raw))throw Error('Selecciona un respaldo JSON V3 del espacio, empresa o expediente; no un informe de cliente.');
 let w={};for(let k of mergeKinds){if(!Array.isArray(raw[k]))throw Error('Falta la lista '+k);let ids=new Set();w[k]=raw[k].map(v=>{if(!v||typeof v!=='object'||Array.isArray(v)||!mergeId(v.id)||ids.has(v.id))throw Error('Identificador ausente o duplicado en '+k);ids.add(v.id);if(k==='projects'){
 if(!mergeId(v.companyId)||!Array.isArray(v.sites)||!v.sites.length)throw Error('Expediente sin empresa o instalaciones válidas');let si=new Set();for(let s of v.sites){if(!s||!mergeId(s.id)||si.has(s.id))throw Error('Identificador de instalación inválido o duplicado');si.add(s.id);for(let f of ['loads','materials','images','files','tasks','budget','scenarios','outages','pvAssignments','designCircuits','commercialOffers','supplierQuotes','auxProtections','acGroups']){if(s[f]==null&&['pvAssignments','designCircuits','commercialOffers','supplierQuotes','auxProtections','acGroups'].includes(f))continue;if(f in s&&(!Array.isArray(s[f])||s[f].some(r=>!r||typeof r!=='object'||Array.isArray(r))))throw Error('Lista técnica inválida: '+f)}if('modules' in s&&(!Array.isArray(s.modules)||s.modules.some(m=>typeof m!=='string')))throw Error('Módulos inválidos');for(let f of ['overrides','materialCosts','docs','privateFinance'])if(f in s&&(!s[f]||typeof s[f]!=='object'||Array.isArray(s[f])))throw Error('Campo técnico inválido: '+f)}
 }return copy(v)});}
 return w;
}
function mergePermissions(v,old,k,enterprise){let n=copy(v);if(enterprise&&k==='projects'){if(old&&Object.prototype.hasOwnProperty.call(old,'allowedUsers'))n.allowedUsers=copy(old.allowedUsers);else if(old)delete n.allowedUsers;else n.allowedUsers=[]}return n}
function mergePlan(local,incoming,ancestor=null,enterprise=false){let l=entityMap(local),r=entityMap(incoming),a=ancestor?entityMap(ancestor):{},rows=[],same=0,localOnly=0;for(let [key,x] of Object.entries(r)){let current=l[key]?.data,received=mergePermissions(x.data,current,x.kind,enterprise),prior=a[key]?.data;if(prior)prior=mergePermissions(prior,current,x.kind,enterprise);let action;if(!current)action=prior?'conflict':'add';else if(mergeEqual(current,received)){same++;continue}else if(prior&&mergeEqual(received,prior)){localOnly++;continue}else if(prior&&mergeEqual(current,prior))action='update';else action='conflict';rows.push({key,kind:x.kind,id:x.id,current,received,action})}for(let k of Object.keys(l))if(!r[k])localOnly++;return {rows,same,localOnly}}
function mergeResult(local,plan,choices={}){let out=copy(local),changed=[];for(let [i,r] of plan.rows.entries()){let action=r.action==='conflict'?choices[i]:r.action;if(r.action==='conflict'&&!['keep','incoming'].includes(action))throw Error('Selecciona una decisión para cada conflicto.');if(action==='keep')continue;let idx=out[r.kind].findIndex(x=>x.id===r.id);if(idx<0)out[r.kind].push(copy(r.received));else out[r.kind][idx]=copy(r.received);changed.push(r)}let companies=new Set(out.companies.map(c=>c.id));for(let p of out.projects)if(!companies.has(p.companyId))throw Error('Falta la empresa de '+(p.name||p.id)+'. Inclúyela en el archivo antes de fusionar.');return {out,changed}}
function mergerAllowed(){return offlineReady||shared&&me?.role==='admin'&&!locking}
function mergePanel(){if(!mergerAllowed())return '';return panel('Sincronización entre autónomo y empresarial',`<p>Intercambia expedientes, materiales, biblioteca y plantillas sin cambiar sus identificadores. No borra registros por estar ausentes en un archivo. Solo el administrador puede importar al modo empresarial; los permisos de expedientes existentes se conservan.</p><div class="actions">${B('Exportar JSON de sincronización','exportMergeWorkspace()','')}${B('Fusionar JSON existente','openMergePicker()','')}</div><p class="warn">Archivo privado sin cifrar. No incluye cuentas, contraseñas, sesiones ni auditoría. Utiliza solamente archivos propios o exportados por un administrador: un respaldo de trabajador puede carecer de datos privados. Protege el archivo. Si dos modos editan el mismo registro, compara las versiones antes de aceptar.</p>`)}
async function freshMergeState(){if(!mergerAllowed())throw Error('Sin autorización para fusionar.');if(offlineReady){if(dirty&&autoSaveEnabled)await flushOffline();if(dirty||offlineConflict||!db)throw Error('No se confirmó el guardado local. Resuelve el conflicto o descarga respaldo antes de fusionar.');return {snapshot:copy(state),revisions:null,localRev:offlineRev}}
 if(dirty||collision||syncing)throw Error('Espera a que termine el guardado empresarial o resuelve el conflicto de edición.');syncing=true;try{let r=await api('/api/state');if(!mergerAllowed()||dirty)throw Error('El espacio cambió durante la consulta.');base=Object.fromEntries(r.records.map(x=>[x.kind+':'+x.id,x]));state=serverState(r.records);receiveIdentity(r.identity);captureInstallationEdit();render();return {snapshot:copy(state),revisions:Object.fromEntries(r.records.map(x=>[x.kind+':'+x.id,x.rev])),localRev:null}}finally{syncing=false}}
async function exportMergeWorkspace(){try{let p=await freshMergeState();downloadJSON('EV_sincronizacion_'+(shared?'empresarial':'autonomo'),{kind:'workspace-sync',...p.snapshot});toast('JSON de sincronización generado')}catch(e){toast(e.message)}}
async function readMergeFile(f){if(!f||!f.size||f.size>200*1024*1024)throw Error('Selecciona un JSON de hasta 200 MiB.');return mergeRead(JSON.parse(await f.text()))}
function openMergePicker(){if(!mergerAllowed())return toast('Reservado al administrador.');modal('Fusionar espacio de trabajo',`<label class="field">Archivo JSON recibido<input type="file" name="incoming" accept=".json,application/json" required></label><label class="field">Base común anterior (opcional)<input type="file" name="ancestor" accept=".json,application/json"></label><p class="muted">Si ambos modos parten de un mismo JSON, conserva ese archivo como base común: permite identificar cuáles registros solo se cambiaron en uno de ellos. Sin base común, todo registro diferente con el mismo identificador requiere revisión. Los registros borrados en otro modo no se borran aquí.</p>`,async f=>{try{const incoming=await readMergeFile(f.get('incoming')),ancestor=f.get('ancestor')?.size?await readMergeFile(f.get('ancestor')):null;let fresh=await freshMergeState();$('dialog').close();showMergePreview(fresh,incoming,ancestor);return false}catch(e){toast(e.message);return false}},'Comparar archivos')}
function mergeFieldNames(a,b){if(!a)return 'Registro ausente en destino; existía en base común';return [...new Set([...Object.keys(a),...Object.keys(b)])].filter(k=>!mergeEqual(a[k],b[k])).join(', ')||'Sin diferencias'}
function showMergePreview(fresh,incoming,ancestor){let plan=mergePlan(fresh.snapshot,incoming,ancestor,shared);let n=plan.rows.filter(r=>r.action==='conflict').length,adds=plan.rows.filter(r=>r.action==='add').length,updates=plan.rows.filter(r=>r.action==='update').length;
 const similar=plan.rows.filter(r=>!r.current&&fresh.snapshot[r.kind].some(x=>typeof x.name==='string'&&typeof r.received.name==='string'&&x.name.trim().toLowerCase()===r.received.name.trim().toLowerCase())).length;
 modal('Revisar sincronización',`<p><b>${adds}</b> nuevos · <b>${updates}</b> actualizaciones desde base común · <b>${n}</b> conflictos · <b>${plan.same}</b> idénticos · <b>${plan.localOnly}</b> conservados del destino.</p>${similar?`<p class="warn">${similar} registros nuevos tienen el mismo nombre que otro registro pero distinto ID. Pueden ser copias antiguas; no se fusionan por nombre. Cancela si no deseas agregarlos.</p>`:''}<p>Los conflictos se resuelven por registro completo, no campo a campo. Para combinar manualmente los campos, descarga la comparación privada, conserva la versión actual y edita después. Aplicar la versión recibida sustituye todo el registro, incluidos sus costos y adjuntos. Los nuevos expedientes empresariales quedan accesibles solo al administrador hasta asignar permisos.</p>${B('Descargar versiones de comparación privadas','downloadMergeComparison()')}${plan.rows.filter(r=>r.action==='conflict').map(r=>`<div class="panel"><strong>${E(mergeLabels[r.kind])}: ${E(r.received.name||r.id)}</strong><p class="muted">Campos diferentes: ${E(mergeFieldNames(r.current,r.received))}</p><label class="field">Decisión<select name="choice${plan.rows.indexOf(r)}" required><option value="">Seleccionar…</option><option value="keep">Conservar la versión actual (o su ausencia)</option><option value="incoming">Aplicar la versión recibida completa</option></select></label></div>`).join('')}<p>${B('Descargar respaldo anterior privado','downloadMergeBefore()')}</p><label class="check"><input type="checkbox" name="confirm" required> He guardado una copia del estado anterior y revisado las decisiones.</label>`,async f=>{try{let choices={};plan.rows.forEach((r,i)=>{if(r.action==='conflict')choices[i]=f.get('choice'+i)});let result=mergeResult(fresh.snapshot,plan,choices);await applyMerge(fresh,result);return true}catch(e){toast(e.message);return false}},'Aplicar fusión');mergePreviewData={fresh,incoming,ancestor};}
let mergePreviewData=null;
function downloadMergeBefore(){if(mergePreviewData)downloadJSON('EV_antes_de_fusion_privado',{kind:'workspace',...mergePreviewData.fresh.snapshot})}
function downloadMergeComparison(){if(mergePreviewData){let {fresh,incoming,ancestor}=mergePreviewData;downloadJSON('EV_comparacion_privada',{kind:'comparison-private',current:fresh.snapshot,incoming,ancestor})}}
async function applyMerge(fresh,result){if(!mergerAllowed()||!mergeEqual(state,fresh.snapshot)||dirty||collision||syncing)throw Error('El espacio cambió desde la vista previa. Cancela y vuelve a comparar.');if(!result.changed.length){toast('No hay cambios que aplicar.');return}if(offlineReady){if(offlineRev!==fresh.localRev||offlineConflict||!db)throw Error('Cambió la revisión local. Vuelve a comparar.');state=normalize(result.out);captureInstallationEdit();queueOfflineSave();let saved=await flushOffline();if(!saved||dirty){render();throw Error('Fusión en memoria, guardado no confirmado. Guarda respaldo y no cierres esta pestaña.')}render();toast('Fusión local guardada: '+result.changed.length+' registros');return}
 if(!shared||me?.role!=='admin')throw Error('Solo un administrador puede aplicar cambios empresariales.');let ops=result.changed.map(r=>({kind:r.kind,id:r.id,rev:fresh.revisions[r.key]||0,data:r.received}));syncing=true;try{let r=await api('/api/changes',{method:'POST',body:JSON.stringify({ops})});if(!mergerAllowed())throw Error('Sesión cerrada. Verifica el resultado al volver a entrar.');base=Object.fromEntries(r.records.map(x=>[x.kind+':'+x.id,x]));state=serverState(r.records);receiveIdentity(r.identity);captureInstallationEdit();status('Base compartida · fusión confirmada');render();toast('Fusión empresarial guardada: '+ops.length+' registros')}catch(e){if(e.code===409)throw Error('La base empresarial cambió o contiene un registro eliminado. No se aplicó la fusión. Cancela y vuelve a comparar.');throw e}finally{syncing=false}}


/* 3.6.2 - resumen empresarial y RFQ seleccionable. Datos opcionales, sin cambiar el motor. */
function projectViabilityStatus(p){return viabilityStates.includes(p?.viability?.status)?p.viability.status:'Sin evaluar'}
function projectViabilityLabel(p){let v=projectViabilityStatus(p);return v!=='Sin evaluar'&&p.viability?.reviewedUpdated&&String(p.updated||'')>String(p.viability.reviewedUpdated)?v+' · Revalidar':v}
function companyExportDialog(id,mode){
 const c=company(id);if(!c)return toast('Empresa no encontrada');if(shared&&me?.role!=='admin')return toast('Solo administración puede emitir paquetes empresariales');
 const projects=state.projects.filter(p=>p.companyId===id);if(!projects.length)return toast('No hay proyectos en esta empresa para exportar.');
 const supplier=mode==='supplier';
 let heading=supplier?'Solicitud global a proveedor · proyectos seleccionados':'Resumen integral de empresa · proyectos seleccionados';
 let text=supplier?'Elige qué alternativas cotizar. No se suman automáticamente todas. Puedes elegir instalaciones de cada proyecto. No se incluyen datos de cliente.':'Marca únicamente los proyectos que quieras incluir en el resumen y en el ZIP interior. Los proyectos no elegidos quedarán fuera de ambas partes.';
 let rows=projects.map((p,i)=>`<div class="tile" style="padding:12px;margin:9px 0"><label class="check"><input type="checkbox" name="evCompanyProject" value="${E(p.id)}" onchange="companyExportToggleSites(this)"><b>${E(p.name)}</b> · ${E(p.version)}</label><small>${E(p.status)} · Viabilidad: ${E(projectViabilityLabel(p))} · ${p.sites.length} instalación(es)</small>${supplier?`<div style="margin:7px 0 0 22px">${p.sites.map(st=>`<label class="check"><input name="evCompanySite" type="checkbox" value="${E(p.id+'|'+st.id)}" disabled>${E(st.name)}</label>`).join('')}</div>`:''}</div>`).join('');
 let options=supplier?`<div class="fields">${mfield('Código de solicitud','code','RFQ_'+localDateKey(),'text',true)}${mfield('Proveedor / destinatario (opcional)','recipient','')}</div><label class="check"><input name="group" type="checkbox"> Consolidar materiales exactamente iguales de los proyectos elegidos (opcional)</label><p class="warn">Al seleccionar proyectos diferentes se trata de una solicitud conjunta: confirma que realmente deseas cotizar el conjunto. EXW y CBM quedarán vacíos para el fabricante.</p>`:`<label class="check"><input name="history" type="checkbox" checked> Añadir informes históricos guardados de los proyectos seleccionados</label><p class="notice">El informe general y los informes individuales se entregarán en PDF. Dentro del ZIP principal habrá otro ZIP con cada proyecto.</p>`;
 modal(heading,`<p class="notice">${E(text)}</p><div class="row">${B('Marcar todos',"document.querySelectorAll('[name=evCompanyProject]').forEach(x=>{x.checked=true;companyExportToggleSites(x)})")} ${B('Desmarcar todos',"document.querySelectorAll('[name=evCompanyProject]').forEach(x=>{x.checked=false;companyExportToggleSites(x)})")}</div><div class="scroll" style="max-height:300px">${rows}</div>${options}<label class="check"><input type="checkbox" name="review" required> He revisado los proyectos, las condiciones y el contenido que se entregará. Autorizo esta exportación.</label><div id="evCompanyProgress" role="status" aria-live="polite"></div><progress id="evCompanyProgressBar" value="0" max="100" style="width:100%"></progress>`,async f=>{
  if(!f.has('review'))return false;
  const chosen=projects.filter(p=>f.getAll('evCompanyProject').includes(p.id));if(!chosen.length)throw Error('Selecciona al menos un proyecto');
  const selected=copy(chosen); // instantánea consistente para toda la exportación
  if(supplier){const siteIds=new Set(f.getAll('evCompanySite'));for(const p of selected)p.sites=p.sites.filter(st=>siteIds.has(p.id+'|'+st.id));if(!selected.some(p=>p.sites.length))throw Error('Selecciona al menos una instalación');}
  await companyExportSelected(c,selected,{mode,history:f.has('history'),group:f.has('group'),code:String(f.get('code')||''),recipient:String(f.get('recipient')||'')});return true;
 },supplier?'Generar proveedor · PDF + Excel':'Descargar ZIP de empresa');
}
function companyExportToggleSites(el){const box=el.closest('.tile');if(!box)return;for(const input of box.querySelectorAll('input[name=evCompanySite]')){input.disabled=!el.checked;input.checked=el.checked}}
function companyExportProgress(percent,description){const a=$('evCompanyProgress'),b=$('evCompanyProgressBar');if(a)a.textContent=description;if(b)b.value=Math.max(0,Math.min(100,percent))}
function companyExportCleanName(s){return slug(s).slice(0,55)}
function companyExportSanitize(text,privateTokens){let out=String(text??'');for(const token of privateTokens){if(token.length<4)continue;out=out.replace(new RegExp(token.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),'[dato reservado]')}return out}
function companyExportPublicTokens(c,projects){return [...new Set([c.name,c.commercial,c.contact,c.phone,c.email,c.address,c.tax,...projects.flatMap(p=>[p.name,p.objective,...(p.sites||[]).flatMap(s=>[s.name,s.location])])].filter(x=>typeof x==='string'&&x.trim().length>=4).map(x=>x.trim()))]}
function companyExportSummaryHTML(c,selected){
 const total=selected.length,group=Object.fromEntries(viabilityStates.map(s=>[s,selected.filter(p=>projectViabilityStatus(p)===s).length]));
 const stateTotals=Object.fromEntries(statuses.map(s=>[s,selected.filter(p=>p.status===s).length]));
 const rows=selected.map((p,i)=>[i+1,p.name,p.status,projectViabilityLabel(p),p.sites.length,p.sites.map(s=>String(s.panels||0)).join(' / '),p.sites.map(s=>String(s.battery||0)).join(' / ')]);
 const details=selected.map((p,i)=>{let siteRows=p.sites.map(s=>{let e=energy(s);return [s.name,s.panels||0,s.watts||0,s.battery||0,s.inverter||0,fmt(e.loadTotal)+' kWh',fmt(e.unmet)+' kWh',String(e.rows?.length||0)+' h']});return `<section><h2>${i+1}. ${E(p.name)}</h2><p><b>Estado documental:</b> ${E(p.status)} · <b>Viabilidad:</b> ${E(projectViabilityLabel(p))}</p><p><b>Objetivo:</b> ${E(p.objective||'Pendiente')} · <b>Versión:</b> ${E(p.version)} · <b>Actualizado:</b> ${E(p.updated||'Sin fecha')}</p><p><b>Fundamento de viabilidad:</b> ${E(p.viability?.rationale||'No evaluado')}</p><p><b>Condiciones para implementar:</b> ${E(p.viability?.conditions||'Por documentar')}</p>${rtable(['Instalación','Paneles','W/panel','Batería kWh','Inversor kW','Demanda','Déficit','Horizonte'],siteRows)}<p>Los valores proceden del escenario activo de cada instalación. Cero déficit en el período simulado no certifica viabilidad definitiva.</p></section>`}).join('');
 const summary=`<section><h2>Resumen ejecutivo</h2><p><b>Empresa:</b> ${E(c.name)}</p><p><b>Proyectos incluidos:</b> ${total}. Este informe contiene exclusivamente los proyectos elegidos al exportar.</p>${rtable(['Viables','Condicionados','No viables','Sin evaluar'],[[group['Viable'],group['Viable con condiciones'],group['No viable'],group['Sin evaluar']]])}<h3>Estados documentales</h3>${rtable(['Estado','Cantidad'],statuses.filter(s=>stateTotals[s]).map(s=>[s,stateTotals[s]]))}<h3>Proyectos seleccionados</h3>${rtable(['N.º','Proyecto','Estado','Viabilidad','Sedes','Paneles/sede','Batería kWh/sede'],rows)}</section>`;
 return clientPage('Resumen integral de empresa',summary+details+'<section><h2>Observaciones</h2><p>La viabilidad es independiente del estado documental. Los escenarios de simulación no equivalen a certificación de instalación. Deben validarse las condiciones de espacio, potencia, conexión, fabricación, protecciones y autonomía.</p><p>Fecha de emisión: '+E(new Date().toLocaleDateString('es'))+'.</p></section>',false);
}
async function companyExportPDF(html){
 if(globalThis.EVEngineeringReports){const bytes=await globalThis.EVEngineeringReports.renderPdf(html);const pdf=Uint8Array.from(bytes);if(pdf.length<5||new TextDecoder().decode(pdf.subarray(0,5))!=='%PDF-')throw Error('El generador de PDF no devolvió un informe válido');return pdf;}
 if(!shared)throw Error('La exportación automática de PDFs integrales requiere iniciar EV Pro Studio con su servidor Python. En modo autónomo, usa imprimir/guardar PDF de cada proyecto; no se generará un ZIP incompleto.');
 let resp=await api('/api/report/render-pdf',{method:'POST',body:JSON.stringify({html})});
 if(!resp.pdf||!/^JVBER/.test(resp.pdf))throw Error('El servidor no devolvió un PDF válido');
 let raw=atob(resp.pdf),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw Error('El PDF devuelto no es válido');return bytes;
}
async function companyExportSelected(c,projects,opts){
 if(shared&&me?.role!=='admin')throw Error('No autorizado');const date=localDateKey();
 if(opts.mode==='supplier'){
  companyExportProgress(12,'Preparando exclusivamente los materiales de los proyectos elegidos…');
  const sites=projects.flatMap(p=>p.sites),raw=supplierExcelRows(sites,true),tokens=companyExportPublicTokens(c,state.projects.filter(p=>p.companyId===c.id)),rows=raw.map(r=>({...r,name:companyExportSanitize(r.name,tokens),spec:companyExportSanitize(r.spec,tokens),siteName:''}));
  if(!rows.length)throw Error('No existen materiales seleccionados para cotizar');
  const code=String(opts.code||'RFQ').replace(/[^A-Za-z0-9_-]/g,'_').slice(0,35);let lot=0;const request=opts.group?rows:projects.flatMap(p=>p.sites.flatMap(st=>{let code='Lote '+(++lot);return supplierExcelRows([st],true).map(r=>({...r,name:companyExportSanitize(r.name,tokens),spec:companyExportSanitize(r.spec,tokens),siteName:code}))}));
  // When not grouping, lot labels are neutral; PDF and Excel do not expose client or project names.
  const printable=clientPage('Solicitud técnica de cotización · '+code,`<section><h2>Solicitud de materiales · ${E(code)}</h2><p>Instalaciones seleccionadas: ${sites.length}. Cantidades pendientes por confirmar: ${request.filter(r=>r.qty===null).length}. Precios unitarios EXW, volumen CBM, garantía, marca, modelo y plazo serán completados por el proveedor.</p><p>Alternativas incluidas solo por selección expresa. No es una orden de compra.</p>${rtable(['N.º',...(opts.group?[]:['Lote']),'Material','Especificación técnica','Unidad','Cantidad'],request.map((r,i)=>[i+1,...(opts.group?[]:[r.siteName]),r.name,r.spec,r.unit,r.qty===null?'Por confirmar':String(r.qty)]))}<p>Solicitar precio EXW/FOB, CBM, peso, tiempos, garantía y compatibilidad por escrito.</p></section>`,false,'',{name:publicIdentity().name,division:'',contact:''});
  companyExportProgress(45,'Convirtiendo solicitud a PDF…');const pdf=await companyExportPDF(printable);
  companyExportProgress(75,'Creando Excel sin datos del cliente…');const xlsx=await supplierExcel(sites,{code,recipient:companyExportSanitize(opts.recipient,tokens),group:opts.group,rows:request}).arrayBuffer();
  let files={'Solicitud_Tecnica_Proveedor.pdf':pdf,'Cotizacion_Editable.xlsx':new Uint8Array(xlsx)};
  companyExportProgress(95,'Empaquetando PDF y XLSX…');download('RFQ_Global_'+code+'.zip',zip(files),'application/zip');companyExportProgress(100,'Solicitud de proveedor completada.');return;
 }
 companyExportProgress(5,'Creando resumen de la empresa…');const summary=await companyExportPDF(companyExportSummaryHTML(c,projects));
 let inner={};const used=new Set();let serial=0;
 for(const p of projects){serial++;let folder=String(serial).padStart(2,'0')+'_'+companyExportCleanName(p.name);let k=1;while(used.has(folder))folder=String(serial).padStart(2,'0')+'_'+companyExportCleanName(p.name)+'_'+(++k);used.add(folder);
  companyExportProgress(8+Math.floor(serial/projects.length*70),'Convirtiendo propuesta integral: '+p.name+' ('+serial+'/'+projects.length+')');
  inner[folder+'/Informe_Actual.pdf']=await companyExportPDF(reportHTML(p));
  if(opts.history){let hist=p.reportHistory||[];for(let [idx,h] of hist.entries()){if(!h.html||typeof h.html!=='string')throw Error('Informe histórico sin contenido: '+p.name);companyExportProgress(8+Math.floor(serial/projects.length*70),'Convirtiendo histórico '+(idx+1)+'/'+hist.length+' · '+p.name);inner[folder+'/Historico/'+String(idx+1).padStart(2,'0')+'_'+companyExportCleanName(h.name||'Revision')+'.pdf']=await companyExportPDF(h.html)}}
 }
 companyExportProgress(87,'Creando ZIP interior de los informes…');const innerArchive=new Uint8Array(await zip(inner).arrayBuffer());
 companyExportProgress(97,'Empaquetando resumen PDF y ZIP de proyectos…');download('Empresa_'+companyExportCleanName(c.name)+'_Resumen_'+date+'.zip',zip({'00_Resumen_General_Empresa.pdf':summary,'01_Informes_de_Proyectos.zip':innerArchive}),'application/zip');companyExportProgress(100,'Expediente empresarial generado correctamente.');
}

